       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"393f893e-040a-5c36-bf2f-b6ef8e07133a","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -نفقة أبناء -املطالبة بالنفقة على ضوء مركز املدعى عليه الوظيفي ووضع األسرة االجتماعي -املطالبة مبصاريف الدراسة -املطالبة مبصاريف العاج -املطالبة بتجديد جوازات سفر األوالد وإعطائها لأم ودفع تذاكر السفر -املطالبة بصورة من دفتر العائلة -املطالبة بفرق النفقة عما دفعة املدعى عليه وعما مت تقديره من قسم اخلبراء -حلف الزوجة على عدم نفقة الزوج -احلكم بدفع فرق النفقة املاضية ودفع النفقة املستقبلية .","document_number":"34268722","case_number":"32151993","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/10/29","year":"1434","subject":"نفقة -نفقة أبناء -املطالبة بالنفقة على ضوء مركز املدعى عليه الوظيفي ووضع األسرة االجتماعي -املطالبة مبصاريف الدراسة -املطالبة مبصاريف العاج -املطالبة بتجديد جوازات سفر األوالد وإعطائها لأم ودفع تذاكر السفر -املطالبة بصورة من دفتر العائلة -املطالبة بفرق النفقة عما دفعة املدعى عليه وعما مت تقديره من قسم اخلبراء -حلف الزوجة على عدم نفقة الزوج -احلكم بدفع فرق النفقة املاضية ودفع النفقة املستقبلية .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/10/29 :‬هـ‬\n                        ‫ُ‬                 ‫َر ْق ُم َّ‬\n                            ‫الص ِّك‪34268722 :‬‬\n                           ‫َر ْق ُم الدعوى‪32151993 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34361404‬تاريخه‪1434/11/18 :‬هـ‬\n\n\n        ‫نفقــة ‪ -‬نفقــة أبنــاء ‪ -‬املطالبــة بالنفقــة علــى ضــوء مركــز املدعــى‬\n        ‫عليــه الوظيفــي ووضــع األســرة االجتماعــي‪ -‬املطالبــة مبصاريــف‬\n        ‫الدراســة‪ -‬املطالبــة مبصاريــف العــاج‪ -‬املطالبــة بتجديــد جــوازات‬\n        ‫ســفر األوالد وإعطائهــا لــأم ودفــع تذاكــر الســفر‪ -‬املطالبــة بصــورة‬\n        ‫مــن دفتــر العائلــة‪ -‬املطالبــة بفــرق النفقــة عمــا دفعــة املدعــى عليــه‬\n        ‫وعمــا مت تقديــره مــن قســم اخلبــراء‪ -‬حلــف الزوجــة علــى عــدم نفقــة‬\n        ‫الــزوج‪ -‬احلكــم بدفــع فــرق النفقــة املاضيــة ودفــع النفقــة املســتقبلية ‪.‬‬\n\n\n\n\n                  ‫‪ -1‬قوله تعالى ( وعلى املولود له رزقهن وكسوتهن باملعروف)‬\n                   ‫‪ -2‬قوله صلى اهلل عليه وسلم ( ابدأ بنفسك ثم مبن تعول)‬\n        ‫‪ -3‬قــال يف كشــاف القنــاع ( ويجــب عليــة أيضـ ًا نفقــة ولــده وإن ســفل‪.‬‬\n        ‫وألن النفقــة واجبــة علــى اإلنســان علــى نفســه وزوجتــه فكــذا هي واجبة‬\n                                                                ‫علــى بعضــه وأصلــه )‬\n        ‫‪ -4‬قــال يف الشــرح الكبيــر( ويلزمــه نفقــة ســائر آبائــه وإن علــو وأوالده‬\n                                                                          ‫وإن ســفلوا)‬\n        ‫‪ -5‬قــال يف شــرح منتهــى اإلرادات ( فيجــب إعفــاف مــن جتــب نفقتــه مــن‬\n        ‫اآلبــاء واألجــداد واألوالد واألخــوة واألعمــام ويقــدم إن ضــاق الفاضــل‬\n                                                                   ‫األقــرب فاألقــرب )‬\n\n‫‪299‬‬\n\f‫ادعــى املدعــي وكالــة بــأن موكلتــه كانــت زوجــه للمدعــى عليــه‬\n‫وأجنبــت منــه ابنــن ( ذكــر أســماءهما وأعمارهمــا ) وقــد فارقهــا وهــو‬\n‫ينفــق عليهمــا تســعمائة ريــال وهــو ال يكفــي‪ -‬طلــب املدعــى وكالــة‬\n‫نفقــة الولديــن املذكوريــن مــع مصاريــف الدراســة ومصاريــف العــاج‬\n‫علــى ضــوء مركــز املدعــى عليــه الوظيفــي ووضــع األســرة االجتماعــي‪-‬‬\n‫مطالبــة املدعــى عليــه بتجديــد جــوازات الســفر حــال انتهائهــا وتســليمها‬\n‫لوالدتهمــا وإعطائهــا إذن بالســفر ودفــع تذاكــر الســفر حال ســفرهم أو‬\n‫يلتــزم بأخــذ األوالد عنــد ســفر والدتهــم‪ -‬أقــر املدعــى عليــه وكالــة بــأن‬\n‫موكلــة ينفــق تســعمائة ريــال شــهري ًا لــكل ابــن ‪ 450‬ريــال حتــى شــهر‬\n‫ذي احلجــة عــام ‪1433‬ه ـ وأن ســبب إقامــة الدعــوى تلطيــخ ســمعة موكلــة‬\n‫وابتــزازه مادي ـ ًا ‪ -‬ورد جــواب مكتــب الصلــح املتضمــن تعــذر الصلــح‬\n‫وتقديــر نفقــة كل ابــن شــهري ًا بألــف ومائتــي ريــال ‪ -‬طلــب املدعــي‬\n‫وكالــة إلــزام املدعــى عليــه بتســليم الفــرق بــن مــا كان يدفعــه وبــن مــا‬\n‫مت تقديــره ‪ -‬قــرر املدعــى عليــه بأنــه حصــل اتفــاق شــفوي علــى أن نفقــة‬\n‫االبنــن الشــهرية ‪ 900‬ريــال ‪ -‬أنكــر املدعــي وكالــة هــذا الدفــع وقــرر‬\n‫أن موكلتــه تنفــق علــى ابنيهــا املبلــغ الزائــد ‪ 900‬ريــال بنيــة الرجــوع‪-‬‬\n‫قــرر املدعــى عليــه أنــه يطلــب ميــن املدعيــة علــى أنهــا أنفقــت علــى أبنيــة‬\n‫نفقــة زائــدة عمــا ســلمه لهــا بنيــة الرجــوع وعلــى نفــي االتفــاق الشــفوي‬\n‫املذكــور ‪ -‬حلفــت املدعيــة أصالــة اليمــن كمــا طلــب منهــا ‪ -‬لقولــه‬\n‫تعالــى ( وعلــى املولــود لــه رزقهــن وكســوتهن باملعــروف) وقولــه صلــى‬\n‫اهلل عليــه وســلم ( ابــدأ بنفســك ثــم مبــن تعــول) وملــا ذكــره أهــل العلــم‬\n\n                                                                                        ‫‪300‬‬\n\f      ‫مــن وجــوب نفقــة األب علــى أوالدة لــذا صــدر احلكم بإلــزام املدعى عليه‬\n      ‫بدفــع فــرق النفقــة الســابقة علــى ابنــه للمدعيــة ( وذكــر مقــدار املبلــغ) ‪-‬‬\n      ‫وإلــزام املدعــى عليــه بدفــع نفقــة مســتقبلية لالبنــن كل شــهر وهــو مبلــغ‬\n      ‫ألفــان وأربعمائــة ريــال لــكل واحــد ألــف ومائتــي ريــال تســلم للمدعيــة‬\n      ‫بالتحويــل إلــى حســابها وفقــا ملــا مت تقديــره مــن قســم اخلبــراء ‪ -‬لــم يقنــع‬\n            ‫املدعــى عليــه باحلكــم‪ -‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالريــاض برقــم ‪ 32151993‬وتاريــخ ‪1432/05/01‬ه ـ املقيــدة‬\n      ‫باحملكمة برقم ‪ 32478496‬وتاريخ ‪1432/05/01‬هـ ففي يوم الثالثاء‬\n      ‫املوافق‪1433/05/18‬ه ـ افتتحــت اجللســة وفيهــا ‪...‬يحمــل الســجل املدنــي‬\n      ‫رقــم ‪ ...‬وكيــا عــن ‪ ...‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل‬\n      ‫الثانيــة بالريــاض رقــم ‪ 58859‬وتاريــخ ‪1432/08/08‬ه ـ واملتضمنــة بــأن‬\n      ‫لــه حــق املرافعــة و املدافعــة واملخاصمــة وإقامــة الدعــاوى وحــق ســماع‬\n      ‫الدعــاوى والــرد عليهــا واإلقــرار واإلنــكار و الصلــح وطلــب وقبــول‬\n      ‫احلكــم ونفيــه واالعتــراض عليــه وطلــب متييــزه ولــم يحضــر املدعــى عليــه‬\n      ‫ولــم يظهــر تبلغــه ويف جلســة أخــرى بتاريــخ ‪1433/10/14‬ه ـ حضــر‬\n      ‫املدعــي وكالــة احلاضــر يف اجللســة املاضيــة‪ ،‬ولــم يحضــر املدعــى عليــه‬\n      ‫وقــد اعتــذر عــن حضــور هــذه اجللســة‪ ،‬وبســؤال املدعــي وكالــة عــن‬\n      ‫دعــواه قــال‪ :‬لقــد كانــت موكلتــي زوجــة للمدعــى عليــه ‪ ...‬حيــث عقــد‬\n\n‫‪301‬‬\n\f‫عليهــا يف عــام ‪1420‬ه ـ وأجنبــت منــه علــى فــراش الزوجيــة كل مــن‪:‬‬\n‫‪...‬املولــود يف ‪1427/4/4‬ه ـ ‪... ،‬املولــود يف ‪1430/1/8‬ه ـ وقــد فارقهــا‬\n‫أول هــذه الســنة ‪1433‬هــ‪ ،‬وهــو ينفــق عليهــم مبلــغ تســعمائة ريــال كل‬\n             ‫شــهر وهــو ال يكفــي‪ ،‬ولــذا فــإن موكلتــي تطالــب باآلتــي ‪:‬‬\n                                         ‫‪ -1‬نفقة أوالدها املذكورين ‪ ...‬و ‪....‬‬\n‫وتشــمل النفقــة املــأكل واملشــرب واملســكن ونفقــة املالبــس صيف ـ ًا‬\n‫وشــتاء واألعيــاد ومناســبات األفــراح‪ ..‬وأجــرة احلضانــة لرعايتهــم وتدبيــر‬\n‫شــؤونهم حيــث إن والدتهــم تبحــث عــن عمــل وجدتهــم طاعنــة يف الســن‬\n‫وتعانــي مــن أمــراض مزمنــة وهــم بحاجــة إلــى رعايــة أثنــاء غيــاب والدتهم‬\n‫وتطلــب أن تكــون النفقــة علــى ضــوء مركــز املدعــى عليــه الوظيفــي‬\n‫و الوضــع االجتماعــي لــه ولهــا حيــث أنهمــا مــن أســرتني مرموقتــن‬\n                                                                     ‫اجتماعي ـاً‪.‬‬\n‫‪ -2‬تطالــب بإلــزام املدعــى عليــه بدفــع مصاريــف الدراســة (املســتلزمات‬\n‫الدراســية ورســوم الدراســة والنقــل املدرســي) حســبما يقــدره هيئــة‬\n‫اخلبــراء ‪ .‬أو يلتــزم بتدريســهم مبعرفتــه يأخذهــم صباحــا ويعيدهــم بعــد‬\n                                                         ‫اخلــروج مــن املدرســة ‪.‬‬\n‫‪ -3‬مصاريــف العــاج بحيــث يلتــزم بدفــع فواتير العــاج يف حال حاجتهم‬\n                    ‫إلــى طبيــب خــاص أو يلتــزم بأخذهــم للطبيب وإعادتهم ‪.‬‬\n‫‪ -4‬إلــزام املدعــى عليــه بتجديــد جــوازات ســفر األوالد حــال انتهائهــا‬\n‫‪-‬حيــث أن لهــم جــوازات‪ -‬وتســليمها لوالدتهــم وإعطائهــم إذن بالســفر‬\n‫ودفــع تذاكــر الســفر حــال ســفرهم حيــث أن موكلتــي تقــوم بالســفر‬\n‫مــع أهلهــا إلــى أقاربهــم خــارج اململكة ‪ .‬أو يلتــزم بأخذ األوالد عنده عند‬\n‫ســفر والدتهــم هــذه دعــواي‪ .‬ويف جلســة أخــرى بتاريــخ ‪1434/02/24‬ه ـ‬\n\n\n                                                                                     ‫‪302‬‬\n\f      ‫حضــر املدعــي وكالــة احلاضــر ســابقا كمــا حضــر ‪ ...‬حامــل بطاقــة‬\n      ‫الهويــة الوطنيــة رقــم ‪ ...‬وكيــا عــن ‪ ...‬بالوكالــة رقــم ‪34217943‬‬\n      ‫وتاريــخ ‪1434/2/23‬ه ـ الصــادرة مــن كتابــة عــدل جنــوب الريــاض‬\n      ‫وبســؤاله عــن جوابــه عــن دعــوى املدعــي قــال صحيــح بــأن املدعيــة‬\n      ‫كانــت زوجــة ملوكلــي و قــد طلقهــا و بانــت منــه و أجنبــت لــه ولديــن ‪...‬‬\n      ‫املولــود ‪1427/4/4‬ه ـ ‪ ...‬املولــود ‪1430/1/8‬ه ـ و هــو ينفــق علــى ابنيــه‬\n      ‫نفقتــه الشــهرية قدرهــا ‪900‬ريــال لالبنــن لــكل واحــد ‪ 450‬ريــال حتــى‬\n      ‫شــهر ذي احلجــة عــام ‪1433‬ه ـ هكــذا أجــاب كمــا أبــرز مذكــرة‬\n      ‫وطلــب رصدهــا و هــذا نصهــا (إشــارة إلــى الدعــوى املقامــة مــن املدعيــة‬\n      ‫‪ ...‬ض ــد موكلــي ‪ ...‬واملنظــورة أمــام فضيلتكــم‪ ،‬أفيدكــم حفظكــم‬\n      ‫اهلل أن هــذه الدعــوى ليســت مقصــودة لذاتهــا وإمنــا قصــد بهــا أمران‪:‬ـ ـ‬\n      ‫األمــر األول‪ :‬تلطيــخ ســمعة موكلــي برفــع الدعــاوى عليــه باحملاكــم ‪،‬‬\n      ‫وأيضـ ًا ســمعته يف عملــه وأنــه صاحــب مشــاكل لدرجــة أنــه قـ ّـدم تقاعــد‬\n      ‫مبكــر مــن عملــه ‪ ،‬ومــا يثبــت ذلــك أنهــم يأتــون إليــه يف عملــه بطلبــن‬\n      ‫إلبالغــه عــن موعــد جلســة واحــدة فقــط ‪ ،‬فعلــى مــاذا يــدل ذلــك ؟ علمـ ًا‬\n      ‫أنهــم يعرفــون منزلــه فبإمكانهــم توصيــل طلــب احلضــور لــه يف بيتــه‪،‬‬\n      ‫واملــازم لديكــم الشــيخ ‪ ...‬وجــه للمدعيــة ووالدهــا خطــاب بعــدم إزعــاج‬\n      ‫املدعــى عليــه أو التعــرض لــه بــاألذى ‪ ،‬ومــع ذلــك لــم يبالــوا ولــم يكترثوا‬\n      ‫بــكالم املــازم‪ ،‬وضربــوا بــه عــرض احلائــط ‪ ،‬واســتمروا يف اإليــذاء‬\n      ‫واإلزعــاج‪ .‬األمــر الثانــي ‪ :‬إبتــزاز موكلــي وإســتنزافه مادي ـ ًا ومعنوي ـ ًا‬\n      ‫أن موكلــي مســتمر يف النفقــة لولديــه (‪ ...‬و ‪)......‬‬  ‫قــدر املســتطاع حيــث ّ‬\n      ‫ويدفــع لهــم شــهري ًا تســعمائة ريــال ( ‪ 900‬ريــال ) يحولهــا يف حســاب‬\n      ‫والدتهــم مبصــرف ‪ ...........‬ولدينــا كشــف بذلــك ‪ ،‬ثــم طلبــت والدتهــم‬\n\n\n‫‪303‬‬\n\f‫أســرة فاخــرة لولديــه فاشــترى لهــم ذلــك وأرســلها لهــم يف بيــت أهلهــا‪،‬‬\n‫أمــا مســألة التوصيــل إلــى املدرســة فالعــام املاضــي لــم تطلــب املدعيــة‬           ‫ّ‬\n‫ـأن املدرســة قريبــة جــد ًا مــن‬  ‫نفقــات توصيــل اإلبــن للمدرســة‪ ،‬علم ـ ًا بـ ّ‬\n‫البيــت‪ ،‬وأيضـ ًا عنــد أهلهــا ثالثــة ســائقني وكلهــم يذهبــون كل صبــاح‬\n‫بأطفالهــم وأوالدهــم إلــى املــدارس وإبنــي علــى طريقهــم كل يــوم ليــس‬\n‫مما‬ ‫لــه مشــوار خــاص أو طريــق خــاص غيــر طريــق الســائق كل صبــاح‪ّ ،‬‬\n‫أن القصــد مــن الدعــوى اإلبتــزاز واإليــذاء ليــس إالّ‪ .‬ويؤيــد مــا‬       ‫يــدل علــى ّ‬\n‫أن املدعية طلبت مرة من موكلي مبلغ ًا من املال لتعيني‬                     ‫ذكرته لكم ّ‬\n‫ـاء لشــرها وكــف أذاهــا حـ ّـول لهــا مبلغـ ًا‬   ‫مــن ينقــل إبنهمــا للمدرســة فإتقـ ً‬\n‫فلمــا حـ ّـول لهــا املبلــغ لتعيــن‬\n                                  ‫لتعيــن مــن ينقــل االبــن ـ ـ علــى حـ ّـد زعمهــا ـ ـ ّ‬\n‫ا‬ ‫ألن االبــن أصـ ً‬  ‫مــن ينقــل اإلبــن أكلــت املــال ولــم تعــن مــن ينقــل اإلبــن‪ّ ،‬‬\n‫يذهــب مــع ســائقهم‪ ،‬فليــس املقصــود مــن الدعــوى أساس ـ ًا إ ّال األذى‬\n‫واإلبتــزاز بــكل مــا تســتطيع‪ .‬لــذا أطلــب مــن فضيلتكــم صــرف النظــر‬\n‫عــن دعــوى املدعيــة حيــث يتضــح لكــم مــن خــال اإلطــاع علــى األوراق‬\n‫واملســتندات أنهــا دعــوى كيديــة‪ .‬نســأل اهلل العافيــة والســامة )أ‪.‬ه ـ‬\n‫وبعــرض ذلــك علــى املدعــي وكالــة قــال بالنســبة إلقامــة الدعــوى فليــس‬\n‫فيهــا تلطيــخ للســمعته كمــا ذكــر املدعــى عليهــا ولــم يحصــل ملوكلتــي‬\n‫إزعــاج لــه وبالنســبة لبــاغ احلضــور الــذي ذكــر فــإن وكيــل املدعيــة‬\n‫‪...‬ذهــب للمدعــى عليــه يف املدرســة وعندمــا ســلمه طلــب احلضــور طلــب‬\n‫منــه أخــذ مصادقــة رئيســة ومديــره علــى البــاغ فرفــض املدعــى عليــه‬\n‫ذلــك فــرأى الوكيــل الســابق أن يرســل البــاغ لــه عــن طريــق احملضريــن‬\n‫فــكان ذلــك وليــس يف ذلــك شــيء وأمــا االبتــزاز فليــس هنالــك إبتــزاز‬\n‫ولكــن املبلــغ الــذي يدفعــه املدعــى عليــه وهــو أربعمائــة وخمســون ريــاال‬\n\n\n                                                                                               ‫‪304‬‬\n\f      ‫لــكل طفــل فقليــل جــدا وهــو ال يغطــي راتــب اخلادمــة التــي تقــوم بخدمــة‬\n      ‫الصغــار كــون موكلتــي تبحــث عــن عمــل وقدمــت علــى عــدة جهــات‬\n      ‫وتنتظــر الــرد منهــم وقــد يكــون العمــل مســائي واملدعيــة ليس لها ســلطة‬\n      ‫علــى ســائق أهلهــا واملدعــى عليــه لــم يصــرف علــى أوالدة مــن بدايــة عــام‬\n      ‫‪1434‬ه ـ وموكلتــي تطالــب املدعــى عليــه بإعطائهــا صــورة مــن دفتــر‬\n      ‫العائلــة حلاجتهــا لــه وموكلتــي مصــرة علــى دعواهــا كمــا أن املدعــى‬\n      ‫عليــه ينفــق علــى ابنيــه نفقــة شــهرية لــكل واحــد منهمــا ‪ 450‬ريــال و قــد‬\n      ‫انقطــع عــن النفقــة عليهمــا بنهايــة شــهر ذي احلجــة عــام ‪1433‬ه ـ هكــذا‬\n      ‫أجــاب هــذا وقــد قــررت الكتابــة لقســم اخلبــراء لتقديــر النفقــة البنــي‬\n      ‫املدعــى عليــه مــن املدعيــة ويف جلســة أخــرى بتاريــخ ‪1434/04/22‬ه ـ‬\n      ‫حضــر املدعــي وكالــة ‪ ...‬احلاضــر يف جلســة ســابقة كمــا حضــر‬\n      ‫املدعــى عليــه ‪...‬يحمــل الســجل املدنــي رقــم ‪...‬يف اجللســة الســابقة وقــد‬\n      ‫وردنــا قــرار مكتــب الصلــح برقــم ‪ 246‬وتاريــخ ‪1434/04/01‬ه ـ و‬\n      ‫املتضمــن (عليــه نفيــد فضيلتــه انــه مت االجتمــاع بالطرفــن وقــد تعــذر‬\n      ‫الصلــح بينهمــا بخصــوص تقديــر النفقــة حيــث ذكــرت املدعيــة بأنهــا‬\n      ‫تطالــب نفقــة أبنائهــا ‪ ...‬و‪ ...‬وأن املدعــى عليــه لــم ينفــق عليهــم النفقــة‬\n      ‫التــي تكفيهــم وأنــه مــن ثالثــة أشــهر لــم يســلمهم أي شــيء وترغــب‬\n      ‫أن تكــون النفقــة شــاملة للســكن واملواصــات والعــاج إلــى آخــر مــا‬\n      ‫ذكــرت بإقرارهــا املرفــق أمــا بالنســبة للمدعــى عليــه فقــد ذكــر بأنــه‬\n      ‫كان يف الســابق ينفــق علــى أوالده بواقــع ‪ 350‬ريــال شــهري ًا لــكل واحــد‬\n      ‫منهــم إلــى ‪ 500‬ريــال شــهري ًا ويقــوم بالزيــادة أحيانــا وأنــه يوجــد عليــه‬\n      ‫أقســاط شــهريه تصــل إلــى ‪ 7000‬ريــال حيــث يســلم لوالــده ‪ 3500‬ريــال‬\n      ‫وكذلــك ‪1833‬ريــال شــهري ًا وهــي قيمــة شــراء أرض وكذلــك يوجــد‬\n\n\n‫‪305‬‬\n\f‫عليــه قســط ‪1667‬ريــال لصالــح صنــدوق التنميــة إلــى آخــر مــا ذكــره‬\n‫بإقــراره املرفــق وبنــاء علــى ذلــك واحلــال كمــا ذكــر وبعــد اإلطــاع علــى‬\n‫الوضــع املــادي للمدعــى عليــه حيــث أتضــح أنــه يتقاضــى معــاش تقاعــدي‬\n‫وقــدره ‪ 11684‬ريــال حســب اخلطــاب املرفــق رقــم ‪ 12454‬وتاريــخ‬\n‫‪1434/03/17‬ه ـ الصــادر مــن املؤسســة العامــة للتقاعــد وأن املدعــى‬\n‫عليــه لــم يثبــت األقســاط املســتحقة مــن أي جهــة معتبــره فإننــا نــرى أن‬\n‫تكــون نفقــة أبنــاء املدعيــة ‪1200‬ريــال شــهري ًا لــكل واحــد منهــم شــاملة‬\n‫الســكن وكذلــك املواصــات هــذا مــا لدينــا) أ‪.‬ه ـ وقــد طلــب املدعــي‬\n‫وكالــة تعديــل دعــواه قائــا أطلــب احلكــم علــى املدعــى عليــه بــأن يســلم‬\n                     ‫النفقــة املســتقبلية ابتــداء مــن تاريــخ ‪1434/04/25‬ه ـ‬\n‫وكذلــك إلــزام املدعــى عليــه بتســليم الفــرق بــن مــا يســلمه املدعــى‬\n‫عليــه وبــن مــا يحكــم بــه خــال الفتــرة مــن شــهر جمــادى األولــى مــن‬\n‫عــام ‪1431‬ه ـ وحتــى تاريــخ ‪1434/04/25‬ه ـ فهــو لــم يســلم خــال الفترة‬\n‫الســابقة ســوى ‪ 900‬ريــال نفقــه لولديــة شــهري ًا أمــا األشــهر األربعة محرم‬\n‫و صفــر وربيــع األول و ربيــع الثانــي فلــم يســلم أي مبلــغ ســوى ‪ 500‬ريــال‬\n‫هكــذا طلــب وبعــرض ذلــك علــى املدعــى عليــه قــال صحيــح مــا ذكــرة‬\n‫املدعــي وكالــة بأننــي كنــت أنفــق علــى ابنــي مببلــغ مجموعــة ‪ 900‬ريال‬\n‫شــهري ًا لــكال اإلبنــن مــن شــهر جمــاد األولــى عــام ‪1431‬ه ـ حتــى نهايــة‬\n‫شــهر ذي احلجــة عــام ‪1433‬ه ـ وقــد قطعــت النفقــة عليهمــا لرفــع الدعــوى‬\n‫مــن املدعيــة ولــم أنفــق علــى ابنــي منــذ بدايــة هــذا العــام ســوى ‪ 500‬ريــال‬\n‫ولــن اســلم فــرق النفقــة الســابقة ألن النفقــة املســلمة لهــم كافيــة ولــم‬\n‫يقيمــوا هــذه الدعــوى اإل كيــدا مــن املدعيــة بســب موضــوع الطــاق‬\n‫وكذلــك لــن أســلم النفقــة الالحقــة ســوى مبلــغ ‪ 300‬ريــال لــكل ابــن‬\n\n\n                                                                                        ‫‪306‬‬\n\f      ‫أســوة ببقيــة األحــكام األخــرى قــد حصــل أتفــاق شــفوي يف شــهر صفــر‬\n      ‫عــام ‪1433‬ه ـ علــى نفقــه شــهرية ‪ 900‬ريــال ولــم تطلب أجرة الســكن يف‬\n      ‫صحيفــة الدعــوى هكــذا أجــاب وبعــرض ذلــك علــى املدعــي وكالة قال‬\n      ‫لــم يحصــل اتفــاق بــن موكلتــي و املدعــى عليــه بــأن تكــون النفقــة ‪900‬‬\n      ‫ريــال العــام املاضــي وغيــر صحيــح أنهــا كيديــه هكــذا أجــاب وبعــرض‬\n      ‫مــا جــاء يف قــرار قســم اخلبــراء رفــض املدعــي وكالــة مــا جــاء فيــه وقــال‬\n      ‫أطلــب أن يكــون تقديــر النفقــة لــكل أبــن ‪ 2000‬ريــال هكــذا أجــاب‬\n      ‫كمــا رفــض املدعــى عليــه مــا جــاء يف قرار قســم اخلبراء وقــال أنه تقدير‬\n      ‫مرتفــع جــد ًا هكــذا أجــاب وبســؤال املدعــي وكالــة هــل موكلتــه تنفــق‬\n      ‫علــى أبنيهــا مــن املدعــى عليــه املبلــغ الزائــد عــن ‪ 900‬ريــال بنيــة الرجــوع‬\n      ‫فقــال هــي تنفــق حســب قولهــا بنيــة الرجــوع علــى املدعــى عليــه هكــذا‬\n      ‫أجــاب وبعــرض ذلــك علــى املدعــى عليــه قــال أطلــب ميــن املدعــى عليهــا‬\n      ‫علــى ذلــك بأنهــا أنفقــت علــى ابنــي نفقــة زائــدة عمــا أســلمه لهــا بنيــة‬\n      ‫الرجــوع علــي مــن تاريــخ جمــادي األول عــام ‪1431‬ه ـ وحتــى تاريــخ هــذا‬\n      ‫اليــوم هكــذا طلــب فاســتعد املدعــى وكالــة بإبــاغ موكلتــه باحلضــور‬\n      ‫اجللســة القادمــة ألداء اليمــن املطلوبــة كمــا طلــب املدعــى عليــه مهلــه‬\n      ‫إلحضــار بينتــه علــى االتفــاق وبــن املدعيــة بــأن تكــون النفقــة ‪900‬ريــال‬\n      ‫من تاريخ صفر عام ‪1433‬هـ ويف جلســة أخرى بتاريخ ‪1434/06/25‬هـ‬\n      ‫حضــر املدعــى عليــه أصالــة‪ ،‬ولــم حتضــر املدعيــة وال مــن ميثلهــا ‪،‬‬\n      ‫وبســؤال املدعــي عليــه عــن بينتــه التــي وعــد بهــا‪ ،‬قــال ‪ :‬ليــس لــدي ســوى‬\n      ‫االتفــاق الشــفهي بيننــا ‪ ،‬وبســؤاله هــل لديــه زيــادة بينــة‪ ،‬فقــال‪ :‬ال ويف‬\n      ‫جلســة أخــرى بتاريــخ ‪1434/07/12‬ه ـ حضــرت املدعيــة ووكيلهــا ‪...‬و‬\n      ‫املدعــى عليــه ‪...‬احلاضــرون يف اجللســة الســابقة ‪ ،‬وقــد قــررت املدعيــة‬\n\n\n‫‪307‬‬\n\f‫أنهــا اســتلمت مؤخــرا مــن املدعــى عليــه مبلغــا وقــدره ألفــان وأربعمائــة‬\n‫ريــال وتطلــب حســمه ممــا تطلبــه مــن املدعــي عليــه‪ ،‬وتطلــب حتويــل‬\n‫النفقــة املســتقبلية علــى حســابها يف مصــرف الراجحــي رقــم ‪ ...‬هكــذا‬\n‫طلبــت وقــد مت محاولــة الصلــح بــن الطرفــن إال أنــه لــم يتوصــل إلــى‬\n‫حــل مــرض بينهمــا ‪ ،‬وقــد طلــب املدعــي عليــه ميــن املدعيــة علــى نفــي‬\n‫االتفــاق يف شــهر صفــر عــام ‪1433‬ه ـ بــأن تكــون نفقــة األبنــاء ‪900‬ريــال‬\n‫كمــا طلــب ميينهــا علــى أنهــا أنفقــت علــى ابنيــه منهــا نفقــة زائــدة عمــا‬\n‫ســلمه لهــا وبنيــة الرجــوع مــن تاريــخ جمــادى األول عــام ‪1431‬ه ـ وحتــى‬\n‫تاريــخ هــذا اليــوم ‪ ،‬وبعــرض ذلــك علــى املدعيــة قالــت ال مانــع لــدي‬\n‫مــن أداء اليمــن فاســتعدت باحللــف ‪ ،‬فأذنــت لهــا‪ ،‬فحلفــت قائلــة‪« :‬‬\n‫واهلل العظيــم بأننــي قــد أنفقــت علــى ابنــي املدعــى عليــه ‪...‬و‪ ...‬منــي‬\n‫بنيــة الرجــوع علــى املدعــى عليــه مــن شــهر جمــادى األولــى عــام ‪1431‬ه ـ‬\n‫وحتــى تاريــخ هــذا اليــوم وقــد أنفقــت عليهمــا بأكثــر مــن تســعمائة‬\n‫ريــال شــهريا وأننــي لــم أتفــق مــع املدعــى عليــه يف نهايــة شــهر صفــر عــام‬\n‫‪1433‬ه ـ بــأن تكــون نفقــة األبنــاء تســعمائة ريــال» هكــذا حلفــت فبنــاء‬\n‫علــى مــا تقــدم مــن الدعــوى واإلجابــة ‪ ،‬وألداء املدعيــة اليمــن املطلوبــة‬\n‫منهــا ‪ ،‬ولقولــه تعالــى‪( :‬وعلــى املولــود لــه رزقهــن وكســوتهن باملعــروف)‬\n‫ولقــول الرســول الكــرمي صلــى اهلل عليــه وســلم‪( :‬ابــدأ بنفســك ثــم مبــن‬\n‫تعــول) وملــا ذكــره الفقهــاء يرحمهــم اهلل فقــد جــاء يف كشــاف القنــاع‬\n‫(ويجــب عليــه أيضــا نفقــة ولــده وإن ســفل ‪ ...‬وألن النفقــة واجبــة علــى‬\n‫اإلنســان علــى نفســه وزوجتــه فكــذا هــي واجبــة علــى بعضــه وأصلــه)‬\n                                                       ‫وقــال يف الشــرح الكبيــر‬\n‫(ويلزمــه نفقــة ســائر آبائــه وإن علــوا وأوالده وإن ســفلوا) وقــال يف شــرح‬\n\n\n                                                                                       ‫‪308‬‬\n\f      ‫املنتهــى ‪( :‬فيجــب إعفــاف مــن جتــب نفقتــه مــن اآلبــاء واألجــداد واألوالد‬\n      ‫واإلخــوة واألعمــام ويقــدم إن ضــاق الفاضــل األقــرب فاألقــرب) ومبــا أن‬\n      ‫املدعيــة طالبــت بالنفقــة الســابقة مــن جمــادى األولى عــام ‪1431‬هـ وحتى‬\n      ‫تاريــخ ‪1434/06/25‬ه ـ واملســتقبلية‪ ،‬وملــا جــاء يف تقريــر قســم اخلبــراء‬\n      ‫بــأن النفقــة لالبنــن شــهرية تقــدر مببلــغ وقــدره ألفــان وأربعمائــة ريــال‬\n      ‫والتــي يكــون مجمــوع النفقــة الســابقة مبلــغ وقــدره واحــد وتســعون ألفــا‬\n      ‫ومائتــا ريــال ‪ ،‬وحيــث دفــع املدعــى عليــه نفقــة لتلــك الفتــرة مجموعهــا‬\n      ‫مبلــغ وقــدره واحــد وثالثــون ألفــا وســبعمائة ريــال وعليــه فحكمــت‬\n      ‫مبــا يلــي ‪ :‬أوال ‪ :‬ألزمــت املدعــى عليــه بدفــع النفقــة الســابقة علــى ابنيــه‬\n      ‫للمدعيــة وهــو مبلــغ وقــدره تســعة وخمســون ألفــا وخمســمائة ريــال‪ .‬ثانياً‪:‬‬\n      ‫ألزمــت املدعــى عليــه بدفــع نفقــة مســتقبلية لالبنــن كل شــهر وهــو‬\n      ‫مبلــغ وقــدره ألفــان وأربعمائــة ريــال لــكل واحــد ألــف ومائتــي ريــال ‪.‬‬\n      ‫تســلم للمدعيــة بالتحويــل إلــى حســابها يف مصــرف الراجحــي املذكــور‬\n      ‫أعــاه مــن تاريــخ ‪1434/07/25‬ه ـ وبإعــان احلكــم علــى املدعية قررت‬\n      ‫قناعتهــا بــه و قــرر املدعــى عليــه عــدم القناعــة فاســتعد بتقــدمي الئحتــه‬\n      ‫االعتراضيــة و أفهــم بــأن لــه مــدة ثالثــن يومــا تبــدأ مــن تاريــخ اســتالمه‬\n      ‫نســخة احلكــم وهــو يــوم الثالثــاء ‪1434/07/18‬ه ـ يقــدم خاللــه الئحته‬\n      ‫االعتراضيــة وأنــه يف حالــة انتهــاء املــدة و لــم يقــدم خاللهــا الئحتــه‬\n      ‫االعتراضيــة فإنــه يســقط حقــه يف االعتــراض علــى احلكــم و يكتســب‬\n      ‫احلكــم القطعيــة‪ ،‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                  ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/07/12‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء ‪1434/10/27‬ه ـ افتتحــت‬\n      ‫اجللســة و قــد وردتنــا املعاملــة مــن رئيــس محكمــة االســتئناف بكتابــه‬\n\n\n‫‪309‬‬\n\f‫ذي الرقــم ‪ 342126052‬يف ‪1434/09/17‬ه ـ املرفــق بــه قــرار الدائــرة‬\n‫الثانية املختصة بنظر قضايا األحوال الشــخصية واالنهاءات مبحكمة‬\n‫االســتئناف بالريــاض برقــم ‪ 34318434‬وتاريــخ ‪1434/09/14‬ه ـ ونــص‬\n‫احلاجــة منــه ‪( :‬وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n‫وأوراق املعاملــة لوحــظ أن مــا قــدر مــن النفقــة املاضيــة كثيــر فعلــى‬\n‫فضيلتــه الكتابــة إلــى هيئــة اخلبــراء باحملكمــة إلعــادة النظــر يف ذلــك‬\n‫وتقديــر النفقــة علــى قــدر ســعة املنفــق لقولــه تعالــى ((لينفــق ذو ســعة مــن‬\n‫ســعته ومــن قــدر عليــه رزقــه فلينفــق ممــا آتــاه اهلل ال يكلــف اهلل نفســا‬\n‫إال مــا آتاهــا ســيجعل اهلل بعــد عســر يســرا)) واهلل املوفق)ا‪.‬ه ـ وإجابــة‬\n‫علــى مــا ذكــره أصحــاب الفضيلــة أقــول وبــاهلل التوفيــق ‪ :‬إن النفقــة‬\n‫التــي مت تقديرهــا شــاملة لنفقــة الســكن واملــأكل واملشــرب وامللبــس‬\n‫ومــا يلــزم ومــن املعلــوم أن املســاكن املســتأجرة وأقلهــا يف العــرف ملــن‬\n‫هــو مثــل حــال املتداعيــن شــقة والشــقق ال تقــل أجــرة املتوســط منهــا‬\n‫عــن عشــرين ألــف ريــال للســنة الواحــدة ونفقــة األبنــاء مــن ألــزم مــا يجــب‬\n‫علــى اآلبــاء ومــا قــدر مــن مبلــغ مــن ســعة احملكــوم عليــه بــه ومــن وجــده‬\n‫لذلــك كلــه لــم يظهــر لــي خــاف مــا حكمــت بــه وقــررت إعــادة املعاملــة‬\n‫حملكمــة االســتئناف وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n                             ‫وآلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/10/27‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم االثنــن املوافــق ‪ 1434/12/23‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 11 : 30‬هــذا و قــد وردتنــا املعاملــة مــن‬\n‫رئيــس محكمــة االســتئناف بكتابــه ذي الرقــم ‪ 342460670‬يف‬\n‫‪ 1434/11/27‬ه ـ املرفــق بــه القــرار الصــادر مــن دائــرة األحــوال‬\n‫الشــخصية الثانيــة برقــم ‪ 34361404‬يف ‪ 1434/11/18‬ه ـ واملتضمــن‬\n\n\n                                                                                       ‫‪310‬‬\n\f      ‫املصادقــة علــى احلكــم بعــد اجلــواب األخيــر‪ ،‬وأقفلــت اجللســة الســاعة‬\n      ‫‪ ، 12 : 00‬واهلل املوفــق‪ ،‬وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n                                   ‫وصحبــه أجمعــن حــرر يف ‪1434/12/23‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة املختصــة‬\n      ‫بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n      ‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫بالريــاض برقــم ‪ 342460670‬وتاريــخ ‪1434/10/29‬ه ـ املرفــق بهــا‬\n      ‫الصــك الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪ ... /‬املســجل‬\n      ‫برقــم ‪ 34268722‬وتاريــخ ‪1434/7/16‬ه ـ اخلــاص بدعــوى‪... /‬بالســجل‬\n      ‫املدنــي رقــم ‪...‬ضــد ‪ ... /‬يف قضيــة نفقــة أوالد وقــد تضمــن الصك حكم‬\n      ‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وحيــث ســبق دراســة الصــك‬\n      ‫وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة وباإلطــاع‬\n      ‫علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالصــك بنــاء علــى قرارنــا‬\n      ‫رقــم ‪ 34318434‬وتاريــخ ‪1434/9/14‬ه ـ تقــرر الدائــرة املصادقــة بعــد‬\n      ‫اجلــواب األخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد و علــى آلــه‬\n                                                                      ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪311‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":299,"source_page_end":311,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6c20696f4c323d5cd892933d20a8f8bb004a4665b0ae990852a1555fd0930e14","normalized_text_hash":"874778365dd24c8c29ff1e438a9185a0079e937781a034e3515f13634924aa9a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p299-34268722"},{"id":"94269e61-4ff5-5f17-8148-f47a6642cdc9","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -نفقة زوجة -نفقة حمل -نفقة حضانة -املطالبة بالنفقة املاضية -إنفاق األم على طفلها بنية الرجوع على األب مبا أنفقته- دفع الزوج بنشوز الزوجة يف عدم اإلنفاق عليها -النشوز ال يسقط نفقة احلامل -تقدير النفقة عن طريق قسم اخلبراء -احلكم بدفع النفقة املاضية -استالم املبلغ احملكوم به ينفي املطالبة به ثانية .","document_number":"34295759","case_number":"3449740","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":"الدائرة ( األحوال الشخصية الثانية) وذلك مبوجب قرارهم ذي","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/13","year":"1434","subject":"نفقة -نفقة زوجة -نفقة حمل -نفقة حضانة -املطالبة بالنفقة املاضية -إنفاق األم على طفلها بنية الرجوع على األب مبا أنفقته- دفع الزوج بنشوز الزوجة يف عدم اإلنفاق عليها -النشوز ال يسقط نفقة احلامل -تقدير النفقة عن طريق قسم اخلبراء -احلكم بدفع النفقة املاضية -استالم املبلغ احملكوم به ينفي املطالبة به ثانية .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/8/13 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34295759 :‬‬\n                    ‫َر ْق ُم الدعوى‪3449740 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n         ‫‪ 34337013‬تاريخه‪1434/10/21 :‬هـ‬\n\n\n\n‫نفقــة ‪ -‬نفقــة زوجــة‪ -‬نفقــة حمــل‪ -‬نفقــة حضانــة‪ -‬املطالبــة بالنفقــة‬\n‫املاضيــة‪ -‬إنفــاق األم علــى طفلهــا بنيــة الرجــوع علــى األب مبــا أنفقتــه‪-‬‬\n‫دفــع الــزوج بنشــوز الزوجــة يف عــدم اإلنفــاق عليهــا‪ -‬النشــوز ال يســقط‬\n‫نفقــة احلامــل‪ -‬تقديــر النفقــة عــن طريــق قســم اخلبــراء‪ -‬احلكم بدفع‬\n ‫النفقــة املاضيــة‪ -‬اســتالم املبلــغ احملكــوم بــه ينفــي املطالبــة بــه ثانيــة ‪.‬‬\n\n\n\n\n          ‫‪ -1‬قوله تعالى ( وعلى املولود له رزقهن وكسوتهن باملعروف)‬\n‫‪ -2‬مــا قــرره الفقهــاء مــن أن النشــوز ال يســقط نفقــة احلامــل ألن النفقــة‬\n                                                       ‫للحمــل وليــس للمــرأة‪.‬‬\n\n\n\n\n‫ادعــت املدعيــة بــأن املدعــى عليــة تزوجهــا بواليــة والدهــا ودخــل بهــا‬\n‫الدخــول الشــرعي وذهبــت إلــى بيــت أهلهــا علــى أثــر خــاف بينهمــا وهــي‬\n‫حامــل يف الشــهر الســابع‪ -‬بعــد الوضــع مكــث عندهــا طفلهــا شــهريني‬\n‫ثــم أخــذه أبــوه طلبــت املدعيــة إلــزام املدعــى عليــه بدفــع نفقتهــا ونفقــة‬\n‫ابنهــا املاضيــة‪ -‬دفــع املدعــى عليــه بأنــه طلبهــا مــرار ًا للرجــوع إلــى بيتــه‬\n‫ورفضــت وأنــه تقــدم بدعــوى للمحكمــة يطالــب زوجتــه بالرجــوع إلــى‬\n‫بيتــه‪ -‬دفــع املدعــى عليــه بأنــه دفــع نفقــة ابنــة يف الشــهر األول ولــم يتبــق‬\n\n                                                                                          ‫‪312‬‬\n\f      ‫ســوي نفقــه الشــهر الثانــي واســتعد بدفعهــا حســب مــا تقــرره احملكمــة‪-‬‬\n      ‫أنكــرت املدعيــة اســتالمها لنفقــة الشــهر األول للطفــل‪ -‬قــرر املدعــى‬\n      ‫عليــه أنــه ال بينــة لديــة علــى هــذا الشــهر وطلــب ميــن املدعيــة علــى نفــي‬\n      ‫النفقــة‪ -‬قــررت املدعيــة أنهــا لــن حتلــف وأنهــا متنازلــة عــن نفقــة الشــهر‬\n      ‫األول للطفــل‪ -‬ورد جــواب قســم اخلبــراء املتضمــن تقديــر نفقــة املدعيــة‬\n      ‫أثنــاء احلمــل ونفقــة الطفــل للشــهر الثانــي‪ -‬ملــا قــرره أهــل العلــم مــن أن‬\n      ‫النشــوز ال مينــع النفقــة ألن النفقــة للحمــل وليــس للمــرأة ولقولــة تعالــى‬\n      ‫( وعلــى املولــود لــه رزقهــن وكســوتهن باملعــروف) لــذا صــدر احلكــم‬\n      ‫بإلــزام املدعــى عليــه بــأن يدفــع للمدعيــة نفقــة احلمــل والشــهر الثانــي‬\n      ‫لطفلــة حســب قــرار قســم اخلبــراء‪ -‬اقتنعــت املدعيــة باحلكــم ولــم يقنــع‬\n                      ‫املدعــى عليــه‪ -‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n      ‫أنــا ‪...‬القاضــي باحملكمــة العامــة باملدينــة املنــورة ففــي هــذا اليــوم‬\n      ‫الســبت ‪1434/02/20‬ه ـ ويف متــام الســاعة التاســعة والنصــف صباحـ ًا‬\n      ‫فتحــت اجللســة األولــى بنــاء علــى املعاملــة املقيــدة يف هــذه احملكمــة‬\n      ‫برقــم‪ 34246051‬يف ‪1434/01/28‬ه ـ واحملالــة إلينــا مــن فضيلــة‬\n                                 ‫الرئيــس برقــم‪ 34246051‬يف ‪1434/01/28‬ه ـ‬\n      ‫مبوجبــه حضــرت املــرأة ‪ ...‬ميانيــة اجلنســية مبوجــب رخصــة اإلقامــة رقــم‬\n      ‫‪...‬جــوازات املدينــة املنــورة واملعــرف بهــا مــن قبــل والدهــا املقيــم ‪...‬ميانــي‬\n      ‫اجلنســية مبوجــب رخصــة اإلقامــة رقــم ‪...‬جــوازات املدينــة املنــورة ولــم‬\n      ‫يحضــر املدعــي عليــه ‪ ...‬وال مــن ينــوب عنــه يف موعــد هــذه اجللســة والتــي‬\n\n‫‪313‬‬\n\f‫حــدد لــه يف متــام الســاعة التاســعة صباح ـ ًا موعــدا لســماع الدعــوى‬\n‫رغــم تبلغــه مبوعــد هــذه اجللســة لشــخصه حســب إفــادة رئيــس قســم‬\n‫محضــري اخلصــوم يف هــذه احملكمــة شــرح ًا علــى ورقــة التبليــغ املؤرخــة‬\n‫يف ‪1434/01/28‬ه ـ ونظــر ًا ملــا تنــص عليــه املــادة اخلامســة واخلمســون‬\n‫مــن نظــام املرافعــات الشــرعية فقــد امــرت برفــع اجللســة إلــى يــوم األحــد‬\n‫املوافــق ‪1434/05/05‬ه ـ الســاعة احلاديــة عشــر وخمســة وأربعــون‬\n‫دقيقــة هــذا ويف يــوم الثالثــاء ‪1434/4/30‬ه ـ ويف متــام الســاعة الثانيــة‬\n‫والنصــف ظهــرا فتحــت اجللســة الثانيــة وفيهــا حضــرت املــرأة ‪...‬مينيــة‬\n‫اجلنســية مبوجــب رخصــة اإلقامــة رقــم ‪...‬جــوازات املدينــة املنــورة واملعرف‬\n‫بهــا مــن قبــل والدهــا املقيــم ‪...‬مينــي اجلنســية مبوجــب رخصــة اإلقامــة‬\n‫رقــم ‪......‬جــوازات املدينــة املنــورة وأدعــت علــى احلاضــر معهــا يف مجلــس‬\n‫احلكــم املقيــم ‪ ...‬ميانــي اجلنســية مبوجــب رخصــة اإلقامــة رقــم ‪...‬جــوازات‬\n‫املدينــة املنــورة قائلــة يف حتريــر دعواهــا عليــه ‪ :‬أن هــذا احلاضــر زوج لــي‬\n‫تزوجنــي بالعقــد الصحيــح الشــرعي بواليــة والــدي هــذا احلاضــر ‪ ...‬علــى‬\n‫مهــر وقــدره خمســة عشــر ألــف ريــال اســتلمتها كاملــة وقــد دخــل بــي‬\n‫بتاريــخ ‪1432/10/13‬ه ـ وقــد أجنبــت لــه علــى فــراش الزوجيــة ‪...‬املولــود‬\n‫يف ‪1433/11/13‬ه ـ وقــد حصــل بيننــا خالفــات وذلــك ألن املدعــى عليــه‬\n‫لــم يوفــر لــي ســكن مســتقل حيــث أننــي اســكن مــع أهلــه وقــد اتفقــت‬\n‫معــه قبــل الــزواج علــى أن يوفــر لــي ســكن مســتقل ولــم يحقــق ذلــك‬\n‫وحياتــي معــه دائمـ ًا بهــا مشــاكل وذلــك لتدخــل أهلــه يف حياتنــا اخلاصــة‬\n‫وبتاريــخ ‪1433/8/11‬ه ـ جــاء إلـ ّـي هــذا احلاضــر ومعــه والدتــه ودار بيننــا‬\n‫نقــاش علــى غســيل األوانــي ثــم قــام املدعــى عليــه بضربــي علــى وجهــي‬\n‫ا يف الشــهر‬    ‫وقــام بالتلفــظ علـ ّـي وســبي وســب أهلــي وكنــت حينهــا حامـ ً‬\n\n\n                                                                                      ‫‪314‬‬\n\f      ‫الســابع وبتاريــخ ‪1433/8/13‬ه ـ خرجــت مــن منــزل هــذا احلاضــر إلــى‬\n      ‫منــزل أهلــي وجلســت عندهــم حتــى تاريــخ هــذا اليــوم ولــم ينفــق علـ ّـي‬\n      ‫ريــا ًال واحــد ًا كمــا أننــي ولــدت ولــدي منــه ‪ ...‬بتاريــخ ‪1433/11/13‬ه ـ‬\n      ‫ولــم ينفــق عليــه حتــى أخــذه منــي بتاريــخ ‪1434/1/13‬ه ـ أي حوالــي‬\n      ‫شــهرين وقــد أنفقــت عليــه بنيــة الرجــوع علــى والــده‪ ،‬أطــب تقديــر النفقة‬\n      ‫املاضيــة الشــرعية لــي وألبنــي وإلــزام املدعــى عليــه بدفــع املبلــغ الــذي‬\n      ‫يقــدره أهــل اخلبــرة علمـ ًا أن هــذا احلاضــر يعمــل ســائق أجــرة يف شــركة‬\n      ‫‪...‬وراتبــه حوالــي مبلــغ وقــدره ألــف وخمســمائة ريــال هــذه دعــواي ‪.‬‬\n      ‫ا ‪ :‬مــا ذكرتــه املدعيــة‬    ‫وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائ ـ ً‬\n      ‫يف دعواهــا ضــدي مــن تاريــخ الــزواج والدخــول واملهــر والـ ــولد وتاريــخ‬\n      ‫خروجهــا مــن منزلــي وتاريــخ أخــذي البنــي فهذا كـل ــه صح ـيـ ــح ‪ ،‬وأمـ ــا‬\n      ‫مــا ذكرتــه مــن أننــي لــم أنفــق عليهــا مــن تاريــخ خروجهــا مــن منــزل‬\n      ‫أهلــي فهــذا صحيــح وذلــك ألنهــا ناشــز وقــد طلبتهــا مــرار ًا وتكــرار ًا‬\n      ‫بالرجــوع إلــى بيــت أهلــي ولكنهــا رفضــت الرجــوع وعليــه فإنهــا ناشــز ًا‬\n      ‫وال نفقــة لهــا علـ ّـي ‪ ،‬وأمــا مــا ذكرتــه مــن أننــي ال أنفــق علــى إبنــي خــال‬\n      ‫الشــهرين عندمــا كان عندهــا فهــذا غيــر صحيــح بــل أنفقــت عليــه يف‬\n      ‫الشــهر األول وأمــا الشــهر الثانــي فلــم أنفــق عليــه وأنــا مســتعد بدفــع‬\n      ‫النفقــة التــي يقدرهــا أهــل اخلبــرة ‪ ،‬وأمــا مــا ذكرتــه مــن حيــث عملــي‬\n      ‫وراتبــي فهــذا كلــه صحيــح هكــذا أجــاب والنتهــاء وقــت اجللســة فقــد‬\n      ‫أمــرت برفــع اجللســة إلــى يــوم األحــد ‪1434/5/5‬ه ـ الســاعة الثانية عشــر‬\n                                                                         ‫إال ربــع صباح ـ ًا‬\n      ‫هذا ويف يوم األحد ‪1434/5/5‬هـ ويف متام الســاعة الثانية عشــر والربع‬\n      ‫فتحــت اجللســة الثانيــة وفيهــا حضــرت املدعيــة واملعــرف بهــا مــن قبــل‬\n\n\n‫‪315‬‬\n\f‫والدهــا املدونــة هويتهــا ســابق ًا وحضــر حلضورهــا املدعــى عليــه ثــم جــرى‬\n‫ال ال ليــس لدي ديون‬    ‫منــا ســؤال املدعــى عليــه هــل لديــه ديــون فأجــاب قائ ً‬\n‫واحلمــد هلل تعالــى وأنــا اســكن مــع أهلــي وأقــوم باإلنفــاق عليهــم هكــذا‬\n‫أجــاب هــذا وقــد جــرى منــي الكتابــة إلــى قســم اخلبــراء لتقديــر النفقــة‬\n‫الشــرعية الواجبــة هــذا ويف يــوم األربعــاء ‪1434/06/21‬ه ـ ويف متــام‬\n‫الســاعة العاشــرة صباحـ ًا فتحــت اجللســة الرابعــة وفيهــا حضــرت املدعيــة‬\n‫واملعــرف بهــا مــن قبــل والدهــا ‪...‬املــدون هويتهمــا ســابق ًا ولــم يحضــر‬\n‫املدعــى عليــه وال مــن ينــوب عنــه يف موعــد هــذه اجللســة والتــي حــدد لهــا‬\n‫يف متــام الســاعة التاســعة والنصــف موعــد ًا لســماع الدعــوى وقــد جــرى‬\n‫تبليغــه مبوعــد هــذه اجللســة يف اجللســة املاضيــة ولــم يحضــر ولــم يقــدم‬\n‫عــذر ًا لعــدم حضــوره وقــد جــرى منــا الكتابــة إلــى قســم اخلبــراء لتقديــر‬\n‫النفقــة الشــرعية الواجبــة وحتــى تاريــخ هــذا اليــوم لــم تردنــا افــادة وعليــه‬\n‫أمــرت برفــع اجللســة إلــى يــوم الســبت ‪1434/08/13‬ه ـ الســاعة احلاديــة‬\n‫الســاعة احلاديــة‬\n                 ‫عشــر صباحـ ًا هــذا ويف يــوم الســبت ‪1434/08/13‬ه ـ َّ‬\n‫صباحــا ُفت َِحـ ْـت اجللســة اخلامســة وفيهــا حضــرت املدعيــة واملعــرف‬\n                                                                        ‫ً‬      ‫عشــر‬\n‫بهــا مــن قبــل والدهــا ‪ ...‬املدونــة هويتــه ســابق ًا وحضــر حلضــوره املدعــى‬\n‫عليــه أصالــة هــذا وقــد وردنــا إفــادة قســم اخلبــراء يف هــذه احملكمــة‬\n‫مبوجــب خطابهــم ذي الرقــم ‪ 341516993‬يف ‪1434/07/17‬ه ـ وهــذا‬\n‫نــص احلاجــة منــه « وبعــد ذلــك رأينــا أن يدفــع املدعــى عليــه نفقــة احلمــل‬\n‫واحلضانــة وقدرهــا ألــف وســتمائة وواحــد وســبعون ريــا ًال وأمــا نفقــة‬\n‫الشــهرين رأينــا أن تكــون خمســمائة ريــال لــكل شــهر هــذا مــا رأينــاه‬\n‫«أ‪.‬ه ـ وبعــرض قــرار قســم اخلبــراء يف هــذه احملكمــة علــى املدعــى عليــه‬\n‫واملدعيــة أجابــت املدعيــة قائلــة أنــا مقتنعــة بقــرار قســم اخلبــراء هكــذا‬\n\n\n                                                                                         ‫‪316‬‬\n\f      ‫ا أنــا غيــر مقتنــع بهــذا القــرار‬‫أجابــت وأمــا املدعــى عليــه فأجــاب قائ ـ ً‬\n      ‫وذلــك ألننــي أقمــت دعــوى علــى املدعــى عليهــا منــذ خروجهــا مــن منزلــي‬\n      ‫إلعادتهــا إلــى بيــت الطاعــة ولكــن لــم حتضــر يف جلســات احملاكمــة‬\n      ‫وعليــه فهــي ناشــز ال جتــب علـ ّـي نفقتهــا وأمــا نفقــة الشــهر فهــذا أنــا‬\n      ‫غيــر مســتعد بــه وذلــك ألننــي دفعــت نفقــة الشــهر األول للمدعيــة أصالــة‬\n      ‫مبلــغ مائتــان ريــال ومالبــس للطفــل تقــدر بخمســمائة ريــال وعليــه فــا‬\n      ‫جتــب علـ ّـي نفقــة االبــن وأمــا الشــهر اآلخــر فأنــا مســتعد بدفــع نفقتــه‬\n      ‫هكــذا أجــاب وبعــرض ذلــك علــى املدعيــة أجابــت قائلــة مــا ذكــره‬\n      ‫املدعــى عليــه غيــر صحيــح ولــم ينفــق علــى ابنــه إال انــه أحضــر معــه‬\n      ‫أربــع بــدل وكذلــك هــزاز للطفــل وحفائــض وشرشــف فقــط هــذا مــا‬\n      ‫أحضــره وقدرهــا بالكثيــر مائتــان ريــال ولــم يعطينــي ريــا ًال واحــد ًا‬\n      ‫هكــذا أجابــت ثــم جــرى منــا ســؤال املدعــى عليــه هــل لديــه بينــة فيمــا‬\n      ‫ا ال ليــس‬ ‫دفــع بــه مــن أنــه انفــق نفقــة الشــهر األول البنــه ‪...‬فأجــاب قائـ ً‬\n      ‫لــدي بينــة علــى ذلــك وأطلــب ميــن املدعيــة هكــذا اجــاب وبعــرض ذلــك‬\n      ‫علــى املدعيــة أجابــت قائلــة لــن أحلــف ولكــن أنــا متنازلــة عــن نفقــة‬\n      ‫الشــهر األول وأطلــب نفقــة الشــهر الثانــي هكــذا أجابــت فبنــاء علــى‬\n      ‫مــا تقــدم مــن الدعــوى واإلجابــة واإلطــاع علــى أوراق املعاملــة وحيــث‬\n      ‫صــادق املدعــى عليــه ملــا جــاء يف دعــوى املدعيــة مــن أنــه لــم ينفــق علــى‬\n      ‫زوجتــه احلامــل منــذ خروجهــا مــن منزلــه بتاريــخ ‪1433/08/13‬ه ـ وحتــى‬\n      ‫والدتهــا بتاريــخ ‪1433/11/13‬ه ـ ريــا ًال واحــد ًا ومبــا أن املدعــى عليــه‬\n      ‫دفــع بعــدم نفقــة عليهــا ألنــه ناشــز ومبــا أن نفقــة احلمــل جتــب علــى الــزوج‬\n      ‫ليــس للمــرأة ولكــن للحمــل كمــا قــرر بذلــك الفقهــاء ولقولــه تعالــى‪:‬‬\n                                ‫(وعلــى املولــود لــه رزقهــن وكســوتهن باملعــروف )‬\n\n\n‫‪317‬‬\n\f‫ومبــا أن املدعــى عليــه صــادق علــى مــا جــاء يف دعــوى املدعيــة مــن أنــه لــم‬\n‫ينفــق علــى املولــود يف الشــهر الثانــي وأنكــر مــا جــاء يف دعــوى املدعيــة‬\n‫مــن أنــه لــم ينفــق يف الشــهر األول مــن والدة املولــود وادعــى أن ينفــق علــى‬\n‫ابنــه يف الشــهر األول وأنكــرت ذلــك املدعيــة ولــم يقــم املدعــى عليــه‬\n‫بينــة علــى ذلــك وطلــب ميــن املدعيــة علــى نفــي دعــواه ومبــا أن املدعيــة‬\n‫قــد تنازلــت عــن نفقــة شــهر واحــد ونظــر ًا ملــا قــرره قســم اخلبــراء يف هــذه‬\n‫احملكمــة مبوجــب قرارهــم املشــار إليــه بعاليــه جلميــع مــا ذكــر فقــد‬\n‫ألزمــت املدعــى عليــه بدفــع مبلــغ وقــدره ألفــان ومائــة وواحــد وســبعون‬\n‫ريــال حــا ًال للمدعيــة هــذا مــا ظهــر لــي وبــه حكمــت وبعرضــه عليهمــا‬\n‫قــررت املدعيــة القناعــة أمــا املدعــى عليــه فقــرر اعتراضــه علــى احلكــم‬\n‫بــدون الئحــة اعتراضيــة وعليــه أمــرت برفــع املعاملــة إلــى محكمــة‬\n‫االســتئناف لتدقيــق احلكــم حســب املتبــع نظام ـ ًا وبــه اختتمــت اجللســة‬\n‫الساعة احلادية عشر والنصف و باهلل ال َّتوفيق‪ ،‬و صلَّى اهلل و سلَّم على‬            ‫َّ‬\n‫محمــدٍ ‪ ،‬و علــى آلــه و صحبــه أجمعــن حــرر يف ‪1434/08/13‬هــ‪.‬‬         ‫نبينــا َّ‬  ‫ِّ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي‬\n‫هــذا اليــوم األحــد ‪1434/12/1‬ه ـ عــادت لنــا املعاملــة مــن محكمــة‬\n‫االســتئناف مبكــة املكرمــة مبوجــب خطابهــم ذي الرقــم ‪34246051‬‬\n‫يف ‪1434/10/27‬ه ـ وقــد جــرى تدقيــق احلكــم وتصديقــه مــن قبــل‬\n‫الدائــرة ( األحــوال الشــخصية الثانيــة) وذلــك مبوجــب قرارهــم ذي‬\n‫الرقــم ‪ 34337013‬يف ‪1434/10/ 21‬ه ـ وقــد تضمــن قرارهــم املوافقــة‬\n‫علــى احلكــم بختــم وتوقيــع كل مــن ‪ ...‬قاضــي اســتئناف و ‪ ...‬قاضــي‬\n‫اســتئناف و ‪ ...‬رئيــس الدائــرة وللمعلوميــة جــرى حتريــره حتــى ال يخفــى‬\n‫وأمــرت بإحلــاق ذلــك يف ضبطــه وســجله وبــاهلل التوفيــق وصلى اهلل وســلم‬\n\n\n                                                                                          ‫‪318‬‬\n\f                                     ‫علــى نبينــا محمــد ‪ .‬حــرر يف ‪1434/12/1‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعده وبعــد ففي هذا‬\n      ‫اليــوم األحــد ‪1435/1/21‬ه ـ حضــر املدعــي وحضــر حلضــوره املدعــى‬\n      ‫ا اســتلمت كامــل املبلــغ احملكــوم لــي‬        ‫عليــه وعليــه قــرر املدعــي قائ ـ ً‬\n      ‫بباطــن هــذا الصــك وقــدره ألفــان ومائــة وواحــد وســبعون ريــا ًال ريــال‬\n      ‫نقــد ًا وعليــه فــا يحــق لــي مطالبــة املدعــى عليــه بــأي مبالــغ ماليــة فيمــا‬\n      ‫يخــص هــذه الدعــوى وللمعلوميــة جــرى حتريــره حتــى ال يخفــى وبــاهلل‬\n      ‫التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف ‪1435/1/21‬ه ـ‬\n      ‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد‪ :‬فقــد جــرى منــا‬\n      ‫نحــن قضــاة الدائــرة الثانيــة لألحــوال الشــخصية واألوقــاف والوصايــا‬\n      ‫والقصــار وبيــوت املــال مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة‬\n      ‫االطــاع علــى الصــك الصــادر مــن فضيلــة الشــيخ‪ ...‬باحملكمــة العامــة‬\n      ‫باملدينــة املنــورة برقــم ‪ 34295759‬وتاريــخ ‪1434/8/13‬ه ـ املتضمــن‬\n      ‫دعــوى ‪ ...‬ضــد ‪ ...‬يف نفقــة ‪ ،‬وبدراســة الصــك وصــورة ضبطــه تقــررت‬\n      ‫املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                                    ‫آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪319‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":312,"source_page_end":319,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"feea0fa3ed3d9ebb384648324fb15287cd3fb5460442d8de8edca6da5207efd8","normalized_text_hash":"6074cc5039050e9703dddc174b5a739021e24477cb33950ceaffd2dfe2bbbadd","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p312-34295759"},{"id":"85d5af5b-99e4-52e4-a0f2-94f9e49f3b9f","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -إعالة وتسديد فواتير وإيجار الشقة ومصروفات املدارس - تقديرها عن طريق قسم اخلبراء -محاولة الصلح بن الطرفن - الصلح على مبالغ معينه -رصد الصلح يف ضبط القضية -امتنع املدعى عليه من التوقيع -صدر احلكم بصحة الصلح ولزومه .","document_number":"34302883","case_number":"307161127","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/22","year":"1434","subject":"نفقة -إعالة وتسديد فواتير وإيجار الشقة ومصروفات املدارس - تقديرها عن طريق قسم اخلبراء -محاولة الصلح بن الطرفن - الصلح على مبالغ معينه -رصد الصلح يف ضبط القضية -امتنع املدعى عليه من التوقيع -صدر احلكم بصحة الصلح ولزومه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/8/22 :‬هـ‬\n                 ‫ُ‬                 ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪34302883 :‬‬\n                   ‫َر ْق ُم الدعوى‪307161127 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34375195‬تاريخه‪1434/12/2 :‬هـ‬\n\n\n\n‫نفقــة ‪ -‬إعالــة وتســديد فواتيــر وإيجــار الشــقة ومصروفــات املــدارس ‪-‬‬\n‫تقديرهــا عــن طريــق قســم اخلبــراء ‪ -‬محاولــة الصلــح بــن الطرفــن ‪-‬‬\n‫الصلــح علــى مبالــغ معينــه ‪ -‬رصــد الصلــح يف ضبــط القضيــة ‪ -‬امتنــع‬\n    ‫املدعــى عليــه مــن التوقيــع ‪ -‬صــدر احلكــم بصحــة الصلــح ولزومــه ‪.‬‬\n\n\n\n\n                                      ‫‪ -‬قول اهلل تعالى ‪ ( :‬والصلح خير ) ‪.‬‬\n‫‪ -‬مــا أخرجــه أبــو داود والترمــذي مــن حديــث أبــي هريــرة رضــي اهلل‬\n‫عنــه وعمــرو بــن عــوف املزنــي أن رســول اهلل صلــى اهلل عليــه وســلم قــال‬\n                                            ‫( الصلــح جائــز بــن املســلمني ) ‪.‬‬\n                        ‫‪ -‬القاعدة الفقهية الكلية ( ال ضرر وال ضرار ) ‪.‬‬\n                                        ‫‪ -‬القاعدة الفقهية ( الضرر يزال ) ‪.‬‬\n                              ‫‪ -‬املادة (‪ )166‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n‫ادعــت املدعيــة بأنهــا زوجــة للمدعــى عليــه الغائــب عــن مجلــس احلكــم‬\n‫ورزقــت منــه بولديــن قاصريــن همــا ‪ ..‬و‪ ، ..‬وقــد هجرهــا منــذ عــام‬\n‫‪1427‬ه ـ وتركهــم بــا نفقــة هــي وأوالدهــا ولــم يقــم بســداد فواتيــر‬\n‫املــدارس وعقــد الشــقة وفواتيــر الكهربــاء وجميــع املبالــغ تقــدر مببلــغ‬\n\n                                                                                   ‫‪320‬‬\n\f      ‫وقــدره ‪ 395‬ألــف ريــال ‪ -‬مت بعــث املعاملــة لقســم اإلصــاح وقدمــت‬\n      ‫املــرأة مــا دفعتــه مبوجــب إيصــاالت وقــدرت النفقــة للولديــن ملــدة خمــس‬\n      ‫ســنوات مــع مبلــغ املــدارس وقــدر املبلــغ الــذي تســتحقه املــرأة ب ـ ‪ 191‬ألــف‬\n      ‫ريــال ‪ -‬يف جلســة أخــرى مت تــاوة مــا مت ضبطــه ســابق ًا يف اجللســة األولــى‬\n      ‫نظــر ًا النتقــال القاضــي األول ومباشــرة خلفــه يف نفــس املكتــب ‪ -‬حضر‬\n      ‫املدعــى عليــه يف هــذه اجللســة وبعــرض الدعوى عليــه صادق على خروجه‬\n      ‫مــن بيتــه ألن املدعيــة حاولــت قتلــه هــي وأوالدهــا ثــم ســافر إلــى اخلــارج يف‬\n      ‫شــوال ‪1431‬ه ـ ملرافقــة ابنتــه يف الدراســة ‪ -‬مت طلــب تفاصيــل النفقــات‬\n      ‫مــن املدعيــة فأحضرتهــا يف جلســة أخــرى ورصــدت يف ضبــط القضيــة‬\n      ‫وتشــمل إيجــار الشــقة وســداد دفعــات املــدارس إعطــاء األوالد املصــروف‬\n      ‫الشــهري واليومــي ومصــروف األكل والشــرب وأصبــح إجمالــي املبالــغ‬\n      ‫التــي تطالــب بهــا املدعيــة مبلــغ وقــدره ‪ 224.786‬ريــال وبعــرض ذلــك‬\n      ‫علــى املدعــى عليــه قــال لــن أنفــق عليهــم ألنهــم قامــوا بتهديــده وطــرده‬\n      ‫مــن بيتــه ‪ -‬مت إحالــة املعاملــة مــرة أخــرى لقســم اإلصــاح نظــر ًا لكبــر‬\n      ‫ســن الطرفــن وطــول مــدة زواجهــا فعــادت املعاملــة مــن قســم اإلصــاح‬\n      ‫يتضمــن أن املدعــى عليــه يدفــع للمدعيــة ‪ 120‬ألــف ريــال تكــون شــاملة‬\n      ‫للنفقــات واملصاريــف واملســتحقات الســابقة ويقــوم باإلنفــاق لــكل شــهر‬\n      ‫‪ 500‬ريــال علــى االبــن والبنــت ويقــوم بدفــع ‪1833‬ريــال أجــرة الســكن‬\n      ‫كل شــهر وهــذا الصلــح منهــي للنــزاع بــن الطرفــن ‪ -‬طلــب الطرفــان‬\n      ‫إثبــات هــذا الصلــح واحلكــم بــه ‪ ،‬حيــث إن الصلــح خيــر وهــو جائــز بــن‬\n      ‫املســلمني ‪ -‬صــدر احلكــم بصحــة هــذا الصلــح ولزومــه بــن الطرفــن‬\n      ‫وإجازتــه ‪ -‬و بعرضــه قــررت املدعيــة واملدعــى عليــه القناعــة بــه ‪ -‬بطلــب‬\n      ‫التوقيــع مــن املدعــى عليــه بعــد االنتهــاء مــن ضبــط القضيــة رفــض‬\n\n\n‫‪321‬‬\n\f‫املدعــى عليــه بشــهادة الكاتــب ‪ -‬حضــر وكيــل املدعــى عليــه يف جلســة‬\n‫أخــرى وقــرر عــدم قناعتــه باحلكــم بالئحــة اعتراضيــة وأفهــم بتعليمــات‬\n                ‫االســتئناف ‪ -‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن النبــي بعــده وبعــد فلــدي‬\n‫أنــا ‪ ...‬القاضــي باحملكمــة العامــة مبحافظــة جــدة ‪ .‬وبنــاء علــى املعاملــة‬\n‫احملالــة لنــا مــن فضيلــة رئيس احملكمة العامة مبحافظة جدة‪/‬املســاعد‬\n‫برقــم ‪ 307161127‬وتاريــخ ‪ 1431/12/21‬ه ـ املقيــدة باحملكمــة‬\n‫برقــم ‪ 31102386‬وتاريــخ ‪ 1431/12/21‬ه ـ ‪ .‬ويف يــوم االثنــن املوافــق‬\n‫‪1432/05/28‬ه ـ أفتتحــت اجللســة الســاعة ‪ 11 : 08‬وفيهــا حضــرت ‪...‬‬\n‫ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬وادعــت علــى الغائــب‬\n‫عــن مجلــس احلكــم ‪ ...‬وقــد بلــغ عــن طريــق البحــث والتحــري قســم‬\n‫ا يف دعــواه أن زوجــي هجرني منذ عام ‪1427‬هـ‬             ‫التحريــات والبحــث قائـ ً‬\n‫وملــدة خمــس ســنوات ولــم يقــم بإعالتــي أنــا وأبنائــي القصــار ‪ ...‬و‪ ...‬منــذ‬\n‫ذلــك احلــن وتركنــا دون ســكن واآلن لــم اســتطيع إعالــة نفســي اطلــب‬\n‫تســديد فواتيــر املــدارس وعقــد إيجــار الشــقة وفواتيــر الكهربــاء والتــي‬\n‫تقــدر مبلــغ وقــدرة ثالثمائــة وخمســة وتســعون ألــف ريــال هــذه دعــواي‬\n‫وقــد جــرى منــا بعــث املعاملــة إلــى قســم اإلصــاح مبوجــب خطابنــا رقــم‬\n‫‪ 31/102386‬يف ‪1431/3/13‬ه ـ فوردنــا جوابهــم مبوجــب خطابهــم رقم‬\n‫‪ 31/102386‬يف ‪1431/3/13‬ه ـ واملتضمــن (( أنــه قــد حضــرت املــرأة‬\n‫ولــم يحضــر املدعــى عليــه وذكــرت املــرأة بأنــه قد تركها هــي وأوالدها‬\n‫وســافر وال يصــرف عليهــا منــذ خمــس ســنني منــذ تاريــخ ‪1427‬ه ـ جمــاد‬\n\n                                                                                      ‫‪322‬‬\n\f      ‫األولــى حتــى تاريــخ هــذا الشــهر ‪1431/3/13‬ه ـ هــي وأوالدهــا ‪ ...‬و‪...‬‬\n      ‫وبنتهــا الكبيــرة التــي تزوجــت منــذ ثمانيــة اشــهر وعليــه نــرى أن يكــون‬\n      ‫مصــروف كل فــرد خمســمائة ريــال لــكل مــن املــرأة و‪ ...‬و‪ ...‬ســتون‬\n      ‫شــهر ًا والبنــت الكبــرى اثنــان وخمســون شــهر ًا مجمــوع نفقتهــم مائــه‬\n      ‫وســته عشــر ألــف ريــال ودفــع اإليجــارات التــي دفعتهــا املــرأة مثبتــه لديهــا‬\n      ‫باإليصــاالت مبلــغ وقــدرة خمســة وســتون ألــف ريــال مبالــغ املــدارس التــي‬\n      ‫دفعتهــا املــرأة عشــرة اآلف ريــال ويكــون مجمــوع مــا تســتحقه املــرأة مــن‬\n      ‫الرجــل مائــه وواحــد وتســعون ألــف ريــال هــذا مــا نــراه واهلل املوافــق )) ‪،‬‬\n      ‫هــذا مــا تضمنــه محضــر اإلصــاح ‪ .‬وبنــاء علــى ذلــك ســوف يتــم الكتابة‬\n      ‫للبحــث والتحــري وذلــك ألمــر القبــض علــى املدعــى عليه وإحضــاره وقت‬\n      ‫الــدوام الرســمي وعليــه جــرى رفــع اجللســة ‪ .‬ويف جلســة أخــرى لــدي أنــا ‪...‬‬\n      ‫القاضــي باحملكمــة العامــة مبحافظــة جــدة خلف ـ ًا لفضيلــة القاضــي ‪...‬‬\n      ‫‪ .‬ويف يــوم األحــد املوافــق ‪1433/01/30‬ه ـ أفتتحــت اجللســة الســاعة ‪00‬‬\n      ‫‪ 10 :‬وفيهــا حضــرت املدعيــة أصالــة وحضــر حلضورهــا املدعــى عليــه ‪...‬‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ، ...‬واســتناد ًا إلــى املــادة‬\n      ‫‪ 166‬مــن نظــام املرافعــات الشــرعية ولوائحهــا التنفيذيــة فقد جرى تالوة‬\n      ‫مــا مت ضبطــه علــى أســماع املتداعيــن وصــادق الطرفــان علــى صحتــه ‪.‬‬\n      ‫وبعــرض دعــوى املدعيــة علــى املدعــى عليــه أجــاب بقولــه ‪ :‬أننــي خرجــت‬\n      ‫مــن بيتــي بعــد أن هــددت بالقتــل بالســكني فكيــف أنفــق علــى مــن‬\n      ‫حاولــوا قتلــي ‪ ،‬ثــم إننــي غــادرت يف شــهر شــوال مــن عــام ‪1431‬ه ـ إلــى‬\n      ‫كنــدا مرافق ـ ًا البنتــي ‪ ...‬ملــدة ســنة ونصــف فكيــف انفــق ‪ ،‬هكــذا‬\n      ‫أجــاب ‪ .‬وقــد طلبــت مــن املدعيــة بيــان تفاصيــل النفقــات التــي تدعــي‬\n      ‫بهــا فقالــت بأننــي لــم أكتبهــا ومســتعدة بإحضارهــا يف اجللســة القادمــة‬\n\n\n‫‪323‬‬\n\f‫‪ ،‬وعليــه رفعــت اجللســة إلحضــار تفاصيــل املدفوعــات املدعــى بهــا مــن‬\n‫املدعيــة ‪ .‬ويف جلســة أخــرى يف يــوم األربعــاء املوافــق ‪1433/03/30‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 10 : 00‬وفيهــا حضــر املتداعيــان أصالــة ‪.‬‬\n‫وبســؤال املدعيــة عمــا أســتعدت بإحضــاره يف اجللســة املاضيــة مــن بيــان‬\n    ‫تفاصيــل النفقــات التــي تدعــي بهــا ‪ ،‬فأبــرزت الكشــف وهــذا نصــه‬\n‫(( أتقــدم لفضيلتكــم بســنداتي و الــذي قمــت فيهــا بـ ـس ــداد اإليجــارات‬\n‫و الدفعــات املدرســية ألبنائــي ‪ ...‬و ‪ ...‬و قيامــي بإعطائهــم مصروفاتهــم‬\n‫اليوميــة و الشــهرية و كذلــك فواتيــر الكهربــاء ‪ -1 :‬قمــت بســداد‬\n‫إيجار شــقة يف حي ‪ ...‬يف تاريخ ‪1427/11/20‬هـ إحدى عشــر ألف ريال‬\n‫(‪ -2 .)11,000‬قمت بسداد إيجار شقة يف تاريخ ‪1429/11/28‬هـ مبلغ‬\n‫و قــدره (‪ )22,000‬اثنــان و عشــرون ألــف ريــال ‪-3 .‬قمــت بســداد إيجــار‬\n‫شــقة بالدفــع إلــى املالكــة ‪ ...‬إيجــار شــهرين مببلــغ (‪ )5,000‬خمســة‬\n‫اآلف ريــال مــن ‪1431/9/1‬ه ـ إلــى ‪1432/10/30‬هــ‪ -4 .‬قمــت بســداد‬\n‫إيجــار شــقة عــن طريــق مكتــب ‪ ...‬للعقــار مبلــغ و قــدره (‪ )32,000‬اثنــان‬\n‫وثالثــون ألــف ريــال ‪ -5.‬شــيك مصــدق إيجــار شــقة عــن طريــق مكتــب‬\n‫‪ ...‬للعقــار إيجــار ســته أشــهر (‪ )13,000‬ثالثــة عشــر ألــف ومبلــغ نقــدي‬\n‫(‪ )3000‬ريــال ثالثــة اآلف ريــال مدفــوع مقدم ـ ًا ‪-6 .‬ســداد مدرســة ‪...‬‬\n‫وقيمــة الســداد (‪ )5500‬خمســة اآلف وخمســمائة ريــال قســط الصــف‬\n‫الســادس االبتدائــي‪ -7 .‬ســداد مدرســة ‪ ...‬وقيمــة الســداد هــي (‪)14500‬‬\n‫أربعة عشــر ألف و خمســمئة ريال و هذا قســط الصف الثاني ثنوي ‪-8 .‬‬\n‫ســداد مبلــغ دورة قــدرات ‪ )490( ...‬أربعمئــة و تســعني ريــال ‪ -9 .‬مجمــوع‬\n‫فواتيــر الكهربــاء ‪ 2296‬ريــال ‪ .‬وقــد هجرنــي أنــا وأبنائــي الثالثــة ‪ ...‬و‪...‬‬\n‫و‪ ...‬مــن تاريــخ ‪1427/10/20‬ه ـ و لــم يقــم باعطائهــم أي مصــروف أو‬\n\n\n                                                                                     ‫‪324‬‬\n\f      ‫مبالــغ ماليــة لهــم و ال مصروفهــم الدراســي و لــم يقــم بإعطائــي مصــروف‬\n      ‫مــأكل أو مشــرب لهــم‪ .‬ومت حســاب جميــع املبالــغ مــن {جلنــة إصــاح‬\n      ‫ذات البيــان} وهــي كالتالــي ‪ :‬مصــروف ابنتــي ‪ ...‬علــى مــدى اثنــان و‬\n      ‫خمســون شــهر وكل شــهر ‪ 500‬ريــال ويكــون مجموعهــا (‪)26,000‬‬\n      ‫ســته وعشــرون ألــف ريــال ‪ .‬و ‪ ...‬و‪ ...‬و ‪ ...‬قــدر لنــا مبلــغ شــهري مقــداره‬\n      ‫‪ 500‬ريــال لــكل فــرد علــى مــدى ســتني شــهرا وكان مجموعهــا ‪:‬‬\n      ‫(‪ )90000‬تســعون ألــف ريــال و هــذا مبلــغ مــن عــام ‪ 1427‬ه ـ ‪ { .‬ويكــون‬\n      ‫مجمــوع املبالــغ (‪ )224786‬مائتــان وأربــع وعشــرين ألــف وســبعمائة‬\n      ‫وســته وثمانــون ريــال} )) ‪ .‬وبعرضــه علــى املدعــى عليــه أجــاب بقولــه ‪ :‬أنــا‬\n      ‫لــن أنفــق عليهــم ‪ ،‬ألنهــم هددونــي وطردونــي مــن بيتــي ‪ ،‬ولــن أدفــع لهــم‬\n      ‫ريــا ًال واحــد ًا ولــو كان ذلــك علــى وفاتــي ‪ ،‬هكــذا أجــاب ‪ .‬ولالطــاع‬\n      ‫علــى الكشــف الــذي أبرزتــه املدعيــة ودراســته قــررت رفــع اجللســة ‪ .‬ويف‬\n      ‫جلســة أخــرى يف يــوم االثنــن املوافــق ‪1433/07/14‬ه ـ افتتحــت اجللســة‬\n      ‫الســاعة ‪ 11 : 00‬وفيهــا حضــر املتداعيــان أصالــة ‪ .‬ونظــر ًا لكبــر ســن‬\n      ‫الطرفني ولطول مدة زواجهما فقد قررت بعث املعاملة لقســم اإلصالح‬\n      ‫حملاولــة الصلــح بــن الطرفــن يف النفقــة ‪ .‬وألجلــه قــررت رفــع اجللســة ‪.‬‬\n      ‫ويف جلســة أخــرى يف يــوم اإلثنــن املوافــق‪ 1434/08/15‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 1.00‬وفيهــا حضــرت املدعيــة وحضــر حلضورهــا املدعى‬\n      ‫عليــه ‪ ...‬ســعودي مبوجــب الســجل املدنــي رقــم ‪ ...‬وعليــه جــرى محاولــة‬\n      ‫الصلــح بــن الطرفــن وتذكيرهمــا بــاهلل تعالــى اســتجاب كل واحــد‬\n      ‫فيهمــا للصلــح واتفقــا الطرفــان أن يعطــي املدعــى عليــه للمدعيــة مبلغـ ًا‬\n      ‫وقــدرة‪ 120‬مائــه وعشــرون ألــف ريــال تكــون شــاملة لــكل النفقــات‬\n      ‫واملصاريــف واملســتحقات املاليــة الســابقة التــي تطالــب بهــا املدعيــة وأن‬\n\n\n‫‪325‬‬\n\f‫ينفــق املدعــى عليــه علــى ابنــه ‪500 ...‬ريــال شــهري ًا وعلــى ابنتــه ‪ 500‬ريــال‬\n‫شــهري ًا وان يدفــع املدعــى عليــه كل شــهر اجــرة الســكن كل شــهر‬\n‫‪ 1833‬ريــال وأن يكــون هــذا الصلــح منهي ـ ًا لــكل نــزاع بــن الطرفــن‬\n‫يف موضــوع النفقــة واملســتحقات املاليــة الزوجيــة وطلــب الطرفــان اثبــات‬\n                                ‫هــذا الصلــح واحلكــم بــه هكــذا اصطلحــا ‪.‬‬\n‫وبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وملــا دار مــن صلــح بــن‬\n‫املتخاصمــن بعاليــه ولقــول اهلل تعالــى (( والصلــح خيــر )) وملــا أخرجــه‬\n‫اإلمــام أبــو داود والترمــذي مــن حديــث أبــي هريــرة وعمــرو بــن عــوف‬\n‫املزنــي أن رســول اهلل صلــى اهلل عليــه وســلم قــال (( الصلــح جائــز‬\n‫بــن املســلمني )) وللقاعــدة الفقهيــة الكليــة أنــه ال ضــرر وال ضــرار‬\n‫وللقاعــدة الفقهيــة أن الضــرر يــزال وملوافقــة الصلــح الــوارد بعاليــه‬\n‫لألصــول الشــرعية والقواعــد الفقهيــة فقــد أجــزت الصلــح الــوارد‬\n‫بعاليــه علــى الصفــة املذكــورة فيــه وحكمــت بصحتــه ولزومــه بــن‬\n‫الطرفــن‪ .‬وبعرضــه علــى الطرفــن قــررا القناعــة بــه ‪ .‬وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‬\n‫‪1434/08/15‬هــ‪ .‬ويف يــوم االثنــن املوافــق ‪1434/8/15‬ه ـ وبعــد‬\n‫االنتهــاء مــن ضبــط القضيــة‪ُ ،‬طلــب مــن الطرفــن التوقيــع علــى محضــر‬\n‫الضبــط ‪ ،‬فرفــض املدعــى عليــه ‪ ...‬التوقيــع‪ ،‬وذلــك بشــهادة الكاتــب‪....‬‬\n‫وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n‫‪ .‬حــرر يف ‪1434/8/21‬هــ‪ .‬ويف يــوم األحــد املوافــق ‪ 1434/08/21‬ه ـ‬\n‫حضــر ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬بوكالتــه عــن‬\n‫املدعــى عليــه ‪ ...‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة‬\n‫بشــمال جــدة برقــم ‪ 341145296‬وتاريــخ ‪1434/08/16‬ه ـ ‪ .‬وقــرر عــدم‬\n\n\n                                                                                        ‫‪326‬‬\n\f      ‫قناعتــه باحلكــم ‪ ،‬وطلــب رفــع املعاملــة حملكمــة االســتئناف بالئحــة‬\n      ‫اعتراضيــة ‪ .‬وأفهــم بــأن لــه حــق االعتــراض خــال ثالثــون يوم ـ ًا تبــدأ‬\n      ‫مــن ‪1434/08/22‬ه ـ ‪ ،‬وإذا مضــت املــدة ولــم يقــدم الئحــة فيكتســب‬\n      ‫احلكــم القطعيــة ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                 ‫آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/08/21‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n      ‫مبحافظــة جــدة ويف يــوم األربعــاء املوافــق ‪1435/1/3‬هـ كان قد وردتنا‬\n      ‫املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة برقــم ‪342615632‬‬\n      ‫يف ‪1434/12/19‬ه ـ والتــي حتــوي علــى القــرار الدائــرة الثانيــة لألحــوال‬\n      ‫الشــخصية واألوقــاف والوصايــا وبيــوت املــال بخصــوص دعــوى ‪ ...‬ضــد‬\n      ‫‪ ...‬وقــد تضمــن القــرار ( املوافقــة علــى احلكــم ) قاضــي اســتئناف ‪...‬‬\n      ‫ختــم وتوقيــع ‪ ...‬ختــم وتوقيــع ورئيــس الدائــرة ‪ ...‬ختــم وتوقيــع وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                        ‫حــرر يف ‪1435/01/03‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n      ‫جــرى منــا نحــن قضــاة الدائــرة الثالثــة لألحــوال الشــخصية واألوقــاف‬\n      ‫والوصايــا والقصــار وبيــوت املــال مبحكمــة االســتئناف يف منطقــة‬\n      ‫مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة مبحافظــة جــدة برقــم ‪ 31102386‬وتاريــخ بــدون‬\n      ‫املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ ‪ ...‬القاضــي باحملكمــة‬\n      ‫العامــة مبحافظــة جــدة برقــم ‪ 34302883‬وتاريــخ ‪1434/8/22‬ه ـ ‪،‬‬\n      ‫املتضمــن دعــوى املــرأة ‪ ...‬ضــد الغائــب عــن مجلــس احلكــم ‪ ...‬يف نفقــة‪،‬‬\n      ‫وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة ‪ ،‬تقــررت‬\n\n\n‫‪327‬‬\n\f‫املوافقــة علــى احلكــم ‪ ،‬واهلل املوفــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد‬\n                                                ‫وعلــى الــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                               ‫‪328‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":320,"source_page_end":328,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"054fb0ab84428bb83c7416fdab110a3cd38e5124903b2804d28dce450abd54c6","normalized_text_hash":"7473fb733ad80565affefd781d727ad76f3ed43dadf260701f96eb734990a6f2","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p320-34302883"},{"id":"ab985c5a-d78f-5126-a484-d4f5b222c2ab","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -مطالبة أم بنفقة أوالدها املاضية واملستقبلية -قصر الطلب على النفقة املستقبلية -تقدير النفقة عن طريق قسم اخلبراء - حكم بالنفقة املستقبلية -حكم مشمول بالنفاذ املعجل.","document_number":"34222949","case_number":"152270508","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/26","year":"1434","subject":"نفقة -مطالبة أم بنفقة أوالدها املاضية واملستقبلية -قصر الطلب على النفقة املستقبلية -تقدير النفقة عن طريق قسم اخلبراء - حكم بالنفقة املستقبلية -حكم مشمول بالنفاذ املعجل.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/5/26 :‬هـ‬\n                       ‫ُ‬                 ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪34222949 :‬‬\n                         ‫َر ْق ُم الدعوى‪152270508 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34303321‬تاريخه‪1434/8/23:‬هـ‬\n\n\n\n      ‫نفقــة ‪ -‬مطالبــة أم بنفقــة أوالدهــا املاضيــة واملســتقبلية ‪ -‬قصــر الطلــب‬\n      ‫علــى النفقــة املســتقبلية ‪ -‬تقديــر النفقــة عــن طريــق قســم اخلبــراء ‪-‬‬\n                  ‫حكــم بالنفقــة املســتقبلية ‪ -‬حكــم مشــمول بالنفــاذ املعجــل‪.‬‬\n\n\n\n\n                                           ‫‪ -1‬قوله تعالى { ل ُِي ْنفِ ْق ُذو َس َع ٍة مِ نْ َس َع ِتهِ}‪.‬‬\n                                       ‫‪ -2‬املادة (‪ )198‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n      ‫ادعــت املدعيــة ضــد املدعــى عليــه أنــه كان زوجهــا ورزق منهــا بابنتــن‬\n      ‫تقيمــان عنــد والدتهمــا املدعيــة وقــررت أن املدعــى عليــه ال ينفــق علــى‬\n      ‫ابنتيــه وأنهــا تنفــق عليهمــا بنيــة الرجــوع وطالبــت بتقديــر النفقــة املاضيــة‬\n      ‫واملســتقبلية ‪ -‬أجــاب املدعــى عليــه باملصادقــة علــى الدعــوى وأنكــر‬\n      ‫عــدم نفقتــه املاضيــة علــى ابنتيــه ‪ -‬حصــرت املدعيــة دعواهــا يف املطالبــة‬\n      ‫بالنفقــة املســتقبلية ‪ -‬مت تقديــر النفقــة املســتقبلية عــن طريــق قســم‬\n      ‫اخلبــراء مببلــغ وقــدره ســتمائة ريــال لــكل واحــدة منهــن غيــر شــاملة‬\n      ‫للعــاج ‪ ،‬والكســوة وتكــون مضاعفــة يف العيديــن ‪ -‬وافقــت املدعيــة‬\n       ‫علــى التقديــر ‪ -‬لألســباب املرصــودة ولقولــه تعالــى { ل ُِي ْنفِ ـ ْـق ُذو َسـ َـع ٍة مِ ــنْ‬\n      ‫َسـ َـع ِتهِ} صــدر احلكــم بإلــزام املدعــى عليــه بتســليم املدعيــة نفقــة البنتــن‬\n\n‫‪329‬‬\n\f‫مبلغ ـ ًا قــدره ألــف ومائتــا ريــال وبذلــك صــدر احلكــم مشــمو ًال بالنفــاذ‬\n‫املعجــل ‪ -‬صــدر قــرار محكمــة االســتئناف مبكــة املكرمــة باملوافقــة‬\n                                                               ‫علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة جــدة املســاعد برقــم ‪152270508‬‬\n‫وتاريــخ ‪1431/05/24‬ه ـ املقيــدة باحملكمــة برقــم ‪ 3149652‬وتاريــخ‬\n‫‪1431/05/24‬ه ـ ففــي يــوم األحــد املوافق‪1434/01/11‬ه ـ حضــرت‬\n‫‪ .....‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم‪ .....‬واملعــرف بهــا مــن‬\n‫قبــل والدهــا ‪ .....‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم‪ .....‬ولــم‬\n‫يحضــر املدعــى عليــه وال مــن ميثلــه ولــم يتقــدم بعــذر‪ ،‬وقــد وردنــا أصــل‬\n‫ورقــة البــاغ موقعــة مــن عمــدة حــي املــروة وعليــه شــرح هــذا نصــه‪( :‬ســلم‬\n‫الطلــب ألهلــه يف منــزل‪ .‬هــذا مــا نفيدكــم بــه)‪ .‬ا‪ .‬ه ـ ونظــرا ألن البــاغ‬\n‫وقــع لغيــر شــخص املدعــى عليــه أفهمــت املدعيــة بإعــادة التبليــغ مــرة‬\n‫أخــرى حتــى يتــم الســير يف الدعــوى حســب التعليمــات‪ .‬ويف يــوم الســبت‬\n‫املوافــق‪1434/02/23 :‬ه ـ حضــرت املدعيــة واملعــرف بهــا كمــا حضــر‬\n‫املدعــى عليــه أصالــة‪ .....‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة‬\n‫رقــم‪ .....‬وادعــت األولــى قائلــة‪ :‬إن هــذا احلاضــر كان زوجــا لــي فقــد‬\n‫طلقنــي يف بدايــة شــهر شــعبان مــن عــام‪1429 :‬ه ـ وولــدت لــه علــى فــراش‬\n‫الزوجيــة بنتــن همــا‪ ...‬املولــودة بتاريــخ‪1422/12/13 :‬ه ـ و ‪ ...‬املولــودة‬\n‫يف شــهر جمــادى األولــى لعــام‪1430 :‬ه ـ ومنــذ تاريــخ طالقــي والبنتــن‬\n\n                                                                                     ‫‪330‬‬\n\f      ‫(‪ ).....‬تقيمــان عنــدي ولــم ينفــق عليهمــا والدهمــا املدعــى عليــه البتــة‪،‬‬\n      ‫وقــد كنــت أنفــق عليهــم بنيــة الرجــوع‪ ،‬أطلــب إلــزام املدعــى عليــه‬\n      ‫بتســليم النفقــة املاضيــة اعتبــارا مــن تاريــخ‪1429/8/22 :‬ه ـ حتــى تاريخ‪:‬‬\n      ‫‪1434/2/22‬ه ـ وحتديــد نفقــة مســتقبلية للطفلتــن‪ ،‬هكــذا ادعــت‪.‬‬\n      ‫وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائـاً‪ :‬مــا ذكرتــه املدعيــة مــن‬\n      ‫الــزواج والطــاق وتاريخــه والبنتــن واســمهما وتواريــخ والدتهمــا وأنهمــا‬\n      ‫يقيمــان عندهــا منــذ تاريــخ طالقهــا فــكل ذلــك صحيــح ولكنــي‬\n      ‫آخذهمــا بعــض األحيــان مــن املدعيــة يــوم األربعــاء واخلميــس واجلمعــة‪،‬‬\n      ‫وأمــا مــا ذكرتــه أننــي لــم أنفــق عليهمــا البتــة فغيــر صحيــح والصحيــح‬\n      ‫أننــي أنفــق عليهمــا منــذ طالقــي لوالدتهمــا حتــى اآلن‪ ،‬وال مانــع لــدي‬\n      ‫مــن حتديــد نفقــة مســتقبلية لبنتــي (‪ ،).....‬وأطلــب رد دعــوى املدعيــة‬\n      ‫جتــاه مطالبتهــا بالنفقــة الســابقة وإخــاء ســبيلي منهــا‪ ،‬هكــذا أجــاب‪.‬‬\n      ‫وبســؤاله عــن بينتــه يف ذلــك أجــاب قائــا‪ :‬أطلــب مهلــة إلحضارهــا‪،‬‬\n      ‫هكــذا أجــاب‪ .‬ويف يــوم األربعــاء املوافــق‪1434/04/24 :‬ه ـ حضــرت‬\n      ‫املدعيــة ووالدهــا املعــرف بهــا واملدعــى عليــه‪ :‬املثبت حضورهم يف جلســة‬\n      ‫ســابقة‪ ،‬وبســؤال املدعــى عليــه عمــا اســتمهل مــن أجلــه أحضــر للشــهادة‬\n      ‫وأدائهــا‪ .....، :‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم‪ .....‬وهــو‬\n      ‫مــن مواليــد عــام‪1382 :‬ه ـ ويعمــل يف ‪ ...‬ويســكن يف حــي ‪ .......‬وطــريف‬\n      ‫النــزاع مــن أبنــاء عمومتــه ويزيــد املدعــى أنــه أخ لزوجتــه ـ حســب إفادتــه ـ‬\n      ‫وشــهد قائــا‪( :‬أشــهد هلل أننــي أرى املدعــى عليــه يشــتري لبناتــه كســوة‬\n      ‫األعيــاد منــذ إقامتهــن عنــد والدتهــن‪ ،‬ورأيتــه مــا ال أحصــي يعطــي ابنتــه‬\n      ‫الكبيــرة (‪ ).....‬بعــد انتهــاء وقــت زيارتهــا لــه وقبــل الذهــاب بهــا لوالدتهــا‬\n      ‫مبالــغ ماليــة علــى فتــرات متفرقــة مــن (‪ 300‬ـ ‪ ،)500‬عمــا بــأن زوجتــي‬\n\n\n‫‪331‬‬\n\f‫تذهــب معــه لألســواق لشــراء كســوة لبناتــه‪ ،‬وقــد ســمعت املدعــى عليــه‬\n‫يكلــم املدعيــة عــن طريــق اجلــوال ويقــول للمدعيــة أنــه ســوف يتكفــل‬\n‫بتوصيــل بناتــه للمدرســة فامتنعــت املدعيــة)‪ ،‬هــذا مــا لــدي وبــه أشــهد‪.‬‬\n‫ثــم أضــاف الشــاهد مخاطبــا املدعــى عليــه‪( :‬اطلــب حضانــة أبنائــك‬\n‫مــن القاضــي كــي تربيهــم أنــت)‪ ،‬هكــذا أضــاف‪ .‬وبعــرض الشــاهد‬\n‫وشــهادته علــى املدعيــة أجابــت قائلــة‪ :‬هــو شــخص متحامــل علــي‪،‬‬\n                                   ‫وشــهادته غيــر صحيحــة‪ ،‬هكــذا أجابــت‪.‬‬\n‫وبســؤال املدعــى عليــه عــن زيــادة بينــة أحضــر للشــهادة وأدائهــا ‪..... ،‬‬\n‫ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم‪ .....‬وهــو مــن مواليــد عــام‪:‬‬\n‫‪1390‬ه ـ ويعمــل ‪ ....‬وليــس لــه قرابــة بالطرفــن ويســكن يف حــي ‪.......‬ـ‬\n‫حسب إفادته ـ وشهد قائال‪( :‬أشهد هلل أنني أكون كثيرا من األحيان‬\n‫مــع املدعــى عليــه وإذا انتهــت فتــرة الزيــارة وأراد أن يرجعهــم لوالدتهــم‬\n‫يشــتري لهــن كل مــا يحتاجونــه مــن اللبــاس وكســوة العيــد وأغــراض‬\n‫املدرســة وقبــل أن ينزلهــم يعطــي كل واحــدة مــن البنتــن مبلــغ يتــراوح‬\n‫مــا بــن ‪ 20‬ـ ‪ )50‬هــذا مــا لــدي وبــه أشــهد‪ .‬وبعــرض الشــاهد وشــهادته‬\n‫علــى املدعيــة أجابــت قائلــة‪ :‬بالنســبة للشــاهد فهــو مســتور احلــال‪ ،‬وأمــا‬\n‫شــهادته فهــي عليــه هــل يكفــي كل أســبوع أن يعطــي كل واحــدة‬\n‫مبلغــا قــدره‪ :‬خمســون ريــاال؟ هكــذا أجابــت‪ .‬وبســؤال املدعــى عليــه عــن‬\n‫زيــادة بينــة أجــاب قائــا‪ :‬أكتفــي مبــا قدمــت‪ ،‬هكــذا أجــاب‪ .‬ونظــرا‬\n‫لوصــول القضيــة لهــذا احلــد فقــد أمــرت بالكتابــة لقســم اخلبــراء لتقديــر‬\n‫نفقــة البنتــن (‪ )....... ، .......‬مــن تاريــخ‪1429/8/22 :‬ه ـ وحتديــد نفقــة‬\n‫مســتقبلية‪ .‬ويف يــوم األحــد املوافــق‪1434/05/26 :‬ه ـ حضــرت املدعيــة‬\n‫‪ .......‬ووالدهــا املعــرف بهــا ‪ ،‬ولــم يحضــر املدعــى عليــه‪ :‬رغــم تبلغــه‬\n\n\n                                                                                     ‫‪332‬‬\n\f      ‫مبوعــد هــذه اجللســة حســب توقيعــه علــى ضبــط اجللســة الســابقة‪ ،‬وقــد‬\n      ‫وردنــا كتــاب رئيــس قســم الصلــح رقــم‪ 3456691 :‬يف‪1434/4/22 :‬ه ـ‬\n      ‫ومرفــق بــه محضــر هــذا نصــه‪( :‬وحيــث ذكــرت املدعيــة بــأن املدعــى‬\n      ‫عليــه يعمــل ســائق أجــرة خاصــة وال يقــل دخلــه الشــهري منهــا مبلغ ـ ًا‬\n      ‫ثالثــة آالف ريــال وقــد ورث عــن والــده منــذ مــدة قريبــة جــد ًا ولديــه شــقة‬\n      ‫متليــك وهــو يعيــش مبفــرده وال يكفــل أحــد غيــر نفســه وليــس عليــه أي‬\n      ‫التزامــات وبنــاء عليــه فإننــا نــرى أن تقــدر نفقــة البنتــن (‪ ).....‬الشــهرية‬\n      ‫مببلــغ قــدره‪ :‬ســتمائة ريــال لــكل واحــدة منهــن غيــر شــاملة للعــاج وأمــا‬\n      ‫الكســوة فتكــون مضاعفــة يف العيديــن)‪ .‬ا‪ .‬ه ـ وبعــرض ذلــك علــى‬\n      ‫املدعيــة أجابــت قائلــة‪ :‬أنــا موافقــة علــى هــذا التقديــر‪ ،‬وأطلــب حصــر‬\n      ‫دعــواي يف املطالبــة بالنفقــة املســتقبلية‪ ،‬وأمــا الســابقة فســوف أقيــم‬\n      ‫فيهــا دعــوى مســتقلة الحقــا‪ ،‬وأطلــب تضمــن احلكــم بالنفــاذ املعجــل‪،‬‬\n      ‫هكــذا أجابــت‪ .‬فبنــاء علــى مــا ســلف‪ ،‬ولقــول اهلل ـ تعالــى ـ‪( :‬لينفــق‬\n      ‫ذو ســعة مــن ســعته)‪ ،‬ونظــر ًا حلاجــة البنتــن للنفقــة‪ ،‬وألن الوالــد جتــب‬\n      ‫عليــه نفقــة ولــده كاملــة ينفــرد بهــا‪ ،‬وألنــه جــرى تقديــر النفقــة لــكل‬\n      ‫واحــدة مــن البنتــن ســتمائة ريــال حســب القــرار املرصــود أعــاه‪ ،‬وبنــاء‬\n      ‫علــى املــادة الثامنــة والتســعون بعــد املئــة مــن نظــام املرافعــات الشــرعية‪،‬‬\n      ‫لذلــك كلــه فقــد ألزمــت املدعــى عليــه أن يســلم للمدعيــة نفقــة بنتيهــا‬\n      ‫(‪...‬و‪ )...‬بتاريــخ واحــد مــن كل شــهر هجــري مبلغــا قــدره‪ :‬ألــف ومئتــا‬\n      ‫ريــال اعتبــار ًا مــن شــهر جمــادى اآلخــر لعــام‪1434 :‬ه ـ وبذلــك حكمــت‬\n      ‫حكمــا مشــموال بالنفــاذ املعجــل‪ .‬وهــذا احلكــم يعــد حضوريــا يف حــق‬\n      ‫املدعــى عليــه‪ .‬وبإعــان احلكــم قــررت املدعيــة قناعتهــا باحلكــم‪ ،‬أمــا‬\n      ‫املدعــى عليــه فســوف يبلــغ باحلكــم ولــه االعتــراض بطلــب التمييــز‬\n\n\n‫‪333‬‬\n\f‫خــال ثالثــن يوم ـ ًا اعتبــار ًا مــن تاريــخ تبليغــه بنســخة احلكــم‪ ،‬وإذا‬\n‫تأخــر عــن هــذه املـ ّـدة ـ مــع تبلغــه لشــخصه بنســخة احلكــم ـ ســقط‬\n‫القطعيــة‪،‬‬\n      ‫ّ‬      ‫حقــه يف االعتــراض بطلــب االســتئناف واكتســب احلكــم‬\n‫وإذا تب َّلــغ لغيــر شــخصه ولــم يقـ ِّـدم اعتراضــه رفــع احلكــم لالســتئناف‬\n‫مــن دون اعتــراض‪ .‬وســوف يتــم الكتابــة للجهــة التنفيذيــة إلنفــاذ هــذا‬\n‫احلكــم عاجــا بكفالــة‪ .‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمد‬\n                      ‫وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/05/26‬ه ـ‬\n‫احلمــد هلل وحــده‪ ،‬وبعــد‪ :‬ويف يــوم اإلثنــن املوافــق‪1434/09/14 :‬ه ـ‬\n‫عــادت املعاملــة مــن محكمــة االســتئناف وبرفقهــا قــرار دائــرة األحــوال‬\n‫الشــخصية الثانيــة رقــم ‪ 34303321‬يف ‪1434/08/23‬ه ـ ونــص احلاجــة‬\n‫منــه‪( :‬وبدراســة احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر‬\n‫باألكثريــة املوافقــة علــى احلكــم) ا‪ .‬ه ـ وللبيــان جــرى إثباتــه‪ ،‬وأمــرت‬\n‫بإحلــاق ذلــك علــى الصــك والســجل‪ .‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى‬\n    ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‪1434/09/14 :‬ه ـ‬\n‫احلمــد هلل والصــاة والســام علــى مــن ال نبي بعــده ‪ ،‬وبعد فقد جرى منا‬\n‫نحــن قضــاة الدائــرة الثانيــة لألحــوال الشــخصية واألوقــاف والوصايــا‬\n‫والقصــار وبيــوت املــال مبحكمــة االســتئناف يف منطقــة مكــة‬\n‫املكرمــة االطــاع علــى الصــك الصــادر مــن فضيلــة الشــيخ‪ .....‬القاضــي‬\n‫باحملكمــة العامــة بجــدة برقــم ‪ 34222949‬وتاريــخ ‪ 1434/5/26‬ه ـ‬\n‫املتضمــن دعــوى‪ .....‬ضــد ‪ .....‬يف دعــوى نفقــة آدمــي وبدراســة الصــك‬\n‫وصــورة ضبطــه والالئحــة االعتراضيــة تقــرر باألكثريــة املوافقــة علــى‬\n‫احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه‬\n                                                                        ‫وســلم ‪.‬‬\n\n\n                                                                                   ‫‪334‬‬\n\f335\n\f336\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":329,"source_page_end":336,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6674a2f8557fdd2a6b7dfc89a1076d9543f25b9b99ce8a4e60a98fb085ae0964","normalized_text_hash":"a7b5a476e0a5cf91ac6136768423e9d2039acab463a4eb868a836a02a647384a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p329-34222949"},{"id":"0ca464b4-d922-5af7-9cb9-6deb3d01cd21","document_type":"judgment","category":"judicial","subcategory":"general","title":"زوجية -منع تدخل -مطالبة زوج والد زوجته بكف تدخله بينه وبن زوجته -مصادقة املدعى عليه على الدعوى وبرر تدخله بأن املدعي طلق ابنته وال بينة له بذلك -إنكار املدعي وقوع الطاق - األصل بقاء عقد النكاح -إلزام المحكمة املدعى عليه بكف يده عن زوجة املدعي -اعترض املدعى عليه -صدق احلكم.","document_number":"34352237","case_number":"34306303","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/6","year":"1434","subject":"زوجية -منع تدخل -مطالبة زوج والد زوجته بكف تدخله بينه وبن زوجته -مصادقة املدعى عليه على الدعوى وبرر تدخله بأن املدعي طلق ابنته وال بينة له بذلك -إنكار املدعي وقوع الطاق - األصل بقاء عقد النكاح -إلزام المحكمة املدعى عليه بكف يده عن زوجة املدعي -اعترض املدعى عليه -صدق احلكم.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"   ‫تاريخه‪1434/11/6 :‬هـ َر ْق ُم‬\n                          ‫ُ‬                   ‫َر ْق ُم َّ‬\n                                ‫الص ِّك‪34352237 :‬‬\n                                  ‫الدعوى‪34306303 :‬‬\n‫رقم قرار التصديق من محكمة االستئناف ‪35114060 :‬‬\n                                ‫تاريخه‪1434/1/14 :‬هـ‬\n\n\n            ‫زوجيــة ‪ -‬منــع تدخــل ‪ -‬مطالبــة زوج والــد زوجتــه بكــف تدخلــه بينــه‬\n            ‫وبــن زوجتــه ‪ -‬مصادقــة املدعــى عليــه علــى الدعــوى وبــرر تدخلــه بــأن‬\n            ‫املدعــي طلــق ابنتــه وال بينــة لــه بذلــك ‪ -‬إنــكار املدعــي وقــوع الطــاق ‪-‬‬\n            ‫األصــل بقــاء عقــد النــكاح ‪ -‬إلــزام احملكمــة املدعــى عليــه بكــف يــده عــن‬\n                              ‫زوجــة املدعــي ‪ -‬اعتــرض املدعــى عليــه ‪ -‬صــدق احلكــم‪.‬‬\n\n\n\n\n            ‫مــا اســتند إليــه القاضــي مــن املبــادئ العامــة وقواعــد اإلثبــات والعدالــة‬\n                                                                       ‫يف تســبيب حكمــه‪.‬‬\n\n\n\n\n            ‫أقــام زوج دعــوى يطالــب والــد زوجتــه بكــف اعتراضــه و انقيــاد‬\n            ‫زوجتــه لــه ‪ ،‬رفــض املدعــى عليــه انقيــاد ابنتــه للمدعــى بســبب طالقــه‬\n            ‫لهــا وال بينــة لــه بذلــك ‪ ،‬أنكــر املدعــي طــاق زوجتــة ‪ ،‬وألن األصــل‬\n            ‫بقــاء النــكاح وال بينــة علــى الطــاق حكمــت احملكمــة بإلــزام املدعــى‬\n            ‫عليــه بكــف اعتراضــه وانقيــاد ابنتــه لزوجهــا املدعــي ‪ ،‬اعتــرض املدعــى‬\n                                                                  ‫عليــه‪ -‬وصــدق احلكــم‬\n\n\n\n\n    ‫‪337‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة ‪ ..........‬وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة برقــم وتاريــخ املقيــدة باحملكمــة برقــم‬\n‫(‪ ).....‬وتاريــخ ‪ .....‬افتتحــت اجللســة الســاعة ‪ 09 : 00‬وفيهــا حضــر ‪..........‬‬\n‫بالســجل املدنــي رقــم ‪ ..........‬وادعــى علــى احلاضــر معــه (‪ ).....‬بالســجل‬\n‫املدنــي رقــم (‪ ).....‬قائــا يف دعــواه أنــه بتاريــخ عقــدت الــزواج علــى بنــت‬\n‫املدعــى عليــه ودخلــت بهــا بتاريــخ ‪1432/10/5‬ه ـ وســكنت معــي يف‬\n‫بيتــي يف محافظــة (‪ ).....‬ويف أواخــر شــهر جمــادى األولــى مــن عــام‬\n‫‪1433‬ه ـ كانــت زوجتــي املذكــورة يف بدايــة حملهــا وطلبــت منــي أن‬\n‫أذهــب بهــا إلــى بيــت والدهــا مبحافظــة (‪ ).....‬فرفضــت وجــاء والدهــا‬\n‫املدعــى عليــه وأخذهــا مــن بيتــي دون إذن منــي وال تــزال عنــد املدعــى‬\n‫عليــه واملدعــى عليــه يعتــرض انقيــاد زوجتــي املذكــورة لــي لــذا أطلــب‬\n‫إلــزام املدعــى عليــه بكــف اعتراضــه انقيــاد زوجتــي املذكــورة لــي‬\n‫هكــذا ادعــى وبســؤال املدعــى عليــه أجــاب بقولــه مــا ذكــره املدعــي‬\n‫مــن عقــد الــزواج علــى بنتــي املذكــورة بالتاريــخ املذكــور وأنــه دخــل‬\n‫بهــا بالتاريــخ املذكــور وســكنت معــه يف محافظــة (‪ ).....‬فصحيــح ومــا‬\n‫ذكــره املدعــي أنــي أخــذت بنتــي املذكــورة مــن بيتــه بــدون إذنــه فغيــر‬\n‫صحيــح بــل الصحيــح أنــي أخذت بنتي املذكــورة بتاريخ ‪1433/5/19‬هـ‬\n‫مــن بيــت املدعــي بــإذن مــن املدعــي ومــا ذكــره أن بنتــي املذكــورة ال‬\n‫تــزال عنــدي وأنــي اعتــرض انقيــاد بنتــي املذكــورة للمدعــي فصحيــح‬\n‫والســبب أنــه بتاريــخ ‪1433/5/21‬ه ـ ذهبــت ببنتــي املذكــورة إلــى بيــت‬\n\n                                                                                      ‫‪338‬‬\n\f      ‫املدعــي يف محافظــة (‪ ).....‬ووجــدت بيــت املدعــي مغلــق وانتظــرت عنــد‬\n      ‫بيــت املدعــي مــن الســاعة الرابعــة عصــر ًا إلــى آذان العشــاء وجــاء املدعــي‬\n      ‫وقــال املدعــي لــي ( بنتــك طالــق وورقتهــا جتيهــا وتأخــذ عفشــها كلــه‬\n      ‫اللــي يف البيــت) وأنــا معتــرض انقيــاد بنتــي املذكــورة للمدعــي لكــون‬\n      ‫املدعــي طلقهــا هكــذا أجــاب وبعــد ســماع الدعــوى واإلجابــة طلبــت مــن‬\n      ‫املدعــى وثيقــة عقــد الــزواج فأبــرز عقد الزواج رقــم ‪ 24/46/233‬وتاريخ‬\n      ‫‪1431/8/29‬ه ـ الصــادر مــن مــأذون عقــود األنكحــة (‪ ).....‬املصــرح‬\n      ‫لــه بإجــراء عقــود األنكحــة لســكان محافظــة جــدة املتضمــن عقــد‬\n      ‫نــكاح بالســجل املدنــي رقــم (‪ ).....‬علــى املــرأة ســجلها املدنــي رقــم(‪).....‬‬\n      ‫مرفقــه صورتــه باملعاملــة ثــم ســألت املدعــي عمــا ذكــره املدعــى عليــه‬\n      ‫مــن الطــاق فأجــاب املدعــي بقولــه مــا ذكــره املدعــى عليــه أنــي طلقــت‬\n      ‫زوجتــي املذكــورة فغيــر صحيــح هكــذا أجــاب ثــم طلبــت مــن املدعــى‬\n      ‫عليــه البينــة علــى طــاق املدعــي لزوجتــه املذكــورة فأجــاب بقولــه ال‬\n      ‫يوجــد لــدي بينــة هكــذا أجــاب وبنــاء علــى جميــع مــا تقــدم ومبــا أن‬\n      ‫املدعــى عليــه أقــر بالــزواج ومبــا أن املدعــى عليــه أقــر باعتراضــه انقيــاد‬\n      ‫بنتــه املذكــورة للمدعــي ومبــا أن املدعي أنكــر طالق زوجته املذكورة‬\n      ‫ولــم يثبــت املدعــى عليــه الطــاق لــذا فقــد حكمــت بإلــزام املدعــى عليــه‬\n      ‫بكــف اعتراضــه انقيــاد زوجــة املدعــي املذكــورة وبعــد النطــق باحلكم‬\n      ‫وتالوتــه عليهمــا أفهمتهمــا بطــرق االعتــراض املقــررة ومواعيدهــا فقــرر‬\n      ‫املدعــي قناعتــه وقــرر املدعــى عليــه عــدم قناعتــه وأفهمتــه مبراجعتنــا‬\n      ‫يــوم اخلميــس املوافــق ‪1434/11/6‬ه ـ الســتالم نســخة مــن صــك احلكــم‬\n      ‫وتقــدمي مذكــرة اعتراضيــة إلــى إدارة احملكمــة خــال مــدة أقصاهــا‬\n      ‫ثالثــون يومــا مــن التاريــخ احملــدد لالســتالم وإذا انتهــت املــدة ولــم يتقــدم‬\n\n\n‫‪339‬‬\n\f‫باعتراضــه فــإن احلــق يف طلــب االســتئناف يســقط ويكتســب احلكــم‬\n‫القطعيــة واختتمــت اجللســة الســاعة ‪ 09 : 25‬وبــاهلل التوفيــق وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/11/05‬ه‪.‬‬\n‫احلمــد هلل وحــده وبعــد يف هــذا اليــوم األربعــاء املوافــق ‪1435/02/01‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪11 : 00‬واملعاملــة قــد عــادت مــن محكمــة‬\n‫االســتئناف بالقصيــم وقــد مت التظهيــر علــى صــك احلكــم بقــرار دائــرة‬\n‫األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف مبنطقة القصيم‬\n‫رقم ‪ 35114060‬وتاريخ ‪1435/1/14‬هـ نصه (تظهيرات دائرة األحوال‬\n‫الشــخصية واإلنهــاءات مبحكمــة االســتئناف مبنطقــة القصيــم احلمــد‬\n‫هلل وحــده وبعــد فقــد اطلعنــا علــى هــذا الصــك رقــم ‪ 34352237‬وتاريــخ‬\n‫‪1434/11/6‬ه ـ الصــادر مــن فضيلــة الشــيخ القاضــي باحملكمــة العامة‬\n‫وأصدرنــا القــرار رقــم ‪ 35114060‬وتاريــخ ‪1435/1/14‬ه ـ املتضمــن‬\n‫املصادقــة علــى مــا حكــم بــه فضيلتــه قاضــي اســتئناف (‪ ).....‬قاضــي‬\n‫اســتئناف (‪ ).....‬رئيــس الدائــرة (‪ ).....‬أ‪ .‬ه ـ واختتمــت اجللســة الســاعة‬\n‫‪11 :10‬وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                              ‫وســلم‪ .‬حــرر يف ‪1435/2/1‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة املختصــة‬\n‫بتدقيــق قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n‫مبنطقــة القصيــم علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة مبحافظــة ‪ ..........‬برقــم (‪ )..........‬وتاريــخ ‪1435/1/9‬هــ؛ املقيــدة‬\n‫لــدى احملكمــة برقــم (‪ )..........‬وتاريــخ ‪1435/1/10‬هــ؛ اخلاصــة‬\n‫ب ــدعوى‪ ).....(/‬ضــد‪ ).....(/‬؛ بشــأن مطالبتــه بإلــزام املدعــى عليــه‬\n‫بكــف اعتراضــه انقيــاد زوجتــه‪).....(/‬؛ املنتهيــة بالصــك الصــادر مــن‬\n\n\n                                                                                    ‫‪340‬‬\n\f      ‫فضيلــة الشــيخ‪ ).....(/‬القاضــي باحملكمــة؛ املســجل برقــم () وتاريــخ‬\n      ‫‪1434/11/6‬هــ؛ املتضمــن حكــم فضيلتــه بإلــزام املدعــى عليــه بكــف‬\n      ‫اعتراضــه انقيــاد زوجــة املدعــي املذكــورة؛ علــى النحــو املفصــل فيــه‪.‬‬\n      ‫وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة‬\n      ‫قررنــا املصادقــة علــى مــا حكــم بــه فضيلتــه‪ .‬واهلل املوفــق‪ ،‬وصلــى اهلل‬\n                                         ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪341‬‬\n\f342\n\f343\n\f344\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":337,"source_page_end":344,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f5d895f131ef5f9e1c6a0a976bee123c878118d45050e14768773c15106e2587","normalized_text_hash":"85455408baefb95bf1e0193acb7a21add4634f326fa41bf366cca5bfc3c559f8","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p337-34352237"},{"id":"5cb99f47-c0a7-559b-8682-d1ae393e6bb9","document_type":"judgment","category":"judicial","subcategory":"general","title":"طلب إعادة خادمة -تخلف املدعى عليه عن احلضور مع تبلغه باملوعد لشخصه -تخلف املدعى عليه يعد نكو ال -رد اليمن إلى املدعي بصحة دعواه ألن احلق يعرف من جهته -إلزام املدعى عليه","document_number":"3462374","case_number":"33343992","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعنيزة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/15","year":"1434","subject":"طلب إعادة خادمة -تخلف املدعى عليه عن احلضور مع تبلغه باملوعد لشخصه -تخلف املدعى عليه يعد نكو ال -رد اليمن إلى املدعي بصحة دعواه ألن احلق يعرف من جهته -إلزام املدعى عليه","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/3/15 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪3462374 :‬‬\n                         ‫َر ْق ُم الدعوى‪33343992 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34228433‬تاريخه‪1434/6/3 :‬هـ‬\n\n\n      ‫طلــب إعــادة خادمــة ‪ -‬تخلــف املدعــى عليــه عــن احلضــور مــع تبلغــه‬\n      ‫باملوعــد لشــخصه ‪ -‬تخلــف املدعــى عليــه يعــد نكــو ًال ‪ -‬رد اليمــن إلــى‬\n      ‫املدعــي بصحــة دعــواه ألن احلــق يعــرف مــن جهتــه ‪ -‬إلــزام املدعــى عليــه‬\n                                                                      ‫بــرد اخلادمــة ‪.‬‬\n\n\n\n\n                                         ‫‪ -1‬املادة (‪ )55‬من نظام املرافعات الشرعية ‪.‬‬\n                                       ‫‪ -2‬املادة (‪ )101‬من نظام املرافعات الشرعية ‪.‬‬\n                                    ‫‪ -3‬املادة (‪ )2/103‬من نظام املرافعات الشرعية ‪.‬‬\n                                   ‫‪ -4‬املادة (‪ ) 5/179‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي أنــه كفــل خادمتــه للعمــل عنــده‪ ،‬وقــد عملــت عنــده فتــرة‬\n      ‫معينــة ثــم اســتغنى عنهــا‪ ،‬طلــب منــه املدعــى عليــه أخذهــا لتجربتهــا‬\n      ‫يف العمــل ثــم نقــل كفالتهــا إليــه فوافــق علــى ذلــك‪ ،‬مت تســليمها إليــه‬\n      ‫وبعــد ذلــك لــم يتوصــل إليــه بــأي طريقــة أو وســيلة‪ ،‬طلــب إلزامــه بإعــادة‬\n      ‫اخلادمــة‪ ،‬مت إبــاغ املدعــى عليــه بجميــع اجللســات إال أنــه لــم يحضــر‬\n      ‫ال عــن اليمــن حــال عــدم احلضــور‬    ‫كمــا مت إبالغــه باعتبــاره نــاك ً‬\n      ‫ولكــن دون جــدوى ‪ ،‬حيــث إن املدعــى عليــه غيــر متجــاوب فقــد أفهــم‬\n\n‫‪345‬‬\n\f‫القاضــي املدعــي بــأن عليــه أن يحلــف اليمــن علــى مــا جــاء بدعــواه ألن‬\n‫ال عــن اليمــن وهــذا مــن املواضــع التــي تــرد‬ ‫املدعــى عليــه يعــد نــاك ً‬\n‫فيهــا اليمــن علــى املدعــي ألن احلــق يعــرف مــن جهتــه كمــا نــص عليــه‬\n‫احملققــون كشــيخ اإلســام وابــن القيــم ‪ ،‬حلــف املدعــي اليمــن كمــا‬\n‫طلبــت منــه ‪ ،‬بنــاء علــى عــدم حضــور املدعــى عليــه مــع تبليغه لشــخصه ‪،‬‬\n‫ال واحلالــة هــذه ‪ ،‬وبنــاء علــى املادتــن‬\n                                          ‫وحيــث إن املدعــى عليــه يعــد نــاك ً‬\n‫(‪ )55‬و ( ‪ ) 2/103‬مــن نظــام املرافعــات الشــرعية ‪ ،‬صــدر احلكــم‬\n‫بإلــزام املدعــى عليــه بإعــادة اخلادمــة املذكــورة للمدعــي ‪ ،‬احلكــم يف‬\n‫حــق املدعــى عليــه يعــد حضوريـ ًا ‪ ،‬تســليم املدعــى عليــه نســخة احلكــم‬\n‫عــن طريــق محضــري اخلصــوم وإفهامــه بتعليمــات االســتئناف ‪ ،‬صــدق‬\n‫احلكــم مــن محكمــة االســتئناف ‪ ،‬ورد خطــاب الشــرطة بأنــه لــم يتــم‬\n‫تســليم صــورة احلكــم للمدعــى عليــه رغــم التــردد علــى منزلــه أكثــر‬\n‫مــن مــرة ويف أوقــات مختلفــة وهواتفــه مغلقــة بصفــة مســتمرة ‪ ،‬مت بعــث‬\n‫املعاملــة حملكمــة االســتئناف بنــاء علــى املــادة ( ‪ ) 5/179‬مــن نظــام‬\n‫املرافعــات الشــرعية ولوائحــه التنفيذيــة ‪ ،‬صــدق احلكــم مــن محكمــة‬\n                                                                    ‫االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد يف يــوم الثالثــاء املوافــق ‪1433/07/01‬ه ـ لــدي‬\n‫أنــا ‪ ......‬القاضــي يف احملكمــة العامــة بعنيــزة افتتحــت اجللســة يف‬\n‫وقتهــا احملــدد لســماعها يف الســاعة الثامنــة والنصــف صباحـ ًا للنظــر يف‬\n‫الدعــوى املقدمــة مــن ‪ ......‬ضــد ‪ ......‬واملقيــدة يف هــذه احملكمــة برقــم‬\n‫‪ 33921012‬يف ‪1433/05/16‬ه ـ واحملالــة لنــا بشــرح فضيلــة الرئيــس‬\n\n                                                                                    ‫‪346‬‬\n\f      ‫وقــد افتتحــت هــذه اجللســة بنــاء علــى املــادة اخلامســة واخلمســن مــن‬\n      ‫نظــام املرافعــات الشــرعية ولوائحــه التنفيذيــة وفيهــا حضــر ‪ ......‬ســعودي‬\n      ‫مبوجــب الســجل رقــم ‪ ......‬وادعــى علــى الغائــب عــن مجلــس القضــاء‬\n      ‫الــذي تبلــغ بهــذا املوعــد لشــخصه حســبما يظهر من ورقــة التبليغ املرفقة‬\n      ‫باملعاملــة قائــا يف حتريــر دعــواه لقــد اســتقدمت خادمــة مــن اثيوبيــا يف‬\n      ‫‪1432/09/15‬ه ـ وعملــت لــدي ســتة أشــهر ثــم اســتغنيت عنهــا فطلــب‬\n      ‫املدعــى عليــه منــي نقــل كفالتهــا إليــه فوافقــت علــى ذلــك ثــم أخذهــا‬\n      ‫منــي يف شــهر ربيــع األول مــن هــذا العــام ‪1433‬ه ـ لتجربتهــا متهيــد ًا لنقــل‬\n      ‫كفالتهــا إليــه واســتلم اجلــواز اخلــاص بهــا كذلــك لكنــه أغلــق هواتفــه‬\n      ‫ولــم يعــد يــرد علــى اتصاالتــي أطلــب إلزامــه بإعــادة هــذه اخلادمــة لــي‬\n      ‫هــذه دعــواي ثــم أفهمتــه بأنــه البــد مــن بيــان اســم هــذه اخلادمــة وإبــراز‬\n      ‫مســتند قدومهــا إلــى اململكــة ومســتند كفالتــه لهــا ففهــم ذلــك وطلــب‬\n      ‫إمهالــه إلحضــار ذلــك فأجيــب لذلــك ثــم رفعــت اجللســة ‪ .‬ثــم يف جلســة‬\n      ‫أخــرى حضــر املدعــي ولــم يحضــر املدعــى عليــه ولــم يقــدم عــذر ًا لتخلفــه‬\n      ‫ا إن اخلادمــة اســمها وهــي اثيوبيــة‬    ‫عــن احلضــور ثــم قــرر املدعــي قائ ـ ً‬\n      ‫اجلنســية وقــد دخلــت إلــى هــذه البــاد مبوجــب التأشــيرة رقــم (‪)......‬‬\n      ‫يف (‪1432/8/27‬هــ) لغــرض العمــل لــدي هكــذا قــرر ثــم أبــرز صــورة‬\n      ‫التأشــيرة املشــار إليهــا آنف ـ ًا والتقريــر الطبــي الصــادر لهــا للحصــول‬\n      ‫علــى إقامــة فوجدتهــا مطابقــة ملــا قــرره املدعــي آنف ـ ًا ‪ .‬ثــم يف جلســة‬\n      ‫أخــرى حضــر املدعــي ولــم يحضــر املدعــى عليــه ولــم يردنــا أي رد مــن‬\n      ‫شــرطة عنيــزة علــى خطابنــا املرفــوع إليهــم يف ‪1433/8/6‬ه ـ املطلــوب‬\n      ‫فيــه إحضــار املدعــى عليــه بنــاء علــى املــادة (‪ )101‬مــن نظــام املرافعــات‬\n      ‫الشــرعية ثــم جــرى ســؤال املدعــي ألديــك بينــة علــى مــا جــاء يف دعــواك‬\n\n\n‫‪347‬‬\n\f‫فقــال ليــس لــدي بينــة وأطلــب إحضــار املدعــى عليــه فــان أنكــر ذلــك‬\n‫فإننــي أطلــب توجيــه اليمــن إليــه ثــم رفعــت اجللســة إلحضــار املدعــى‬\n‫عليــه بنــاء علــى املــادة (‪ )101‬مــن نظــام املرافعــات الشــرعية وإبالغــه بــأن‬\n‫ال عــن أداء‬‫املدعــي قــد طلــب ميينــه وأنــه إذا لــم يحضــر فســوف يعــد نــاك ً‬\n‫اليمــن ‪ .‬ثــم يف جلســة أخــرى حضــر املدعــي ولــم يحضــر املدعــى عليــه‬\n‫وقــد وردنــا أصــل ورقــة التبليــغ مــن قســم محضــري اخلصــوم املتضمنــة‬\n‫اإلفــادة بأنــه مت االتصــال علــى األرقــام اخلاصــة باملدعــى عليــه فكانــت‬\n‫مقفلــة وأنــه مت الذهــاب إلــى منزلــة عــدة مــرات فلــم يوجــد بــه أحــد ‪ .‬أ ‪ .‬هـ‬\n‫‪ .‬ونظــرا ألن املدعــى عليــه غيــر متجــاوب فقــد أفهمــت املدعــي بــأن عليــه‬\n‫أن يحلــف ميينــا علــى مــا جــاء يف دعــواه ألن املدعــى عليــه يعــد نــاكال‬\n‫عــن أداء اليمــن وهــذان مــن مواضــع رد اليمــن ألن احلــق يعــرف مــن جهــة‬\n‫املدعــي ثــم قــرر املدعــي قائــا إننــي مســتعد ألداء اليمــن ثــم حلــف بــاهلل‬\n‫قائــا واهلل العظيــم إننــي اتفقــت مــع املدعــى عليــه علــى أن يأخــذ منــي‬\n‫اخلادمــة املذكــورة يف هــذه الدعــوى وهــي إثيوبيــة اجلنســية لتجربتهــا‬\n‫ثــم نقــل كفالتهــا إليــه واســتالمه جلوازهــا يف شــهر ربيــع األول مــن عــام‬\n‫‪1433‬ه ـ وأنهــا مازالــت عنــده ولــم ينقــل كفالتهــا أن هــذا كلــه صحيــح‬\n‫هكــذا حلــف فبنــاء علــى مــا ســبق مــن الدعــوى واإلجابــة ونظــرا ألن‬\n‫املدعــى عليــه قــد تبلــغ لشــخصه بــأول موعــد ولــم يحضــر أي جلســة وملــا‬\n‫جــاء يف املــادة (‪ )55‬مــن نظــام املرافعــات الشــرعية ولوائحــه التنفيذيــة‬\n‫وألن املدعــى عليــه يعتبــر نــاكال عــن أداء اليمــن وألن املدعــي قــد‬\n‫حلــف اليمــن الالزمــة شــرعا حســبما طلبــت منــه وألن هــذه الدعــوى‬\n‫ممــا يدخــل فيهــا رد اليمــن إلــى املدعــي ألن احلــق يعــرف مــن جهتــه‬\n‫كمــا نــص علــى ذلــك جمــع مــن احملققــن كشــيخ اإلســام ابــن تيميــة‬\n\n\n                                                                                         ‫‪348‬‬\n\f      ‫وابــن القيــم وملــا جــاء يف املــادة (‪ )2/103‬مــن نظــام املرافعــات الشــرعية‬\n      ‫لذلــك كلــه فقــد ألزمــت املدعــى عليــه بــان يعيــد اخلادمــة املذكــورة يف‬\n      ‫الدعــوى إلــى املدعــي وبذلــك حكمــت ويعــد احلكــم يف حقــه حضوريــا‬\n      ‫ثــم أمــرت بتســليم املدعــى عليــه نســخة مــن احلكــم عــن طريــق محضــري‬\n      ‫اخلصــوم لتقــدمي اعتراضــه خــال مــدة أقصاهــا ثالثــون يومــا مــن تاريــخ‬\n      ‫اســتالمه لــه وأنــه إذا لــم يقــدم اعتراضــه خــال هــذه املــدة فــإن حقــة‬\n      ‫يســقط يف التمييــز ويصبــح احلكــم مكتســبا القطعيــة وعليــه جــرى‬\n      ‫التوقيــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                      ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/03/15‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ويف يــوم الســبت املوافــق ‪1434/5/18‬ه ـ افتتحــت‬\n      ‫اجللســة يف الســاعة الثامنــة وخمســة وأربعــون دقيقــة بنــاء علــى ورود‬\n      ‫خطــاب مديــر شــرطة عنيــزة رقــم ‪ 3/16/2304/31‬يف ‪1434/5/12‬ه ـ‬\n      ‫واملتضمــن أنــه لــم يتــم تســليم صورة احلكم للمدعى عليــه ‪ ...‬رغم التردد‬\n      ‫علــى منزلــه أكثــر مــن مــرة ويف أوقــات مختلفــة وهواتفــه مغلقــة بصفــة‬\n      ‫مســتمرة أ‪.‬ه ـ ولذلــك فقــد أمــرت ببعــث املعاملــة حملكمــة االســتئناف‬\n      ‫بالقصيــم لتدقيــق احلكــم بنــاء علــى املــادة ‪ 5/179‬مــن نظــام املرافعــات‬\n      ‫الشــرعية ولوائحــه التنفيذيــة وصلــى اهلل وســلم علــى نبينــا محمــد حــرر‬\n                                                                 ‫يف ‪1434/5/18‬هـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ،‬يف يــوم األربعــاء املوافــق ‪1434/6/14‬ه ـ‬\n      ‫افتتحــت اجللســة يف الســاعة العاشــرة والنصــف صباحــا بنــاء علــى ورود‬\n      ‫املعاملــة مــن محكمــة االســتئناف بالقصيــم برقــم ‪ 341262902‬يف‬\n      ‫‪1434/6/11‬ه ـ مــزودة بقــرار أصحــاب الفضيلــة قضــاة االســتئناف‬\n      ‫بالدائــرة احلقوقيــة األولــى بالقصيــم رقــم ‪ 34228433‬يف ‪1434/6/3‬ه ـ‬\n\n\n‫‪349‬‬\n\f‫املقــرر فيــه املصادقــة علــى احلكــم أ ‪ .‬ه ـ ‪ .‬وقــد جــرى التهميــش بذلــك‬\n‫علــى الضبــط وســجله حســب التعليمــات وعليــه جــرى التوقيــع وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                       ‫حــرر يف ‪ 1434/06/14‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى نبينــا محمــد وعلى آلــه وصحبه‬\n‫وبعــد ‪،‬فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة األولــى مبحكمــة‬\n‫االســتئناف مب ـ ــنطقة القصـ ــيم علــى الـمـعــامـلـ ــة ال ــواردة م ــن فـض ــيلة‬\n‫رئيــس احملكمــة العامــة مبحافظــة عنيــزة برقــم (‪ )33921012‬وتــاري ـ ــخ‬\n‫‪1434/5/21‬ه ـ ؛ الـمح ــالة إلـيـنـ ــا بـرق ــم (‪ )34240941‬الـمـرف ــق به ــا‬\n‫الـص ــك الـمسج ــل بـرق ــم (‪ )3462374‬وتاريخ ‪1434/3/15‬هـ ؛ الصادر‬\n‫مــن فضيلــة الشــيخ ‪ ......‬القاضــي باحملكمــة؛ اخلــاص بدعــوى ‪ ......‬ضــد‬\n‫‪ ، ......‬بشــأن املطالبــة بإعــادة خادمــة أثيوبيــة‪ ،‬وقــد تضمــن الصــك‬\n‫حكــم فضيلتــه بإلــزام املدعــى عليــه بــأن يعيــد اخلادمــة إلــى املدعــي؛‬\n‫علــى النحــو املفصــل فيــه‪ .‬وبدراســة الصــك وصــورة ضبطــه وأوراق‬\n‫املعاملــة تقــرر املصادقــة علــى احلكــم‪ .‬واهلل املوفــق‪ ،‬وصلــى اهلل علــى‬\n                                         ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                        ‫‪350‬‬\n\f351\n\f352\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":345,"source_page_end":352,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5b2679c38dc568466615e684aee2e21fda87bb9be8bc955ef205e246c2a05be2","normalized_text_hash":"d5b0666cc920d065b82037dbc65cee90b3495644e9f08ff5fec85d36c4634f75","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p345-3462374"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"393f893e-040a-5c36-bf2f-b6ef8e07133a","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -نفقة أبناء -املطالبة بالنفقة على ضوء مركز املدعى عليه الوظيفي ووضع األسرة االجتماعي -املطالبة مبصاريف الدراسة -املطالبة مبصاريف العاج -املطالبة بتجديد جوازات سفر األوالد وإعطائها لأم ودفع تذاكر السفر -املطالبة بصورة من دفتر العائلة -املطالبة بفرق النفقة عما دفعة املدعى عليه وعما مت تقديره من قسم اخلبراء -حلف الزوجة على عدم نفقة الزوج -احلكم بدفع فرق النفقة املاضية ودفع النفقة املستقبلية .","document_number":"34268722","case_number":"32151993","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/10/29","year":"1434","subject":"نفقة -نفقة أبناء -املطالبة بالنفقة على ضوء مركز املدعى عليه الوظيفي ووضع األسرة االجتماعي -املطالبة مبصاريف الدراسة -املطالبة مبصاريف العاج -املطالبة بتجديد جوازات سفر األوالد وإعطائها لأم ودفع تذاكر السفر -املطالبة بصورة من دفتر العائلة -املطالبة بفرق النفقة عما دفعة املدعى عليه وعما مت تقديره من قسم اخلبراء -حلف الزوجة على عدم نفقة الزوج -احلكم بدفع فرق النفقة املاضية ودفع النفقة املستقبلية .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/10/29 :‬هـ‬\n                        ‫ُ‬                 ‫َر ْق ُم َّ‬\n                            ‫الص ِّك‪34268722 :‬‬\n                           ‫َر ْق ُم الدعوى‪32151993 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34361404‬تاريخه‪1434/11/18 :‬هـ‬\n\n\n        ‫نفقــة ‪ -‬نفقــة أبنــاء ‪ -‬املطالبــة بالنفقــة علــى ضــوء مركــز املدعــى‬\n        ‫عليــه الوظيفــي ووضــع األســرة االجتماعــي‪ -‬املطالبــة مبصاريــف‬\n        ‫الدراســة‪ -‬املطالبــة مبصاريــف العــاج‪ -‬املطالبــة بتجديــد جــوازات‬\n        ‫ســفر األوالد وإعطائهــا لــأم ودفــع تذاكــر الســفر‪ -‬املطالبــة بصــورة‬\n        ‫مــن دفتــر العائلــة‪ -‬املطالبــة بفــرق النفقــة عمــا دفعــة املدعــى عليــه‬\n        ‫وعمــا مت تقديــره مــن قســم اخلبــراء‪ -‬حلــف الزوجــة علــى عــدم نفقــة‬\n        ‫الــزوج‪ -‬احلكــم بدفــع فــرق النفقــة املاضيــة ودفــع النفقــة املســتقبلية ‪.‬‬\n\n\n\n\n                  ‫‪ -1‬قوله تعالى ( وعلى املولود له رزقهن وكسوتهن باملعروف)‬\n                   ‫‪ -2‬قوله صلى اهلل عليه وسلم ( ابدأ بنفسك ثم مبن تعول)‬\n        ‫‪ -3‬قــال يف كشــاف القنــاع ( ويجــب عليــة أيضـ ًا نفقــة ولــده وإن ســفل‪.‬‬\n        ‫وألن النفقــة واجبــة علــى اإلنســان علــى نفســه وزوجتــه فكــذا هي واجبة‬\n                                                                ‫علــى بعضــه وأصلــه )‬\n        ‫‪ -4‬قــال يف الشــرح الكبيــر( ويلزمــه نفقــة ســائر آبائــه وإن علــو وأوالده‬\n                                                                          ‫وإن ســفلوا)‬\n        ‫‪ -5‬قــال يف شــرح منتهــى اإلرادات ( فيجــب إعفــاف مــن جتــب نفقتــه مــن‬\n        ‫اآلبــاء واألجــداد واألوالد واألخــوة واألعمــام ويقــدم إن ضــاق الفاضــل‬\n                                                                   ‫األقــرب فاألقــرب )‬\n\n‫‪299‬‬\n\f‫ادعــى املدعــي وكالــة بــأن موكلتــه كانــت زوجــه للمدعــى عليــه‬\n‫وأجنبــت منــه ابنــن ( ذكــر أســماءهما وأعمارهمــا ) وقــد فارقهــا وهــو‬\n‫ينفــق عليهمــا تســعمائة ريــال وهــو ال يكفــي‪ -‬طلــب املدعــى وكالــة‬\n‫نفقــة الولديــن املذكوريــن مــع مصاريــف الدراســة ومصاريــف العــاج‬\n‫علــى ضــوء مركــز املدعــى عليــه الوظيفــي ووضــع األســرة االجتماعــي‪-‬‬\n‫مطالبــة املدعــى عليــه بتجديــد جــوازات الســفر حــال انتهائهــا وتســليمها‬\n‫لوالدتهمــا وإعطائهــا إذن بالســفر ودفــع تذاكــر الســفر حال ســفرهم أو‬\n‫يلتــزم بأخــذ األوالد عنــد ســفر والدتهــم‪ -‬أقــر املدعــى عليــه وكالــة بــأن‬\n‫موكلــة ينفــق تســعمائة ريــال شــهري ًا لــكل ابــن ‪ 450‬ريــال حتــى شــهر‬\n‫ذي احلجــة عــام ‪1433‬ه ـ وأن ســبب إقامــة الدعــوى تلطيــخ ســمعة موكلــة‬\n‫وابتــزازه مادي ـ ًا ‪ -‬ورد جــواب مكتــب الصلــح املتضمــن تعــذر الصلــح‬\n‫وتقديــر نفقــة كل ابــن شــهري ًا بألــف ومائتــي ريــال ‪ -‬طلــب املدعــي‬\n‫وكالــة إلــزام املدعــى عليــه بتســليم الفــرق بــن مــا كان يدفعــه وبــن مــا‬\n‫مت تقديــره ‪ -‬قــرر املدعــى عليــه بأنــه حصــل اتفــاق شــفوي علــى أن نفقــة‬\n‫االبنــن الشــهرية ‪ 900‬ريــال ‪ -‬أنكــر املدعــي وكالــة هــذا الدفــع وقــرر‬\n‫أن موكلتــه تنفــق علــى ابنيهــا املبلــغ الزائــد ‪ 900‬ريــال بنيــة الرجــوع‪-‬‬\n‫قــرر املدعــى عليــه أنــه يطلــب ميــن املدعيــة علــى أنهــا أنفقــت علــى أبنيــة‬\n‫نفقــة زائــدة عمــا ســلمه لهــا بنيــة الرجــوع وعلــى نفــي االتفــاق الشــفوي‬\n‫املذكــور ‪ -‬حلفــت املدعيــة أصالــة اليمــن كمــا طلــب منهــا ‪ -‬لقولــه‬\n‫تعالــى ( وعلــى املولــود لــه رزقهــن وكســوتهن باملعــروف) وقولــه صلــى‬\n‫اهلل عليــه وســلم ( ابــدأ بنفســك ثــم مبــن تعــول) وملــا ذكــره أهــل العلــم‬\n\n                                                                                        ‫‪300‬‬\n\f      ‫مــن وجــوب نفقــة األب علــى أوالدة لــذا صــدر احلكم بإلــزام املدعى عليه‬\n      ‫بدفــع فــرق النفقــة الســابقة علــى ابنــه للمدعيــة ( وذكــر مقــدار املبلــغ) ‪-‬‬\n      ‫وإلــزام املدعــى عليــه بدفــع نفقــة مســتقبلية لالبنــن كل شــهر وهــو مبلــغ‬\n      ‫ألفــان وأربعمائــة ريــال لــكل واحــد ألــف ومائتــي ريــال تســلم للمدعيــة‬\n      ‫بالتحويــل إلــى حســابها وفقــا ملــا مت تقديــره مــن قســم اخلبــراء ‪ -‬لــم يقنــع‬\n            ‫املدعــى عليــه باحلكــم‪ -‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالريــاض برقــم ‪ 32151993‬وتاريــخ ‪1432/05/01‬ه ـ املقيــدة‬\n      ‫باحملكمة برقم ‪ 32478496‬وتاريخ ‪1432/05/01‬هـ ففي يوم الثالثاء‬\n      ‫املوافق‪1433/05/18‬ه ـ افتتحــت اجللســة وفيهــا ‪...‬يحمــل الســجل املدنــي‬\n      ‫رقــم ‪ ...‬وكيــا عــن ‪ ...‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل‬\n      ‫الثانيــة بالريــاض رقــم ‪ 58859‬وتاريــخ ‪1432/08/08‬ه ـ واملتضمنــة بــأن‬\n      ‫لــه حــق املرافعــة و املدافعــة واملخاصمــة وإقامــة الدعــاوى وحــق ســماع‬\n      ‫الدعــاوى والــرد عليهــا واإلقــرار واإلنــكار و الصلــح وطلــب وقبــول‬\n      ‫احلكــم ونفيــه واالعتــراض عليــه وطلــب متييــزه ولــم يحضــر املدعــى عليــه‬\n      ‫ولــم يظهــر تبلغــه ويف جلســة أخــرى بتاريــخ ‪1433/10/14‬ه ـ حضــر‬\n      ‫املدعــي وكالــة احلاضــر يف اجللســة املاضيــة‪ ،‬ولــم يحضــر املدعــى عليــه‬\n      ‫وقــد اعتــذر عــن حضــور هــذه اجللســة‪ ،‬وبســؤال املدعــي وكالــة عــن‬\n      ‫دعــواه قــال‪ :‬لقــد كانــت موكلتــي زوجــة للمدعــى عليــه ‪ ...‬حيــث عقــد‬\n\n‫‪301‬‬\n\f‫عليهــا يف عــام ‪1420‬ه ـ وأجنبــت منــه علــى فــراش الزوجيــة كل مــن‪:‬‬\n‫‪...‬املولــود يف ‪1427/4/4‬ه ـ ‪... ،‬املولــود يف ‪1430/1/8‬ه ـ وقــد فارقهــا‬\n‫أول هــذه الســنة ‪1433‬هــ‪ ،‬وهــو ينفــق عليهــم مبلــغ تســعمائة ريــال كل‬\n             ‫شــهر وهــو ال يكفــي‪ ،‬ولــذا فــإن موكلتــي تطالــب باآلتــي ‪:‬‬\n                                         ‫‪ -1‬نفقة أوالدها املذكورين ‪ ...‬و ‪....‬‬\n‫وتشــمل النفقــة املــأكل واملشــرب واملســكن ونفقــة املالبــس صيف ـ ًا‬\n‫وشــتاء واألعيــاد ومناســبات األفــراح‪ ..‬وأجــرة احلضانــة لرعايتهــم وتدبيــر‬\n‫شــؤونهم حيــث إن والدتهــم تبحــث عــن عمــل وجدتهــم طاعنــة يف الســن‬\n‫وتعانــي مــن أمــراض مزمنــة وهــم بحاجــة إلــى رعايــة أثنــاء غيــاب والدتهم‬\n‫وتطلــب أن تكــون النفقــة علــى ضــوء مركــز املدعــى عليــه الوظيفــي‬\n‫و الوضــع االجتماعــي لــه ولهــا حيــث أنهمــا مــن أســرتني مرموقتــن‬\n                                                                     ‫اجتماعي ـاً‪.‬‬\n‫‪ -2‬تطالــب بإلــزام املدعــى عليــه بدفــع مصاريــف الدراســة (املســتلزمات‬\n‫الدراســية ورســوم الدراســة والنقــل املدرســي) حســبما يقــدره هيئــة‬\n‫اخلبــراء ‪ .‬أو يلتــزم بتدريســهم مبعرفتــه يأخذهــم صباحــا ويعيدهــم بعــد‬\n                                                         ‫اخلــروج مــن املدرســة ‪.‬‬\n‫‪ -3‬مصاريــف العــاج بحيــث يلتــزم بدفــع فواتير العــاج يف حال حاجتهم‬\n                    ‫إلــى طبيــب خــاص أو يلتــزم بأخذهــم للطبيب وإعادتهم ‪.‬‬\n‫‪ -4‬إلــزام املدعــى عليــه بتجديــد جــوازات ســفر األوالد حــال انتهائهــا‬\n‫‪-‬حيــث أن لهــم جــوازات‪ -‬وتســليمها لوالدتهــم وإعطائهــم إذن بالســفر‬\n‫ودفــع تذاكــر الســفر حــال ســفرهم حيــث أن موكلتــي تقــوم بالســفر‬\n‫مــع أهلهــا إلــى أقاربهــم خــارج اململكة ‪ .‬أو يلتــزم بأخذ األوالد عنده عند‬\n‫ســفر والدتهــم هــذه دعــواي‪ .‬ويف جلســة أخــرى بتاريــخ ‪1434/02/24‬ه ـ‬\n\n\n                                                                                     ‫‪302‬‬\n\f      ‫حضــر املدعــي وكالــة احلاضــر ســابقا كمــا حضــر ‪ ...‬حامــل بطاقــة‬\n      ‫الهويــة الوطنيــة رقــم ‪ ...‬وكيــا عــن ‪ ...‬بالوكالــة رقــم ‪34217943‬‬\n      ‫وتاريــخ ‪1434/2/23‬ه ـ الصــادرة مــن كتابــة عــدل جنــوب الريــاض‬\n      ‫وبســؤاله عــن جوابــه عــن دعــوى املدعــي قــال صحيــح بــأن املدعيــة‬\n      ‫كانــت زوجــة ملوكلــي و قــد طلقهــا و بانــت منــه و أجنبــت لــه ولديــن ‪...‬‬\n      ‫املولــود ‪1427/4/4‬ه ـ ‪ ...‬املولــود ‪1430/1/8‬ه ـ و هــو ينفــق علــى ابنيــه‬\n      ‫نفقتــه الشــهرية قدرهــا ‪900‬ريــال لالبنــن لــكل واحــد ‪ 450‬ريــال حتــى‬\n      ‫شــهر ذي احلجــة عــام ‪1433‬ه ـ هكــذا أجــاب كمــا أبــرز مذكــرة‬\n      ‫وطلــب رصدهــا و هــذا نصهــا (إشــارة إلــى الدعــوى املقامــة مــن املدعيــة‬\n      ‫‪ ...‬ض ــد موكلــي ‪ ...‬واملنظــورة أمــام فضيلتكــم‪ ،‬أفيدكــم حفظكــم‬\n      ‫اهلل أن هــذه الدعــوى ليســت مقصــودة لذاتهــا وإمنــا قصــد بهــا أمران‪:‬ـ ـ‬\n      ‫األمــر األول‪ :‬تلطيــخ ســمعة موكلــي برفــع الدعــاوى عليــه باحملاكــم ‪،‬‬\n      ‫وأيضـ ًا ســمعته يف عملــه وأنــه صاحــب مشــاكل لدرجــة أنــه قـ ّـدم تقاعــد‬\n      ‫مبكــر مــن عملــه ‪ ،‬ومــا يثبــت ذلــك أنهــم يأتــون إليــه يف عملــه بطلبــن‬\n      ‫إلبالغــه عــن موعــد جلســة واحــدة فقــط ‪ ،‬فعلــى مــاذا يــدل ذلــك ؟ علمـ ًا‬\n      ‫أنهــم يعرفــون منزلــه فبإمكانهــم توصيــل طلــب احلضــور لــه يف بيتــه‪،‬‬\n      ‫واملــازم لديكــم الشــيخ ‪ ...‬وجــه للمدعيــة ووالدهــا خطــاب بعــدم إزعــاج‬\n      ‫املدعــى عليــه أو التعــرض لــه بــاألذى ‪ ،‬ومــع ذلــك لــم يبالــوا ولــم يكترثوا‬\n      ‫بــكالم املــازم‪ ،‬وضربــوا بــه عــرض احلائــط ‪ ،‬واســتمروا يف اإليــذاء‬\n      ‫واإلزعــاج‪ .‬األمــر الثانــي ‪ :‬إبتــزاز موكلــي وإســتنزافه مادي ـ ًا ومعنوي ـ ًا‬\n      ‫أن موكلــي مســتمر يف النفقــة لولديــه (‪ ...‬و ‪)......‬‬  ‫قــدر املســتطاع حيــث ّ‬\n      ‫ويدفــع لهــم شــهري ًا تســعمائة ريــال ( ‪ 900‬ريــال ) يحولهــا يف حســاب‬\n      ‫والدتهــم مبصــرف ‪ ...........‬ولدينــا كشــف بذلــك ‪ ،‬ثــم طلبــت والدتهــم‬\n\n\n‫‪303‬‬\n\f‫أســرة فاخــرة لولديــه فاشــترى لهــم ذلــك وأرســلها لهــم يف بيــت أهلهــا‪،‬‬\n‫أمــا مســألة التوصيــل إلــى املدرســة فالعــام املاضــي لــم تطلــب املدعيــة‬           ‫ّ‬\n‫ـأن املدرســة قريبــة جــد ًا مــن‬  ‫نفقــات توصيــل اإلبــن للمدرســة‪ ،‬علم ـ ًا بـ ّ‬\n‫البيــت‪ ،‬وأيضـ ًا عنــد أهلهــا ثالثــة ســائقني وكلهــم يذهبــون كل صبــاح‬\n‫بأطفالهــم وأوالدهــم إلــى املــدارس وإبنــي علــى طريقهــم كل يــوم ليــس‬\n‫مما‬ ‫لــه مشــوار خــاص أو طريــق خــاص غيــر طريــق الســائق كل صبــاح‪ّ ،‬‬\n‫أن القصــد مــن الدعــوى اإلبتــزاز واإليــذاء ليــس إالّ‪ .‬ويؤيــد مــا‬       ‫يــدل علــى ّ‬\n‫أن املدعية طلبت مرة من موكلي مبلغ ًا من املال لتعيني‬                     ‫ذكرته لكم ّ‬\n‫ـاء لشــرها وكــف أذاهــا حـ ّـول لهــا مبلغـ ًا‬   ‫مــن ينقــل إبنهمــا للمدرســة فإتقـ ً‬\n‫فلمــا حـ ّـول لهــا املبلــغ لتعيــن‬\n                                  ‫لتعيــن مــن ينقــل االبــن ـ ـ علــى حـ ّـد زعمهــا ـ ـ ّ‬\n‫ا‬ ‫ألن االبــن أصـ ً‬  ‫مــن ينقــل اإلبــن أكلــت املــال ولــم تعــن مــن ينقــل اإلبــن‪ّ ،‬‬\n‫يذهــب مــع ســائقهم‪ ،‬فليــس املقصــود مــن الدعــوى أساس ـ ًا إ ّال األذى‬\n‫واإلبتــزاز بــكل مــا تســتطيع‪ .‬لــذا أطلــب مــن فضيلتكــم صــرف النظــر‬\n‫عــن دعــوى املدعيــة حيــث يتضــح لكــم مــن خــال اإلطــاع علــى األوراق‬\n‫واملســتندات أنهــا دعــوى كيديــة‪ .‬نســأل اهلل العافيــة والســامة )أ‪.‬ه ـ‬\n‫وبعــرض ذلــك علــى املدعــي وكالــة قــال بالنســبة إلقامــة الدعــوى فليــس‬\n‫فيهــا تلطيــخ للســمعته كمــا ذكــر املدعــى عليهــا ولــم يحصــل ملوكلتــي‬\n‫إزعــاج لــه وبالنســبة لبــاغ احلضــور الــذي ذكــر فــإن وكيــل املدعيــة‬\n‫‪...‬ذهــب للمدعــى عليــه يف املدرســة وعندمــا ســلمه طلــب احلضــور طلــب‬\n‫منــه أخــذ مصادقــة رئيســة ومديــره علــى البــاغ فرفــض املدعــى عليــه‬\n‫ذلــك فــرأى الوكيــل الســابق أن يرســل البــاغ لــه عــن طريــق احملضريــن‬\n‫فــكان ذلــك وليــس يف ذلــك شــيء وأمــا االبتــزاز فليــس هنالــك إبتــزاز‬\n‫ولكــن املبلــغ الــذي يدفعــه املدعــى عليــه وهــو أربعمائــة وخمســون ريــاال‬\n\n\n                                                                                               ‫‪304‬‬\n\f      ‫لــكل طفــل فقليــل جــدا وهــو ال يغطــي راتــب اخلادمــة التــي تقــوم بخدمــة‬\n      ‫الصغــار كــون موكلتــي تبحــث عــن عمــل وقدمــت علــى عــدة جهــات‬\n      ‫وتنتظــر الــرد منهــم وقــد يكــون العمــل مســائي واملدعيــة ليس لها ســلطة‬\n      ‫علــى ســائق أهلهــا واملدعــى عليــه لــم يصــرف علــى أوالدة مــن بدايــة عــام‬\n      ‫‪1434‬ه ـ وموكلتــي تطالــب املدعــى عليــه بإعطائهــا صــورة مــن دفتــر‬\n      ‫العائلــة حلاجتهــا لــه وموكلتــي مصــرة علــى دعواهــا كمــا أن املدعــى‬\n      ‫عليــه ينفــق علــى ابنيــه نفقــة شــهرية لــكل واحــد منهمــا ‪ 450‬ريــال و قــد‬\n      ‫انقطــع عــن النفقــة عليهمــا بنهايــة شــهر ذي احلجــة عــام ‪1433‬ه ـ هكــذا‬\n      ‫أجــاب هــذا وقــد قــررت الكتابــة لقســم اخلبــراء لتقديــر النفقــة البنــي‬\n      ‫املدعــى عليــه مــن املدعيــة ويف جلســة أخــرى بتاريــخ ‪1434/04/22‬ه ـ‬\n      ‫حضــر املدعــي وكالــة ‪ ...‬احلاضــر يف جلســة ســابقة كمــا حضــر‬\n      ‫املدعــى عليــه ‪...‬يحمــل الســجل املدنــي رقــم ‪...‬يف اجللســة الســابقة وقــد‬\n      ‫وردنــا قــرار مكتــب الصلــح برقــم ‪ 246‬وتاريــخ ‪1434/04/01‬ه ـ و‬\n      ‫املتضمــن (عليــه نفيــد فضيلتــه انــه مت االجتمــاع بالطرفــن وقــد تعــذر‬\n      ‫الصلــح بينهمــا بخصــوص تقديــر النفقــة حيــث ذكــرت املدعيــة بأنهــا‬\n      ‫تطالــب نفقــة أبنائهــا ‪ ...‬و‪ ...‬وأن املدعــى عليــه لــم ينفــق عليهــم النفقــة‬\n      ‫التــي تكفيهــم وأنــه مــن ثالثــة أشــهر لــم يســلمهم أي شــيء وترغــب‬\n      ‫أن تكــون النفقــة شــاملة للســكن واملواصــات والعــاج إلــى آخــر مــا‬\n      ‫ذكــرت بإقرارهــا املرفــق أمــا بالنســبة للمدعــى عليــه فقــد ذكــر بأنــه‬\n      ‫كان يف الســابق ينفــق علــى أوالده بواقــع ‪ 350‬ريــال شــهري ًا لــكل واحــد‬\n      ‫منهــم إلــى ‪ 500‬ريــال شــهري ًا ويقــوم بالزيــادة أحيانــا وأنــه يوجــد عليــه‬\n      ‫أقســاط شــهريه تصــل إلــى ‪ 7000‬ريــال حيــث يســلم لوالــده ‪ 3500‬ريــال‬\n      ‫وكذلــك ‪1833‬ريــال شــهري ًا وهــي قيمــة شــراء أرض وكذلــك يوجــد‬\n\n\n‫‪305‬‬\n\f‫عليــه قســط ‪1667‬ريــال لصالــح صنــدوق التنميــة إلــى آخــر مــا ذكــره‬\n‫بإقــراره املرفــق وبنــاء علــى ذلــك واحلــال كمــا ذكــر وبعــد اإلطــاع علــى‬\n‫الوضــع املــادي للمدعــى عليــه حيــث أتضــح أنــه يتقاضــى معــاش تقاعــدي‬\n‫وقــدره ‪ 11684‬ريــال حســب اخلطــاب املرفــق رقــم ‪ 12454‬وتاريــخ‬\n‫‪1434/03/17‬ه ـ الصــادر مــن املؤسســة العامــة للتقاعــد وأن املدعــى‬\n‫عليــه لــم يثبــت األقســاط املســتحقة مــن أي جهــة معتبــره فإننــا نــرى أن‬\n‫تكــون نفقــة أبنــاء املدعيــة ‪1200‬ريــال شــهري ًا لــكل واحــد منهــم شــاملة‬\n‫الســكن وكذلــك املواصــات هــذا مــا لدينــا) أ‪.‬ه ـ وقــد طلــب املدعــي‬\n‫وكالــة تعديــل دعــواه قائــا أطلــب احلكــم علــى املدعــى عليــه بــأن يســلم‬\n                     ‫النفقــة املســتقبلية ابتــداء مــن تاريــخ ‪1434/04/25‬ه ـ‬\n‫وكذلــك إلــزام املدعــى عليــه بتســليم الفــرق بــن مــا يســلمه املدعــى‬\n‫عليــه وبــن مــا يحكــم بــه خــال الفتــرة مــن شــهر جمــادى األولــى مــن‬\n‫عــام ‪1431‬ه ـ وحتــى تاريــخ ‪1434/04/25‬ه ـ فهــو لــم يســلم خــال الفترة‬\n‫الســابقة ســوى ‪ 900‬ريــال نفقــه لولديــة شــهري ًا أمــا األشــهر األربعة محرم‬\n‫و صفــر وربيــع األول و ربيــع الثانــي فلــم يســلم أي مبلــغ ســوى ‪ 500‬ريــال‬\n‫هكــذا طلــب وبعــرض ذلــك علــى املدعــى عليــه قــال صحيــح مــا ذكــرة‬\n‫املدعــي وكالــة بأننــي كنــت أنفــق علــى ابنــي مببلــغ مجموعــة ‪ 900‬ريال‬\n‫شــهري ًا لــكال اإلبنــن مــن شــهر جمــاد األولــى عــام ‪1431‬ه ـ حتــى نهايــة‬\n‫شــهر ذي احلجــة عــام ‪1433‬ه ـ وقــد قطعــت النفقــة عليهمــا لرفــع الدعــوى‬\n‫مــن املدعيــة ولــم أنفــق علــى ابنــي منــذ بدايــة هــذا العــام ســوى ‪ 500‬ريــال‬\n‫ولــن اســلم فــرق النفقــة الســابقة ألن النفقــة املســلمة لهــم كافيــة ولــم‬\n‫يقيمــوا هــذه الدعــوى اإل كيــدا مــن املدعيــة بســب موضــوع الطــاق‬\n‫وكذلــك لــن أســلم النفقــة الالحقــة ســوى مبلــغ ‪ 300‬ريــال لــكل ابــن‬\n\n\n                                                                                        ‫‪306‬‬\n\f      ‫أســوة ببقيــة األحــكام األخــرى قــد حصــل أتفــاق شــفوي يف شــهر صفــر‬\n      ‫عــام ‪1433‬ه ـ علــى نفقــه شــهرية ‪ 900‬ريــال ولــم تطلب أجرة الســكن يف‬\n      ‫صحيفــة الدعــوى هكــذا أجــاب وبعــرض ذلــك علــى املدعــي وكالة قال‬\n      ‫لــم يحصــل اتفــاق بــن موكلتــي و املدعــى عليــه بــأن تكــون النفقــة ‪900‬‬\n      ‫ريــال العــام املاضــي وغيــر صحيــح أنهــا كيديــه هكــذا أجــاب وبعــرض‬\n      ‫مــا جــاء يف قــرار قســم اخلبــراء رفــض املدعــي وكالــة مــا جــاء فيــه وقــال‬\n      ‫أطلــب أن يكــون تقديــر النفقــة لــكل أبــن ‪ 2000‬ريــال هكــذا أجــاب‬\n      ‫كمــا رفــض املدعــى عليــه مــا جــاء يف قرار قســم اخلبراء وقــال أنه تقدير‬\n      ‫مرتفــع جــد ًا هكــذا أجــاب وبســؤال املدعــي وكالــة هــل موكلتــه تنفــق‬\n      ‫علــى أبنيهــا مــن املدعــى عليــه املبلــغ الزائــد عــن ‪ 900‬ريــال بنيــة الرجــوع‬\n      ‫فقــال هــي تنفــق حســب قولهــا بنيــة الرجــوع علــى املدعــى عليــه هكــذا‬\n      ‫أجــاب وبعــرض ذلــك علــى املدعــى عليــه قــال أطلــب ميــن املدعــى عليهــا‬\n      ‫علــى ذلــك بأنهــا أنفقــت علــى ابنــي نفقــة زائــدة عمــا أســلمه لهــا بنيــة‬\n      ‫الرجــوع علــي مــن تاريــخ جمــادي األول عــام ‪1431‬ه ـ وحتــى تاريــخ هــذا‬\n      ‫اليــوم هكــذا طلــب فاســتعد املدعــى وكالــة بإبــاغ موكلتــه باحلضــور‬\n      ‫اجللســة القادمــة ألداء اليمــن املطلوبــة كمــا طلــب املدعــى عليــه مهلــه‬\n      ‫إلحضــار بينتــه علــى االتفــاق وبــن املدعيــة بــأن تكــون النفقــة ‪900‬ريــال‬\n      ‫من تاريخ صفر عام ‪1433‬هـ ويف جلســة أخرى بتاريخ ‪1434/06/25‬هـ‬\n      ‫حضــر املدعــى عليــه أصالــة‪ ،‬ولــم حتضــر املدعيــة وال مــن ميثلهــا ‪،‬‬\n      ‫وبســؤال املدعــي عليــه عــن بينتــه التــي وعــد بهــا‪ ،‬قــال ‪ :‬ليــس لــدي ســوى‬\n      ‫االتفــاق الشــفهي بيننــا ‪ ،‬وبســؤاله هــل لديــه زيــادة بينــة‪ ،‬فقــال‪ :‬ال ويف‬\n      ‫جلســة أخــرى بتاريــخ ‪1434/07/12‬ه ـ حضــرت املدعيــة ووكيلهــا ‪...‬و‬\n      ‫املدعــى عليــه ‪...‬احلاضــرون يف اجللســة الســابقة ‪ ،‬وقــد قــررت املدعيــة‬\n\n\n‫‪307‬‬\n\f‫أنهــا اســتلمت مؤخــرا مــن املدعــى عليــه مبلغــا وقــدره ألفــان وأربعمائــة‬\n‫ريــال وتطلــب حســمه ممــا تطلبــه مــن املدعــي عليــه‪ ،‬وتطلــب حتويــل‬\n‫النفقــة املســتقبلية علــى حســابها يف مصــرف الراجحــي رقــم ‪ ...‬هكــذا‬\n‫طلبــت وقــد مت محاولــة الصلــح بــن الطرفــن إال أنــه لــم يتوصــل إلــى‬\n‫حــل مــرض بينهمــا ‪ ،‬وقــد طلــب املدعــي عليــه ميــن املدعيــة علــى نفــي‬\n‫االتفــاق يف شــهر صفــر عــام ‪1433‬ه ـ بــأن تكــون نفقــة األبنــاء ‪900‬ريــال‬\n‫كمــا طلــب ميينهــا علــى أنهــا أنفقــت علــى ابنيــه منهــا نفقــة زائــدة عمــا‬\n‫ســلمه لهــا وبنيــة الرجــوع مــن تاريــخ جمــادى األول عــام ‪1431‬ه ـ وحتــى‬\n‫تاريــخ هــذا اليــوم ‪ ،‬وبعــرض ذلــك علــى املدعيــة قالــت ال مانــع لــدي‬\n‫مــن أداء اليمــن فاســتعدت باحللــف ‪ ،‬فأذنــت لهــا‪ ،‬فحلفــت قائلــة‪« :‬‬\n‫واهلل العظيــم بأننــي قــد أنفقــت علــى ابنــي املدعــى عليــه ‪...‬و‪ ...‬منــي‬\n‫بنيــة الرجــوع علــى املدعــى عليــه مــن شــهر جمــادى األولــى عــام ‪1431‬ه ـ‬\n‫وحتــى تاريــخ هــذا اليــوم وقــد أنفقــت عليهمــا بأكثــر مــن تســعمائة‬\n‫ريــال شــهريا وأننــي لــم أتفــق مــع املدعــى عليــه يف نهايــة شــهر صفــر عــام‬\n‫‪1433‬ه ـ بــأن تكــون نفقــة األبنــاء تســعمائة ريــال» هكــذا حلفــت فبنــاء‬\n‫علــى مــا تقــدم مــن الدعــوى واإلجابــة ‪ ،‬وألداء املدعيــة اليمــن املطلوبــة‬\n‫منهــا ‪ ،‬ولقولــه تعالــى‪( :‬وعلــى املولــود لــه رزقهــن وكســوتهن باملعــروف)‬\n‫ولقــول الرســول الكــرمي صلــى اهلل عليــه وســلم‪( :‬ابــدأ بنفســك ثــم مبــن‬\n‫تعــول) وملــا ذكــره الفقهــاء يرحمهــم اهلل فقــد جــاء يف كشــاف القنــاع‬\n‫(ويجــب عليــه أيضــا نفقــة ولــده وإن ســفل ‪ ...‬وألن النفقــة واجبــة علــى‬\n‫اإلنســان علــى نفســه وزوجتــه فكــذا هــي واجبــة علــى بعضــه وأصلــه)‬\n                                                       ‫وقــال يف الشــرح الكبيــر‬\n‫(ويلزمــه نفقــة ســائر آبائــه وإن علــوا وأوالده وإن ســفلوا) وقــال يف شــرح‬\n\n\n                                                                                       ‫‪308‬‬\n\f      ‫املنتهــى ‪( :‬فيجــب إعفــاف مــن جتــب نفقتــه مــن اآلبــاء واألجــداد واألوالد‬\n      ‫واإلخــوة واألعمــام ويقــدم إن ضــاق الفاضــل األقــرب فاألقــرب) ومبــا أن‬\n      ‫املدعيــة طالبــت بالنفقــة الســابقة مــن جمــادى األولى عــام ‪1431‬هـ وحتى‬\n      ‫تاريــخ ‪1434/06/25‬ه ـ واملســتقبلية‪ ،‬وملــا جــاء يف تقريــر قســم اخلبــراء‬\n      ‫بــأن النفقــة لالبنــن شــهرية تقــدر مببلــغ وقــدره ألفــان وأربعمائــة ريــال‬\n      ‫والتــي يكــون مجمــوع النفقــة الســابقة مبلــغ وقــدره واحــد وتســعون ألفــا‬\n      ‫ومائتــا ريــال ‪ ،‬وحيــث دفــع املدعــى عليــه نفقــة لتلــك الفتــرة مجموعهــا‬\n      ‫مبلــغ وقــدره واحــد وثالثــون ألفــا وســبعمائة ريــال وعليــه فحكمــت‬\n      ‫مبــا يلــي ‪ :‬أوال ‪ :‬ألزمــت املدعــى عليــه بدفــع النفقــة الســابقة علــى ابنيــه‬\n      ‫للمدعيــة وهــو مبلــغ وقــدره تســعة وخمســون ألفــا وخمســمائة ريــال‪ .‬ثانياً‪:‬‬\n      ‫ألزمــت املدعــى عليــه بدفــع نفقــة مســتقبلية لالبنــن كل شــهر وهــو‬\n      ‫مبلــغ وقــدره ألفــان وأربعمائــة ريــال لــكل واحــد ألــف ومائتــي ريــال ‪.‬‬\n      ‫تســلم للمدعيــة بالتحويــل إلــى حســابها يف مصــرف الراجحــي املذكــور‬\n      ‫أعــاه مــن تاريــخ ‪1434/07/25‬ه ـ وبإعــان احلكــم علــى املدعية قررت‬\n      ‫قناعتهــا بــه و قــرر املدعــى عليــه عــدم القناعــة فاســتعد بتقــدمي الئحتــه‬\n      ‫االعتراضيــة و أفهــم بــأن لــه مــدة ثالثــن يومــا تبــدأ مــن تاريــخ اســتالمه‬\n      ‫نســخة احلكــم وهــو يــوم الثالثــاء ‪1434/07/18‬ه ـ يقــدم خاللــه الئحته‬\n      ‫االعتراضيــة وأنــه يف حالــة انتهــاء املــدة و لــم يقــدم خاللهــا الئحتــه‬\n      ‫االعتراضيــة فإنــه يســقط حقــه يف االعتــراض علــى احلكــم و يكتســب‬\n      ‫احلكــم القطعيــة‪ ،‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                  ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/07/12‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء ‪1434/10/27‬ه ـ افتتحــت‬\n      ‫اجللســة و قــد وردتنــا املعاملــة مــن رئيــس محكمــة االســتئناف بكتابــه‬\n\n\n‫‪309‬‬\n\f‫ذي الرقــم ‪ 342126052‬يف ‪1434/09/17‬ه ـ املرفــق بــه قــرار الدائــرة‬\n‫الثانية املختصة بنظر قضايا األحوال الشــخصية واالنهاءات مبحكمة‬\n‫االســتئناف بالريــاض برقــم ‪ 34318434‬وتاريــخ ‪1434/09/14‬ه ـ ونــص‬\n‫احلاجــة منــه ‪( :‬وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n‫وأوراق املعاملــة لوحــظ أن مــا قــدر مــن النفقــة املاضيــة كثيــر فعلــى‬\n‫فضيلتــه الكتابــة إلــى هيئــة اخلبــراء باحملكمــة إلعــادة النظــر يف ذلــك‬\n‫وتقديــر النفقــة علــى قــدر ســعة املنفــق لقولــه تعالــى ((لينفــق ذو ســعة مــن‬\n‫ســعته ومــن قــدر عليــه رزقــه فلينفــق ممــا آتــاه اهلل ال يكلــف اهلل نفســا‬\n‫إال مــا آتاهــا ســيجعل اهلل بعــد عســر يســرا)) واهلل املوفق)ا‪.‬ه ـ وإجابــة‬\n‫علــى مــا ذكــره أصحــاب الفضيلــة أقــول وبــاهلل التوفيــق ‪ :‬إن النفقــة‬\n‫التــي مت تقديرهــا شــاملة لنفقــة الســكن واملــأكل واملشــرب وامللبــس‬\n‫ومــا يلــزم ومــن املعلــوم أن املســاكن املســتأجرة وأقلهــا يف العــرف ملــن‬\n‫هــو مثــل حــال املتداعيــن شــقة والشــقق ال تقــل أجــرة املتوســط منهــا‬\n‫عــن عشــرين ألــف ريــال للســنة الواحــدة ونفقــة األبنــاء مــن ألــزم مــا يجــب‬\n‫علــى اآلبــاء ومــا قــدر مــن مبلــغ مــن ســعة احملكــوم عليــه بــه ومــن وجــده‬\n‫لذلــك كلــه لــم يظهــر لــي خــاف مــا حكمــت بــه وقــررت إعــادة املعاملــة‬\n‫حملكمــة االســتئناف وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n                             ‫وآلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/10/27‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم االثنــن املوافــق ‪ 1434/12/23‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 11 : 30‬هــذا و قــد وردتنــا املعاملــة مــن‬\n‫رئيــس محكمــة االســتئناف بكتابــه ذي الرقــم ‪ 342460670‬يف‬\n‫‪ 1434/11/27‬ه ـ املرفــق بــه القــرار الصــادر مــن دائــرة األحــوال‬\n‫الشــخصية الثانيــة برقــم ‪ 34361404‬يف ‪ 1434/11/18‬ه ـ واملتضمــن‬\n\n\n                                                                                       ‫‪310‬‬\n\f      ‫املصادقــة علــى احلكــم بعــد اجلــواب األخيــر‪ ،‬وأقفلــت اجللســة الســاعة‬\n      ‫‪ ، 12 : 00‬واهلل املوفــق‪ ،‬وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n                                   ‫وصحبــه أجمعــن حــرر يف ‪1434/12/23‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة املختصــة‬\n      ‫بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n      ‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫بالريــاض برقــم ‪ 342460670‬وتاريــخ ‪1434/10/29‬ه ـ املرفــق بهــا‬\n      ‫الصــك الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪ ... /‬املســجل‬\n      ‫برقــم ‪ 34268722‬وتاريــخ ‪1434/7/16‬ه ـ اخلــاص بدعــوى‪... /‬بالســجل‬\n      ‫املدنــي رقــم ‪...‬ضــد ‪ ... /‬يف قضيــة نفقــة أوالد وقــد تضمــن الصك حكم‬\n      ‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وحيــث ســبق دراســة الصــك‬\n      ‫وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة وباإلطــاع‬\n      ‫علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالصــك بنــاء علــى قرارنــا‬\n      ‫رقــم ‪ 34318434‬وتاريــخ ‪1434/9/14‬ه ـ تقــرر الدائــرة املصادقــة بعــد‬\n      ‫اجلــواب األخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد و علــى آلــه‬\n                                                                      ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪311‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":299,"source_page_end":311,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6c20696f4c323d5cd892933d20a8f8bb004a4665b0ae990852a1555fd0930e14","normalized_text_hash":"874778365dd24c8c29ff1e438a9185a0079e937781a034e3515f13634924aa9a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p299-34268722"},{"id":"94269e61-4ff5-5f17-8148-f47a6642cdc9","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -نفقة زوجة -نفقة حمل -نفقة حضانة -املطالبة بالنفقة املاضية -إنفاق األم على طفلها بنية الرجوع على األب مبا أنفقته- دفع الزوج بنشوز الزوجة يف عدم اإلنفاق عليها -النشوز ال يسقط نفقة احلامل -تقدير النفقة عن طريق قسم اخلبراء -احلكم بدفع النفقة املاضية -استالم املبلغ احملكوم به ينفي املطالبة به ثانية .","document_number":"34295759","case_number":"3449740","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":"الدائرة ( األحوال الشخصية الثانية) وذلك مبوجب قرارهم ذي","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/13","year":"1434","subject":"نفقة -نفقة زوجة -نفقة حمل -نفقة حضانة -املطالبة بالنفقة املاضية -إنفاق األم على طفلها بنية الرجوع على األب مبا أنفقته- دفع الزوج بنشوز الزوجة يف عدم اإلنفاق عليها -النشوز ال يسقط نفقة احلامل -تقدير النفقة عن طريق قسم اخلبراء -احلكم بدفع النفقة املاضية -استالم املبلغ احملكوم به ينفي املطالبة به ثانية .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/8/13 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34295759 :‬‬\n                    ‫َر ْق ُم الدعوى‪3449740 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n         ‫‪ 34337013‬تاريخه‪1434/10/21 :‬هـ‬\n\n\n\n‫نفقــة ‪ -‬نفقــة زوجــة‪ -‬نفقــة حمــل‪ -‬نفقــة حضانــة‪ -‬املطالبــة بالنفقــة‬\n‫املاضيــة‪ -‬إنفــاق األم علــى طفلهــا بنيــة الرجــوع علــى األب مبــا أنفقتــه‪-‬‬\n‫دفــع الــزوج بنشــوز الزوجــة يف عــدم اإلنفــاق عليهــا‪ -‬النشــوز ال يســقط‬\n‫نفقــة احلامــل‪ -‬تقديــر النفقــة عــن طريــق قســم اخلبــراء‪ -‬احلكم بدفع‬\n ‫النفقــة املاضيــة‪ -‬اســتالم املبلــغ احملكــوم بــه ينفــي املطالبــة بــه ثانيــة ‪.‬‬\n\n\n\n\n          ‫‪ -1‬قوله تعالى ( وعلى املولود له رزقهن وكسوتهن باملعروف)‬\n‫‪ -2‬مــا قــرره الفقهــاء مــن أن النشــوز ال يســقط نفقــة احلامــل ألن النفقــة‬\n                                                       ‫للحمــل وليــس للمــرأة‪.‬‬\n\n\n\n\n‫ادعــت املدعيــة بــأن املدعــى عليــة تزوجهــا بواليــة والدهــا ودخــل بهــا‬\n‫الدخــول الشــرعي وذهبــت إلــى بيــت أهلهــا علــى أثــر خــاف بينهمــا وهــي‬\n‫حامــل يف الشــهر الســابع‪ -‬بعــد الوضــع مكــث عندهــا طفلهــا شــهريني‬\n‫ثــم أخــذه أبــوه طلبــت املدعيــة إلــزام املدعــى عليــه بدفــع نفقتهــا ونفقــة‬\n‫ابنهــا املاضيــة‪ -‬دفــع املدعــى عليــه بأنــه طلبهــا مــرار ًا للرجــوع إلــى بيتــه‬\n‫ورفضــت وأنــه تقــدم بدعــوى للمحكمــة يطالــب زوجتــه بالرجــوع إلــى‬\n‫بيتــه‪ -‬دفــع املدعــى عليــه بأنــه دفــع نفقــة ابنــة يف الشــهر األول ولــم يتبــق‬\n\n                                                                                          ‫‪312‬‬\n\f      ‫ســوي نفقــه الشــهر الثانــي واســتعد بدفعهــا حســب مــا تقــرره احملكمــة‪-‬‬\n      ‫أنكــرت املدعيــة اســتالمها لنفقــة الشــهر األول للطفــل‪ -‬قــرر املدعــى‬\n      ‫عليــه أنــه ال بينــة لديــة علــى هــذا الشــهر وطلــب ميــن املدعيــة علــى نفــي‬\n      ‫النفقــة‪ -‬قــررت املدعيــة أنهــا لــن حتلــف وأنهــا متنازلــة عــن نفقــة الشــهر‬\n      ‫األول للطفــل‪ -‬ورد جــواب قســم اخلبــراء املتضمــن تقديــر نفقــة املدعيــة‬\n      ‫أثنــاء احلمــل ونفقــة الطفــل للشــهر الثانــي‪ -‬ملــا قــرره أهــل العلــم مــن أن‬\n      ‫النشــوز ال مينــع النفقــة ألن النفقــة للحمــل وليــس للمــرأة ولقولــة تعالــى‬\n      ‫( وعلــى املولــود لــه رزقهــن وكســوتهن باملعــروف) لــذا صــدر احلكــم‬\n      ‫بإلــزام املدعــى عليــه بــأن يدفــع للمدعيــة نفقــة احلمــل والشــهر الثانــي‬\n      ‫لطفلــة حســب قــرار قســم اخلبــراء‪ -‬اقتنعــت املدعيــة باحلكــم ولــم يقنــع‬\n                      ‫املدعــى عليــه‪ -‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n      ‫أنــا ‪...‬القاضــي باحملكمــة العامــة باملدينــة املنــورة ففــي هــذا اليــوم‬\n      ‫الســبت ‪1434/02/20‬ه ـ ويف متــام الســاعة التاســعة والنصــف صباحـ ًا‬\n      ‫فتحــت اجللســة األولــى بنــاء علــى املعاملــة املقيــدة يف هــذه احملكمــة‬\n      ‫برقــم‪ 34246051‬يف ‪1434/01/28‬ه ـ واحملالــة إلينــا مــن فضيلــة‬\n                                 ‫الرئيــس برقــم‪ 34246051‬يف ‪1434/01/28‬ه ـ‬\n      ‫مبوجبــه حضــرت املــرأة ‪ ...‬ميانيــة اجلنســية مبوجــب رخصــة اإلقامــة رقــم‬\n      ‫‪...‬جــوازات املدينــة املنــورة واملعــرف بهــا مــن قبــل والدهــا املقيــم ‪...‬ميانــي‬\n      ‫اجلنســية مبوجــب رخصــة اإلقامــة رقــم ‪...‬جــوازات املدينــة املنــورة ولــم‬\n      ‫يحضــر املدعــي عليــه ‪ ...‬وال مــن ينــوب عنــه يف موعــد هــذه اجللســة والتــي‬\n\n‫‪313‬‬\n\f‫حــدد لــه يف متــام الســاعة التاســعة صباح ـ ًا موعــدا لســماع الدعــوى‬\n‫رغــم تبلغــه مبوعــد هــذه اجللســة لشــخصه حســب إفــادة رئيــس قســم‬\n‫محضــري اخلصــوم يف هــذه احملكمــة شــرح ًا علــى ورقــة التبليــغ املؤرخــة‬\n‫يف ‪1434/01/28‬ه ـ ونظــر ًا ملــا تنــص عليــه املــادة اخلامســة واخلمســون‬\n‫مــن نظــام املرافعــات الشــرعية فقــد امــرت برفــع اجللســة إلــى يــوم األحــد‬\n‫املوافــق ‪1434/05/05‬ه ـ الســاعة احلاديــة عشــر وخمســة وأربعــون‬\n‫دقيقــة هــذا ويف يــوم الثالثــاء ‪1434/4/30‬ه ـ ويف متــام الســاعة الثانيــة‬\n‫والنصــف ظهــرا فتحــت اجللســة الثانيــة وفيهــا حضــرت املــرأة ‪...‬مينيــة‬\n‫اجلنســية مبوجــب رخصــة اإلقامــة رقــم ‪...‬جــوازات املدينــة املنــورة واملعرف‬\n‫بهــا مــن قبــل والدهــا املقيــم ‪...‬مينــي اجلنســية مبوجــب رخصــة اإلقامــة‬\n‫رقــم ‪......‬جــوازات املدينــة املنــورة وأدعــت علــى احلاضــر معهــا يف مجلــس‬\n‫احلكــم املقيــم ‪ ...‬ميانــي اجلنســية مبوجــب رخصــة اإلقامــة رقــم ‪...‬جــوازات‬\n‫املدينــة املنــورة قائلــة يف حتريــر دعواهــا عليــه ‪ :‬أن هــذا احلاضــر زوج لــي‬\n‫تزوجنــي بالعقــد الصحيــح الشــرعي بواليــة والــدي هــذا احلاضــر ‪ ...‬علــى‬\n‫مهــر وقــدره خمســة عشــر ألــف ريــال اســتلمتها كاملــة وقــد دخــل بــي‬\n‫بتاريــخ ‪1432/10/13‬ه ـ وقــد أجنبــت لــه علــى فــراش الزوجيــة ‪...‬املولــود‬\n‫يف ‪1433/11/13‬ه ـ وقــد حصــل بيننــا خالفــات وذلــك ألن املدعــى عليــه‬\n‫لــم يوفــر لــي ســكن مســتقل حيــث أننــي اســكن مــع أهلــه وقــد اتفقــت‬\n‫معــه قبــل الــزواج علــى أن يوفــر لــي ســكن مســتقل ولــم يحقــق ذلــك‬\n‫وحياتــي معــه دائمـ ًا بهــا مشــاكل وذلــك لتدخــل أهلــه يف حياتنــا اخلاصــة‬\n‫وبتاريــخ ‪1433/8/11‬ه ـ جــاء إلـ ّـي هــذا احلاضــر ومعــه والدتــه ودار بيننــا‬\n‫نقــاش علــى غســيل األوانــي ثــم قــام املدعــى عليــه بضربــي علــى وجهــي‬\n‫ا يف الشــهر‬    ‫وقــام بالتلفــظ علـ ّـي وســبي وســب أهلــي وكنــت حينهــا حامـ ً‬\n\n\n                                                                                      ‫‪314‬‬\n\f      ‫الســابع وبتاريــخ ‪1433/8/13‬ه ـ خرجــت مــن منــزل هــذا احلاضــر إلــى‬\n      ‫منــزل أهلــي وجلســت عندهــم حتــى تاريــخ هــذا اليــوم ولــم ينفــق علـ ّـي‬\n      ‫ريــا ًال واحــد ًا كمــا أننــي ولــدت ولــدي منــه ‪ ...‬بتاريــخ ‪1433/11/13‬ه ـ‬\n      ‫ولــم ينفــق عليــه حتــى أخــذه منــي بتاريــخ ‪1434/1/13‬ه ـ أي حوالــي‬\n      ‫شــهرين وقــد أنفقــت عليــه بنيــة الرجــوع علــى والــده‪ ،‬أطــب تقديــر النفقة‬\n      ‫املاضيــة الشــرعية لــي وألبنــي وإلــزام املدعــى عليــه بدفــع املبلــغ الــذي‬\n      ‫يقــدره أهــل اخلبــرة علمـ ًا أن هــذا احلاضــر يعمــل ســائق أجــرة يف شــركة‬\n      ‫‪...‬وراتبــه حوالــي مبلــغ وقــدره ألــف وخمســمائة ريــال هــذه دعــواي ‪.‬‬\n      ‫ا ‪ :‬مــا ذكرتــه املدعيــة‬    ‫وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائ ـ ً‬\n      ‫يف دعواهــا ضــدي مــن تاريــخ الــزواج والدخــول واملهــر والـ ــولد وتاريــخ‬\n      ‫خروجهــا مــن منزلــي وتاريــخ أخــذي البنــي فهذا كـل ــه صح ـيـ ــح ‪ ،‬وأمـ ــا‬\n      ‫مــا ذكرتــه مــن أننــي لــم أنفــق عليهــا مــن تاريــخ خروجهــا مــن منــزل‬\n      ‫أهلــي فهــذا صحيــح وذلــك ألنهــا ناشــز وقــد طلبتهــا مــرار ًا وتكــرار ًا‬\n      ‫بالرجــوع إلــى بيــت أهلــي ولكنهــا رفضــت الرجــوع وعليــه فإنهــا ناشــز ًا‬\n      ‫وال نفقــة لهــا علـ ّـي ‪ ،‬وأمــا مــا ذكرتــه مــن أننــي ال أنفــق علــى إبنــي خــال‬\n      ‫الشــهرين عندمــا كان عندهــا فهــذا غيــر صحيــح بــل أنفقــت عليــه يف‬\n      ‫الشــهر األول وأمــا الشــهر الثانــي فلــم أنفــق عليــه وأنــا مســتعد بدفــع‬\n      ‫النفقــة التــي يقدرهــا أهــل اخلبــرة ‪ ،‬وأمــا مــا ذكرتــه مــن حيــث عملــي‬\n      ‫وراتبــي فهــذا كلــه صحيــح هكــذا أجــاب والنتهــاء وقــت اجللســة فقــد‬\n      ‫أمــرت برفــع اجللســة إلــى يــوم األحــد ‪1434/5/5‬ه ـ الســاعة الثانية عشــر‬\n                                                                         ‫إال ربــع صباح ـ ًا‬\n      ‫هذا ويف يوم األحد ‪1434/5/5‬هـ ويف متام الســاعة الثانية عشــر والربع‬\n      ‫فتحــت اجللســة الثانيــة وفيهــا حضــرت املدعيــة واملعــرف بهــا مــن قبــل‬\n\n\n‫‪315‬‬\n\f‫والدهــا املدونــة هويتهــا ســابق ًا وحضــر حلضورهــا املدعــى عليــه ثــم جــرى‬\n‫ال ال ليــس لدي ديون‬    ‫منــا ســؤال املدعــى عليــه هــل لديــه ديــون فأجــاب قائ ً‬\n‫واحلمــد هلل تعالــى وأنــا اســكن مــع أهلــي وأقــوم باإلنفــاق عليهــم هكــذا‬\n‫أجــاب هــذا وقــد جــرى منــي الكتابــة إلــى قســم اخلبــراء لتقديــر النفقــة‬\n‫الشــرعية الواجبــة هــذا ويف يــوم األربعــاء ‪1434/06/21‬ه ـ ويف متــام‬\n‫الســاعة العاشــرة صباحـ ًا فتحــت اجللســة الرابعــة وفيهــا حضــرت املدعيــة‬\n‫واملعــرف بهــا مــن قبــل والدهــا ‪...‬املــدون هويتهمــا ســابق ًا ولــم يحضــر‬\n‫املدعــى عليــه وال مــن ينــوب عنــه يف موعــد هــذه اجللســة والتــي حــدد لهــا‬\n‫يف متــام الســاعة التاســعة والنصــف موعــد ًا لســماع الدعــوى وقــد جــرى‬\n‫تبليغــه مبوعــد هــذه اجللســة يف اجللســة املاضيــة ولــم يحضــر ولــم يقــدم‬\n‫عــذر ًا لعــدم حضــوره وقــد جــرى منــا الكتابــة إلــى قســم اخلبــراء لتقديــر‬\n‫النفقــة الشــرعية الواجبــة وحتــى تاريــخ هــذا اليــوم لــم تردنــا افــادة وعليــه‬\n‫أمــرت برفــع اجللســة إلــى يــوم الســبت ‪1434/08/13‬ه ـ الســاعة احلاديــة‬\n‫الســاعة احلاديــة‬\n                 ‫عشــر صباحـ ًا هــذا ويف يــوم الســبت ‪1434/08/13‬ه ـ َّ‬\n‫صباحــا ُفت َِحـ ْـت اجللســة اخلامســة وفيهــا حضــرت املدعيــة واملعــرف‬\n                                                                        ‫ً‬      ‫عشــر‬\n‫بهــا مــن قبــل والدهــا ‪ ...‬املدونــة هويتــه ســابق ًا وحضــر حلضــوره املدعــى‬\n‫عليــه أصالــة هــذا وقــد وردنــا إفــادة قســم اخلبــراء يف هــذه احملكمــة‬\n‫مبوجــب خطابهــم ذي الرقــم ‪ 341516993‬يف ‪1434/07/17‬ه ـ وهــذا‬\n‫نــص احلاجــة منــه « وبعــد ذلــك رأينــا أن يدفــع املدعــى عليــه نفقــة احلمــل‬\n‫واحلضانــة وقدرهــا ألــف وســتمائة وواحــد وســبعون ريــا ًال وأمــا نفقــة‬\n‫الشــهرين رأينــا أن تكــون خمســمائة ريــال لــكل شــهر هــذا مــا رأينــاه‬\n‫«أ‪.‬ه ـ وبعــرض قــرار قســم اخلبــراء يف هــذه احملكمــة علــى املدعــى عليــه‬\n‫واملدعيــة أجابــت املدعيــة قائلــة أنــا مقتنعــة بقــرار قســم اخلبــراء هكــذا‬\n\n\n                                                                                         ‫‪316‬‬\n\f      ‫ا أنــا غيــر مقتنــع بهــذا القــرار‬‫أجابــت وأمــا املدعــى عليــه فأجــاب قائ ـ ً‬\n      ‫وذلــك ألننــي أقمــت دعــوى علــى املدعــى عليهــا منــذ خروجهــا مــن منزلــي‬\n      ‫إلعادتهــا إلــى بيــت الطاعــة ولكــن لــم حتضــر يف جلســات احملاكمــة‬\n      ‫وعليــه فهــي ناشــز ال جتــب علـ ّـي نفقتهــا وأمــا نفقــة الشــهر فهــذا أنــا‬\n      ‫غيــر مســتعد بــه وذلــك ألننــي دفعــت نفقــة الشــهر األول للمدعيــة أصالــة‬\n      ‫مبلــغ مائتــان ريــال ومالبــس للطفــل تقــدر بخمســمائة ريــال وعليــه فــا‬\n      ‫جتــب علـ ّـي نفقــة االبــن وأمــا الشــهر اآلخــر فأنــا مســتعد بدفــع نفقتــه‬\n      ‫هكــذا أجــاب وبعــرض ذلــك علــى املدعيــة أجابــت قائلــة مــا ذكــره‬\n      ‫املدعــى عليــه غيــر صحيــح ولــم ينفــق علــى ابنــه إال انــه أحضــر معــه‬\n      ‫أربــع بــدل وكذلــك هــزاز للطفــل وحفائــض وشرشــف فقــط هــذا مــا‬\n      ‫أحضــره وقدرهــا بالكثيــر مائتــان ريــال ولــم يعطينــي ريــا ًال واحــد ًا‬\n      ‫هكــذا أجابــت ثــم جــرى منــا ســؤال املدعــى عليــه هــل لديــه بينــة فيمــا‬\n      ‫ا ال ليــس‬ ‫دفــع بــه مــن أنــه انفــق نفقــة الشــهر األول البنــه ‪...‬فأجــاب قائـ ً‬\n      ‫لــدي بينــة علــى ذلــك وأطلــب ميــن املدعيــة هكــذا اجــاب وبعــرض ذلــك‬\n      ‫علــى املدعيــة أجابــت قائلــة لــن أحلــف ولكــن أنــا متنازلــة عــن نفقــة‬\n      ‫الشــهر األول وأطلــب نفقــة الشــهر الثانــي هكــذا أجابــت فبنــاء علــى‬\n      ‫مــا تقــدم مــن الدعــوى واإلجابــة واإلطــاع علــى أوراق املعاملــة وحيــث‬\n      ‫صــادق املدعــى عليــه ملــا جــاء يف دعــوى املدعيــة مــن أنــه لــم ينفــق علــى‬\n      ‫زوجتــه احلامــل منــذ خروجهــا مــن منزلــه بتاريــخ ‪1433/08/13‬ه ـ وحتــى‬\n      ‫والدتهــا بتاريــخ ‪1433/11/13‬ه ـ ريــا ًال واحــد ًا ومبــا أن املدعــى عليــه‬\n      ‫دفــع بعــدم نفقــة عليهــا ألنــه ناشــز ومبــا أن نفقــة احلمــل جتــب علــى الــزوج‬\n      ‫ليــس للمــرأة ولكــن للحمــل كمــا قــرر بذلــك الفقهــاء ولقولــه تعالــى‪:‬‬\n                                ‫(وعلــى املولــود لــه رزقهــن وكســوتهن باملعــروف )‬\n\n\n‫‪317‬‬\n\f‫ومبــا أن املدعــى عليــه صــادق علــى مــا جــاء يف دعــوى املدعيــة مــن أنــه لــم‬\n‫ينفــق علــى املولــود يف الشــهر الثانــي وأنكــر مــا جــاء يف دعــوى املدعيــة‬\n‫مــن أنــه لــم ينفــق يف الشــهر األول مــن والدة املولــود وادعــى أن ينفــق علــى‬\n‫ابنــه يف الشــهر األول وأنكــرت ذلــك املدعيــة ولــم يقــم املدعــى عليــه‬\n‫بينــة علــى ذلــك وطلــب ميــن املدعيــة علــى نفــي دعــواه ومبــا أن املدعيــة‬\n‫قــد تنازلــت عــن نفقــة شــهر واحــد ونظــر ًا ملــا قــرره قســم اخلبــراء يف هــذه‬\n‫احملكمــة مبوجــب قرارهــم املشــار إليــه بعاليــه جلميــع مــا ذكــر فقــد‬\n‫ألزمــت املدعــى عليــه بدفــع مبلــغ وقــدره ألفــان ومائــة وواحــد وســبعون‬\n‫ريــال حــا ًال للمدعيــة هــذا مــا ظهــر لــي وبــه حكمــت وبعرضــه عليهمــا‬\n‫قــررت املدعيــة القناعــة أمــا املدعــى عليــه فقــرر اعتراضــه علــى احلكــم‬\n‫بــدون الئحــة اعتراضيــة وعليــه أمــرت برفــع املعاملــة إلــى محكمــة‬\n‫االســتئناف لتدقيــق احلكــم حســب املتبــع نظام ـ ًا وبــه اختتمــت اجللســة‬\n‫الساعة احلادية عشر والنصف و باهلل ال َّتوفيق‪ ،‬و صلَّى اهلل و سلَّم على‬            ‫َّ‬\n‫محمــدٍ ‪ ،‬و علــى آلــه و صحبــه أجمعــن حــرر يف ‪1434/08/13‬هــ‪.‬‬         ‫نبينــا َّ‬  ‫ِّ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي‬\n‫هــذا اليــوم األحــد ‪1434/12/1‬ه ـ عــادت لنــا املعاملــة مــن محكمــة‬\n‫االســتئناف مبكــة املكرمــة مبوجــب خطابهــم ذي الرقــم ‪34246051‬‬\n‫يف ‪1434/10/27‬ه ـ وقــد جــرى تدقيــق احلكــم وتصديقــه مــن قبــل‬\n‫الدائــرة ( األحــوال الشــخصية الثانيــة) وذلــك مبوجــب قرارهــم ذي‬\n‫الرقــم ‪ 34337013‬يف ‪1434/10/ 21‬ه ـ وقــد تضمــن قرارهــم املوافقــة‬\n‫علــى احلكــم بختــم وتوقيــع كل مــن ‪ ...‬قاضــي اســتئناف و ‪ ...‬قاضــي‬\n‫اســتئناف و ‪ ...‬رئيــس الدائــرة وللمعلوميــة جــرى حتريــره حتــى ال يخفــى‬\n‫وأمــرت بإحلــاق ذلــك يف ضبطــه وســجله وبــاهلل التوفيــق وصلى اهلل وســلم‬\n\n\n                                                                                          ‫‪318‬‬\n\f                                     ‫علــى نبينــا محمــد ‪ .‬حــرر يف ‪1434/12/1‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعده وبعــد ففي هذا‬\n      ‫اليــوم األحــد ‪1435/1/21‬ه ـ حضــر املدعــي وحضــر حلضــوره املدعــى‬\n      ‫ا اســتلمت كامــل املبلــغ احملكــوم لــي‬        ‫عليــه وعليــه قــرر املدعــي قائ ـ ً‬\n      ‫بباطــن هــذا الصــك وقــدره ألفــان ومائــة وواحــد وســبعون ريــا ًال ريــال‬\n      ‫نقــد ًا وعليــه فــا يحــق لــي مطالبــة املدعــى عليــه بــأي مبالــغ ماليــة فيمــا‬\n      ‫يخــص هــذه الدعــوى وللمعلوميــة جــرى حتريــره حتــى ال يخفــى وبــاهلل‬\n      ‫التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف ‪1435/1/21‬ه ـ‬\n      ‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد‪ :‬فقــد جــرى منــا‬\n      ‫نحــن قضــاة الدائــرة الثانيــة لألحــوال الشــخصية واألوقــاف والوصايــا‬\n      ‫والقصــار وبيــوت املــال مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة‬\n      ‫االطــاع علــى الصــك الصــادر مــن فضيلــة الشــيخ‪ ...‬باحملكمــة العامــة‬\n      ‫باملدينــة املنــورة برقــم ‪ 34295759‬وتاريــخ ‪1434/8/13‬ه ـ املتضمــن‬\n      ‫دعــوى ‪ ...‬ضــد ‪ ...‬يف نفقــة ‪ ،‬وبدراســة الصــك وصــورة ضبطــه تقــررت‬\n      ‫املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                                    ‫آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪319‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":312,"source_page_end":319,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"feea0fa3ed3d9ebb384648324fb15287cd3fb5460442d8de8edca6da5207efd8","normalized_text_hash":"6074cc5039050e9703dddc174b5a739021e24477cb33950ceaffd2dfe2bbbadd","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p312-34295759"},{"id":"85d5af5b-99e4-52e4-a0f2-94f9e49f3b9f","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -إعالة وتسديد فواتير وإيجار الشقة ومصروفات املدارس - تقديرها عن طريق قسم اخلبراء -محاولة الصلح بن الطرفن - الصلح على مبالغ معينه -رصد الصلح يف ضبط القضية -امتنع املدعى عليه من التوقيع -صدر احلكم بصحة الصلح ولزومه .","document_number":"34302883","case_number":"307161127","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/22","year":"1434","subject":"نفقة -إعالة وتسديد فواتير وإيجار الشقة ومصروفات املدارس - تقديرها عن طريق قسم اخلبراء -محاولة الصلح بن الطرفن - الصلح على مبالغ معينه -رصد الصلح يف ضبط القضية -امتنع املدعى عليه من التوقيع -صدر احلكم بصحة الصلح ولزومه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/8/22 :‬هـ‬\n                 ‫ُ‬                 ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪34302883 :‬‬\n                   ‫َر ْق ُم الدعوى‪307161127 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34375195‬تاريخه‪1434/12/2 :‬هـ‬\n\n\n\n‫نفقــة ‪ -‬إعالــة وتســديد فواتيــر وإيجــار الشــقة ومصروفــات املــدارس ‪-‬‬\n‫تقديرهــا عــن طريــق قســم اخلبــراء ‪ -‬محاولــة الصلــح بــن الطرفــن ‪-‬‬\n‫الصلــح علــى مبالــغ معينــه ‪ -‬رصــد الصلــح يف ضبــط القضيــة ‪ -‬امتنــع‬\n    ‫املدعــى عليــه مــن التوقيــع ‪ -‬صــدر احلكــم بصحــة الصلــح ولزومــه ‪.‬‬\n\n\n\n\n                                      ‫‪ -‬قول اهلل تعالى ‪ ( :‬والصلح خير ) ‪.‬‬\n‫‪ -‬مــا أخرجــه أبــو داود والترمــذي مــن حديــث أبــي هريــرة رضــي اهلل‬\n‫عنــه وعمــرو بــن عــوف املزنــي أن رســول اهلل صلــى اهلل عليــه وســلم قــال‬\n                                            ‫( الصلــح جائــز بــن املســلمني ) ‪.‬‬\n                        ‫‪ -‬القاعدة الفقهية الكلية ( ال ضرر وال ضرار ) ‪.‬‬\n                                        ‫‪ -‬القاعدة الفقهية ( الضرر يزال ) ‪.‬‬\n                              ‫‪ -‬املادة (‪ )166‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n‫ادعــت املدعيــة بأنهــا زوجــة للمدعــى عليــه الغائــب عــن مجلــس احلكــم‬\n‫ورزقــت منــه بولديــن قاصريــن همــا ‪ ..‬و‪ ، ..‬وقــد هجرهــا منــذ عــام‬\n‫‪1427‬ه ـ وتركهــم بــا نفقــة هــي وأوالدهــا ولــم يقــم بســداد فواتيــر‬\n‫املــدارس وعقــد الشــقة وفواتيــر الكهربــاء وجميــع املبالــغ تقــدر مببلــغ‬\n\n                                                                                   ‫‪320‬‬\n\f      ‫وقــدره ‪ 395‬ألــف ريــال ‪ -‬مت بعــث املعاملــة لقســم اإلصــاح وقدمــت‬\n      ‫املــرأة مــا دفعتــه مبوجــب إيصــاالت وقــدرت النفقــة للولديــن ملــدة خمــس‬\n      ‫ســنوات مــع مبلــغ املــدارس وقــدر املبلــغ الــذي تســتحقه املــرأة ب ـ ‪ 191‬ألــف‬\n      ‫ريــال ‪ -‬يف جلســة أخــرى مت تــاوة مــا مت ضبطــه ســابق ًا يف اجللســة األولــى‬\n      ‫نظــر ًا النتقــال القاضــي األول ومباشــرة خلفــه يف نفــس املكتــب ‪ -‬حضر‬\n      ‫املدعــى عليــه يف هــذه اجللســة وبعــرض الدعوى عليــه صادق على خروجه‬\n      ‫مــن بيتــه ألن املدعيــة حاولــت قتلــه هــي وأوالدهــا ثــم ســافر إلــى اخلــارج يف‬\n      ‫شــوال ‪1431‬ه ـ ملرافقــة ابنتــه يف الدراســة ‪ -‬مت طلــب تفاصيــل النفقــات‬\n      ‫مــن املدعيــة فأحضرتهــا يف جلســة أخــرى ورصــدت يف ضبــط القضيــة‬\n      ‫وتشــمل إيجــار الشــقة وســداد دفعــات املــدارس إعطــاء األوالد املصــروف‬\n      ‫الشــهري واليومــي ومصــروف األكل والشــرب وأصبــح إجمالــي املبالــغ‬\n      ‫التــي تطالــب بهــا املدعيــة مبلــغ وقــدره ‪ 224.786‬ريــال وبعــرض ذلــك‬\n      ‫علــى املدعــى عليــه قــال لــن أنفــق عليهــم ألنهــم قامــوا بتهديــده وطــرده‬\n      ‫مــن بيتــه ‪ -‬مت إحالــة املعاملــة مــرة أخــرى لقســم اإلصــاح نظــر ًا لكبــر‬\n      ‫ســن الطرفــن وطــول مــدة زواجهــا فعــادت املعاملــة مــن قســم اإلصــاح‬\n      ‫يتضمــن أن املدعــى عليــه يدفــع للمدعيــة ‪ 120‬ألــف ريــال تكــون شــاملة‬\n      ‫للنفقــات واملصاريــف واملســتحقات الســابقة ويقــوم باإلنفــاق لــكل شــهر‬\n      ‫‪ 500‬ريــال علــى االبــن والبنــت ويقــوم بدفــع ‪1833‬ريــال أجــرة الســكن‬\n      ‫كل شــهر وهــذا الصلــح منهــي للنــزاع بــن الطرفــن ‪ -‬طلــب الطرفــان‬\n      ‫إثبــات هــذا الصلــح واحلكــم بــه ‪ ،‬حيــث إن الصلــح خيــر وهــو جائــز بــن‬\n      ‫املســلمني ‪ -‬صــدر احلكــم بصحــة هــذا الصلــح ولزومــه بــن الطرفــن‬\n      ‫وإجازتــه ‪ -‬و بعرضــه قــررت املدعيــة واملدعــى عليــه القناعــة بــه ‪ -‬بطلــب‬\n      ‫التوقيــع مــن املدعــى عليــه بعــد االنتهــاء مــن ضبــط القضيــة رفــض‬\n\n\n‫‪321‬‬\n\f‫املدعــى عليــه بشــهادة الكاتــب ‪ -‬حضــر وكيــل املدعــى عليــه يف جلســة‬\n‫أخــرى وقــرر عــدم قناعتــه باحلكــم بالئحــة اعتراضيــة وأفهــم بتعليمــات‬\n                ‫االســتئناف ‪ -‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن النبــي بعــده وبعــد فلــدي‬\n‫أنــا ‪ ...‬القاضــي باحملكمــة العامــة مبحافظــة جــدة ‪ .‬وبنــاء علــى املعاملــة‬\n‫احملالــة لنــا مــن فضيلــة رئيس احملكمة العامة مبحافظة جدة‪/‬املســاعد‬\n‫برقــم ‪ 307161127‬وتاريــخ ‪ 1431/12/21‬ه ـ املقيــدة باحملكمــة‬\n‫برقــم ‪ 31102386‬وتاريــخ ‪ 1431/12/21‬ه ـ ‪ .‬ويف يــوم االثنــن املوافــق‬\n‫‪1432/05/28‬ه ـ أفتتحــت اجللســة الســاعة ‪ 11 : 08‬وفيهــا حضــرت ‪...‬‬\n‫ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬وادعــت علــى الغائــب‬\n‫عــن مجلــس احلكــم ‪ ...‬وقــد بلــغ عــن طريــق البحــث والتحــري قســم‬\n‫ا يف دعــواه أن زوجــي هجرني منذ عام ‪1427‬هـ‬             ‫التحريــات والبحــث قائـ ً‬\n‫وملــدة خمــس ســنوات ولــم يقــم بإعالتــي أنــا وأبنائــي القصــار ‪ ...‬و‪ ...‬منــذ‬\n‫ذلــك احلــن وتركنــا دون ســكن واآلن لــم اســتطيع إعالــة نفســي اطلــب‬\n‫تســديد فواتيــر املــدارس وعقــد إيجــار الشــقة وفواتيــر الكهربــاء والتــي‬\n‫تقــدر مبلــغ وقــدرة ثالثمائــة وخمســة وتســعون ألــف ريــال هــذه دعــواي‬\n‫وقــد جــرى منــا بعــث املعاملــة إلــى قســم اإلصــاح مبوجــب خطابنــا رقــم‬\n‫‪ 31/102386‬يف ‪1431/3/13‬ه ـ فوردنــا جوابهــم مبوجــب خطابهــم رقم‬\n‫‪ 31/102386‬يف ‪1431/3/13‬ه ـ واملتضمــن (( أنــه قــد حضــرت املــرأة‬\n‫ولــم يحضــر املدعــى عليــه وذكــرت املــرأة بأنــه قد تركها هــي وأوالدها‬\n‫وســافر وال يصــرف عليهــا منــذ خمــس ســنني منــذ تاريــخ ‪1427‬ه ـ جمــاد‬\n\n                                                                                      ‫‪322‬‬\n\f      ‫األولــى حتــى تاريــخ هــذا الشــهر ‪1431/3/13‬ه ـ هــي وأوالدهــا ‪ ...‬و‪...‬‬\n      ‫وبنتهــا الكبيــرة التــي تزوجــت منــذ ثمانيــة اشــهر وعليــه نــرى أن يكــون‬\n      ‫مصــروف كل فــرد خمســمائة ريــال لــكل مــن املــرأة و‪ ...‬و‪ ...‬ســتون‬\n      ‫شــهر ًا والبنــت الكبــرى اثنــان وخمســون شــهر ًا مجمــوع نفقتهــم مائــه‬\n      ‫وســته عشــر ألــف ريــال ودفــع اإليجــارات التــي دفعتهــا املــرأة مثبتــه لديهــا‬\n      ‫باإليصــاالت مبلــغ وقــدرة خمســة وســتون ألــف ريــال مبالــغ املــدارس التــي‬\n      ‫دفعتهــا املــرأة عشــرة اآلف ريــال ويكــون مجمــوع مــا تســتحقه املــرأة مــن‬\n      ‫الرجــل مائــه وواحــد وتســعون ألــف ريــال هــذا مــا نــراه واهلل املوافــق )) ‪،‬‬\n      ‫هــذا مــا تضمنــه محضــر اإلصــاح ‪ .‬وبنــاء علــى ذلــك ســوف يتــم الكتابة‬\n      ‫للبحــث والتحــري وذلــك ألمــر القبــض علــى املدعــى عليه وإحضــاره وقت‬\n      ‫الــدوام الرســمي وعليــه جــرى رفــع اجللســة ‪ .‬ويف جلســة أخــرى لــدي أنــا ‪...‬‬\n      ‫القاضــي باحملكمــة العامــة مبحافظــة جــدة خلف ـ ًا لفضيلــة القاضــي ‪...‬‬\n      ‫‪ .‬ويف يــوم األحــد املوافــق ‪1433/01/30‬ه ـ أفتتحــت اجللســة الســاعة ‪00‬‬\n      ‫‪ 10 :‬وفيهــا حضــرت املدعيــة أصالــة وحضــر حلضورهــا املدعــى عليــه ‪...‬‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ، ...‬واســتناد ًا إلــى املــادة‬\n      ‫‪ 166‬مــن نظــام املرافعــات الشــرعية ولوائحهــا التنفيذيــة فقد جرى تالوة‬\n      ‫مــا مت ضبطــه علــى أســماع املتداعيــن وصــادق الطرفــان علــى صحتــه ‪.‬‬\n      ‫وبعــرض دعــوى املدعيــة علــى املدعــى عليــه أجــاب بقولــه ‪ :‬أننــي خرجــت‬\n      ‫مــن بيتــي بعــد أن هــددت بالقتــل بالســكني فكيــف أنفــق علــى مــن‬\n      ‫حاولــوا قتلــي ‪ ،‬ثــم إننــي غــادرت يف شــهر شــوال مــن عــام ‪1431‬ه ـ إلــى‬\n      ‫كنــدا مرافق ـ ًا البنتــي ‪ ...‬ملــدة ســنة ونصــف فكيــف انفــق ‪ ،‬هكــذا‬\n      ‫أجــاب ‪ .‬وقــد طلبــت مــن املدعيــة بيــان تفاصيــل النفقــات التــي تدعــي‬\n      ‫بهــا فقالــت بأننــي لــم أكتبهــا ومســتعدة بإحضارهــا يف اجللســة القادمــة‬\n\n\n‫‪323‬‬\n\f‫‪ ،‬وعليــه رفعــت اجللســة إلحضــار تفاصيــل املدفوعــات املدعــى بهــا مــن‬\n‫املدعيــة ‪ .‬ويف جلســة أخــرى يف يــوم األربعــاء املوافــق ‪1433/03/30‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 10 : 00‬وفيهــا حضــر املتداعيــان أصالــة ‪.‬‬\n‫وبســؤال املدعيــة عمــا أســتعدت بإحضــاره يف اجللســة املاضيــة مــن بيــان‬\n    ‫تفاصيــل النفقــات التــي تدعــي بهــا ‪ ،‬فأبــرزت الكشــف وهــذا نصــه‬\n‫(( أتقــدم لفضيلتكــم بســنداتي و الــذي قمــت فيهــا بـ ـس ــداد اإليجــارات‬\n‫و الدفعــات املدرســية ألبنائــي ‪ ...‬و ‪ ...‬و قيامــي بإعطائهــم مصروفاتهــم‬\n‫اليوميــة و الشــهرية و كذلــك فواتيــر الكهربــاء ‪ -1 :‬قمــت بســداد‬\n‫إيجار شــقة يف حي ‪ ...‬يف تاريخ ‪1427/11/20‬هـ إحدى عشــر ألف ريال‬\n‫(‪ -2 .)11,000‬قمت بسداد إيجار شقة يف تاريخ ‪1429/11/28‬هـ مبلغ‬\n‫و قــدره (‪ )22,000‬اثنــان و عشــرون ألــف ريــال ‪-3 .‬قمــت بســداد إيجــار‬\n‫شــقة بالدفــع إلــى املالكــة ‪ ...‬إيجــار شــهرين مببلــغ (‪ )5,000‬خمســة‬\n‫اآلف ريــال مــن ‪1431/9/1‬ه ـ إلــى ‪1432/10/30‬هــ‪ -4 .‬قمــت بســداد‬\n‫إيجــار شــقة عــن طريــق مكتــب ‪ ...‬للعقــار مبلــغ و قــدره (‪ )32,000‬اثنــان‬\n‫وثالثــون ألــف ريــال ‪ -5.‬شــيك مصــدق إيجــار شــقة عــن طريــق مكتــب‬\n‫‪ ...‬للعقــار إيجــار ســته أشــهر (‪ )13,000‬ثالثــة عشــر ألــف ومبلــغ نقــدي‬\n‫(‪ )3000‬ريــال ثالثــة اآلف ريــال مدفــوع مقدم ـ ًا ‪-6 .‬ســداد مدرســة ‪...‬‬\n‫وقيمــة الســداد (‪ )5500‬خمســة اآلف وخمســمائة ريــال قســط الصــف‬\n‫الســادس االبتدائــي‪ -7 .‬ســداد مدرســة ‪ ...‬وقيمــة الســداد هــي (‪)14500‬‬\n‫أربعة عشــر ألف و خمســمئة ريال و هذا قســط الصف الثاني ثنوي ‪-8 .‬‬\n‫ســداد مبلــغ دورة قــدرات ‪ )490( ...‬أربعمئــة و تســعني ريــال ‪ -9 .‬مجمــوع‬\n‫فواتيــر الكهربــاء ‪ 2296‬ريــال ‪ .‬وقــد هجرنــي أنــا وأبنائــي الثالثــة ‪ ...‬و‪...‬‬\n‫و‪ ...‬مــن تاريــخ ‪1427/10/20‬ه ـ و لــم يقــم باعطائهــم أي مصــروف أو‬\n\n\n                                                                                     ‫‪324‬‬\n\f      ‫مبالــغ ماليــة لهــم و ال مصروفهــم الدراســي و لــم يقــم بإعطائــي مصــروف‬\n      ‫مــأكل أو مشــرب لهــم‪ .‬ومت حســاب جميــع املبالــغ مــن {جلنــة إصــاح‬\n      ‫ذات البيــان} وهــي كالتالــي ‪ :‬مصــروف ابنتــي ‪ ...‬علــى مــدى اثنــان و‬\n      ‫خمســون شــهر وكل شــهر ‪ 500‬ريــال ويكــون مجموعهــا (‪)26,000‬‬\n      ‫ســته وعشــرون ألــف ريــال ‪ .‬و ‪ ...‬و‪ ...‬و ‪ ...‬قــدر لنــا مبلــغ شــهري مقــداره‬\n      ‫‪ 500‬ريــال لــكل فــرد علــى مــدى ســتني شــهرا وكان مجموعهــا ‪:‬‬\n      ‫(‪ )90000‬تســعون ألــف ريــال و هــذا مبلــغ مــن عــام ‪ 1427‬ه ـ ‪ { .‬ويكــون‬\n      ‫مجمــوع املبالــغ (‪ )224786‬مائتــان وأربــع وعشــرين ألــف وســبعمائة‬\n      ‫وســته وثمانــون ريــال} )) ‪ .‬وبعرضــه علــى املدعــى عليــه أجــاب بقولــه ‪ :‬أنــا‬\n      ‫لــن أنفــق عليهــم ‪ ،‬ألنهــم هددونــي وطردونــي مــن بيتــي ‪ ،‬ولــن أدفــع لهــم‬\n      ‫ريــا ًال واحــد ًا ولــو كان ذلــك علــى وفاتــي ‪ ،‬هكــذا أجــاب ‪ .‬ولالطــاع‬\n      ‫علــى الكشــف الــذي أبرزتــه املدعيــة ودراســته قــررت رفــع اجللســة ‪ .‬ويف‬\n      ‫جلســة أخــرى يف يــوم االثنــن املوافــق ‪1433/07/14‬ه ـ افتتحــت اجللســة‬\n      ‫الســاعة ‪ 11 : 00‬وفيهــا حضــر املتداعيــان أصالــة ‪ .‬ونظــر ًا لكبــر ســن‬\n      ‫الطرفني ولطول مدة زواجهما فقد قررت بعث املعاملة لقســم اإلصالح‬\n      ‫حملاولــة الصلــح بــن الطرفــن يف النفقــة ‪ .‬وألجلــه قــررت رفــع اجللســة ‪.‬‬\n      ‫ويف جلســة أخــرى يف يــوم اإلثنــن املوافــق‪ 1434/08/15‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 1.00‬وفيهــا حضــرت املدعيــة وحضــر حلضورهــا املدعى‬\n      ‫عليــه ‪ ...‬ســعودي مبوجــب الســجل املدنــي رقــم ‪ ...‬وعليــه جــرى محاولــة‬\n      ‫الصلــح بــن الطرفــن وتذكيرهمــا بــاهلل تعالــى اســتجاب كل واحــد‬\n      ‫فيهمــا للصلــح واتفقــا الطرفــان أن يعطــي املدعــى عليــه للمدعيــة مبلغـ ًا‬\n      ‫وقــدرة‪ 120‬مائــه وعشــرون ألــف ريــال تكــون شــاملة لــكل النفقــات‬\n      ‫واملصاريــف واملســتحقات املاليــة الســابقة التــي تطالــب بهــا املدعيــة وأن‬\n\n\n‫‪325‬‬\n\f‫ينفــق املدعــى عليــه علــى ابنــه ‪500 ...‬ريــال شــهري ًا وعلــى ابنتــه ‪ 500‬ريــال‬\n‫شــهري ًا وان يدفــع املدعــى عليــه كل شــهر اجــرة الســكن كل شــهر‬\n‫‪ 1833‬ريــال وأن يكــون هــذا الصلــح منهي ـ ًا لــكل نــزاع بــن الطرفــن‬\n‫يف موضــوع النفقــة واملســتحقات املاليــة الزوجيــة وطلــب الطرفــان اثبــات‬\n                                ‫هــذا الصلــح واحلكــم بــه هكــذا اصطلحــا ‪.‬‬\n‫وبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وملــا دار مــن صلــح بــن‬\n‫املتخاصمــن بعاليــه ولقــول اهلل تعالــى (( والصلــح خيــر )) وملــا أخرجــه‬\n‫اإلمــام أبــو داود والترمــذي مــن حديــث أبــي هريــرة وعمــرو بــن عــوف‬\n‫املزنــي أن رســول اهلل صلــى اهلل عليــه وســلم قــال (( الصلــح جائــز‬\n‫بــن املســلمني )) وللقاعــدة الفقهيــة الكليــة أنــه ال ضــرر وال ضــرار‬\n‫وللقاعــدة الفقهيــة أن الضــرر يــزال وملوافقــة الصلــح الــوارد بعاليــه‬\n‫لألصــول الشــرعية والقواعــد الفقهيــة فقــد أجــزت الصلــح الــوارد‬\n‫بعاليــه علــى الصفــة املذكــورة فيــه وحكمــت بصحتــه ولزومــه بــن‬\n‫الطرفــن‪ .‬وبعرضــه علــى الطرفــن قــررا القناعــة بــه ‪ .‬وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‬\n‫‪1434/08/15‬هــ‪ .‬ويف يــوم االثنــن املوافــق ‪1434/8/15‬ه ـ وبعــد‬\n‫االنتهــاء مــن ضبــط القضيــة‪ُ ،‬طلــب مــن الطرفــن التوقيــع علــى محضــر‬\n‫الضبــط ‪ ،‬فرفــض املدعــى عليــه ‪ ...‬التوقيــع‪ ،‬وذلــك بشــهادة الكاتــب‪....‬‬\n‫وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n‫‪ .‬حــرر يف ‪1434/8/21‬هــ‪ .‬ويف يــوم األحــد املوافــق ‪ 1434/08/21‬ه ـ‬\n‫حضــر ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬بوكالتــه عــن‬\n‫املدعــى عليــه ‪ ...‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة‬\n‫بشــمال جــدة برقــم ‪ 341145296‬وتاريــخ ‪1434/08/16‬ه ـ ‪ .‬وقــرر عــدم‬\n\n\n                                                                                        ‫‪326‬‬\n\f      ‫قناعتــه باحلكــم ‪ ،‬وطلــب رفــع املعاملــة حملكمــة االســتئناف بالئحــة‬\n      ‫اعتراضيــة ‪ .‬وأفهــم بــأن لــه حــق االعتــراض خــال ثالثــون يوم ـ ًا تبــدأ‬\n      ‫مــن ‪1434/08/22‬ه ـ ‪ ،‬وإذا مضــت املــدة ولــم يقــدم الئحــة فيكتســب‬\n      ‫احلكــم القطعيــة ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                 ‫آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/08/21‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n      ‫مبحافظــة جــدة ويف يــوم األربعــاء املوافــق ‪1435/1/3‬هـ كان قد وردتنا‬\n      ‫املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة برقــم ‪342615632‬‬\n      ‫يف ‪1434/12/19‬ه ـ والتــي حتــوي علــى القــرار الدائــرة الثانيــة لألحــوال‬\n      ‫الشــخصية واألوقــاف والوصايــا وبيــوت املــال بخصــوص دعــوى ‪ ...‬ضــد‬\n      ‫‪ ...‬وقــد تضمــن القــرار ( املوافقــة علــى احلكــم ) قاضــي اســتئناف ‪...‬‬\n      ‫ختــم وتوقيــع ‪ ...‬ختــم وتوقيــع ورئيــس الدائــرة ‪ ...‬ختــم وتوقيــع وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                        ‫حــرر يف ‪1435/01/03‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n      ‫جــرى منــا نحــن قضــاة الدائــرة الثالثــة لألحــوال الشــخصية واألوقــاف‬\n      ‫والوصايــا والقصــار وبيــوت املــال مبحكمــة االســتئناف يف منطقــة‬\n      ‫مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة مبحافظــة جــدة برقــم ‪ 31102386‬وتاريــخ بــدون‬\n      ‫املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ ‪ ...‬القاضــي باحملكمــة‬\n      ‫العامــة مبحافظــة جــدة برقــم ‪ 34302883‬وتاريــخ ‪1434/8/22‬ه ـ ‪،‬‬\n      ‫املتضمــن دعــوى املــرأة ‪ ...‬ضــد الغائــب عــن مجلــس احلكــم ‪ ...‬يف نفقــة‪،‬‬\n      ‫وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة ‪ ،‬تقــررت‬\n\n\n‫‪327‬‬\n\f‫املوافقــة علــى احلكــم ‪ ،‬واهلل املوفــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد‬\n                                                ‫وعلــى الــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                               ‫‪328‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":320,"source_page_end":328,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"054fb0ab84428bb83c7416fdab110a3cd38e5124903b2804d28dce450abd54c6","normalized_text_hash":"7473fb733ad80565affefd781d727ad76f3ed43dadf260701f96eb734990a6f2","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p320-34302883"},{"id":"ab985c5a-d78f-5126-a484-d4f5b222c2ab","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -مطالبة أم بنفقة أوالدها املاضية واملستقبلية -قصر الطلب على النفقة املستقبلية -تقدير النفقة عن طريق قسم اخلبراء - حكم بالنفقة املستقبلية -حكم مشمول بالنفاذ املعجل.","document_number":"34222949","case_number":"152270508","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/26","year":"1434","subject":"نفقة -مطالبة أم بنفقة أوالدها املاضية واملستقبلية -قصر الطلب على النفقة املستقبلية -تقدير النفقة عن طريق قسم اخلبراء - حكم بالنفقة املستقبلية -حكم مشمول بالنفاذ املعجل.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/5/26 :‬هـ‬\n                       ‫ُ‬                 ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪34222949 :‬‬\n                         ‫َر ْق ُم الدعوى‪152270508 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34303321‬تاريخه‪1434/8/23:‬هـ‬\n\n\n\n      ‫نفقــة ‪ -‬مطالبــة أم بنفقــة أوالدهــا املاضيــة واملســتقبلية ‪ -‬قصــر الطلــب‬\n      ‫علــى النفقــة املســتقبلية ‪ -‬تقديــر النفقــة عــن طريــق قســم اخلبــراء ‪-‬‬\n                  ‫حكــم بالنفقــة املســتقبلية ‪ -‬حكــم مشــمول بالنفــاذ املعجــل‪.‬‬\n\n\n\n\n                                           ‫‪ -1‬قوله تعالى { ل ُِي ْنفِ ْق ُذو َس َع ٍة مِ نْ َس َع ِتهِ}‪.‬‬\n                                       ‫‪ -2‬املادة (‪ )198‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n      ‫ادعــت املدعيــة ضــد املدعــى عليــه أنــه كان زوجهــا ورزق منهــا بابنتــن‬\n      ‫تقيمــان عنــد والدتهمــا املدعيــة وقــررت أن املدعــى عليــه ال ينفــق علــى‬\n      ‫ابنتيــه وأنهــا تنفــق عليهمــا بنيــة الرجــوع وطالبــت بتقديــر النفقــة املاضيــة‬\n      ‫واملســتقبلية ‪ -‬أجــاب املدعــى عليــه باملصادقــة علــى الدعــوى وأنكــر‬\n      ‫عــدم نفقتــه املاضيــة علــى ابنتيــه ‪ -‬حصــرت املدعيــة دعواهــا يف املطالبــة‬\n      ‫بالنفقــة املســتقبلية ‪ -‬مت تقديــر النفقــة املســتقبلية عــن طريــق قســم‬\n      ‫اخلبــراء مببلــغ وقــدره ســتمائة ريــال لــكل واحــدة منهــن غيــر شــاملة‬\n      ‫للعــاج ‪ ،‬والكســوة وتكــون مضاعفــة يف العيديــن ‪ -‬وافقــت املدعيــة‬\n       ‫علــى التقديــر ‪ -‬لألســباب املرصــودة ولقولــه تعالــى { ل ُِي ْنفِ ـ ْـق ُذو َسـ َـع ٍة مِ ــنْ‬\n      ‫َسـ َـع ِتهِ} صــدر احلكــم بإلــزام املدعــى عليــه بتســليم املدعيــة نفقــة البنتــن‬\n\n‫‪329‬‬\n\f‫مبلغ ـ ًا قــدره ألــف ومائتــا ريــال وبذلــك صــدر احلكــم مشــمو ًال بالنفــاذ‬\n‫املعجــل ‪ -‬صــدر قــرار محكمــة االســتئناف مبكــة املكرمــة باملوافقــة‬\n                                                               ‫علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة جــدة املســاعد برقــم ‪152270508‬‬\n‫وتاريــخ ‪1431/05/24‬ه ـ املقيــدة باحملكمــة برقــم ‪ 3149652‬وتاريــخ‬\n‫‪1431/05/24‬ه ـ ففــي يــوم األحــد املوافق‪1434/01/11‬ه ـ حضــرت‬\n‫‪ .....‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم‪ .....‬واملعــرف بهــا مــن‬\n‫قبــل والدهــا ‪ .....‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم‪ .....‬ولــم‬\n‫يحضــر املدعــى عليــه وال مــن ميثلــه ولــم يتقــدم بعــذر‪ ،‬وقــد وردنــا أصــل‬\n‫ورقــة البــاغ موقعــة مــن عمــدة حــي املــروة وعليــه شــرح هــذا نصــه‪( :‬ســلم‬\n‫الطلــب ألهلــه يف منــزل‪ .‬هــذا مــا نفيدكــم بــه)‪ .‬ا‪ .‬ه ـ ونظــرا ألن البــاغ‬\n‫وقــع لغيــر شــخص املدعــى عليــه أفهمــت املدعيــة بإعــادة التبليــغ مــرة‬\n‫أخــرى حتــى يتــم الســير يف الدعــوى حســب التعليمــات‪ .‬ويف يــوم الســبت‬\n‫املوافــق‪1434/02/23 :‬ه ـ حضــرت املدعيــة واملعــرف بهــا كمــا حضــر‬\n‫املدعــى عليــه أصالــة‪ .....‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة‬\n‫رقــم‪ .....‬وادعــت األولــى قائلــة‪ :‬إن هــذا احلاضــر كان زوجــا لــي فقــد‬\n‫طلقنــي يف بدايــة شــهر شــعبان مــن عــام‪1429 :‬ه ـ وولــدت لــه علــى فــراش‬\n‫الزوجيــة بنتــن همــا‪ ...‬املولــودة بتاريــخ‪1422/12/13 :‬ه ـ و ‪ ...‬املولــودة‬\n‫يف شــهر جمــادى األولــى لعــام‪1430 :‬ه ـ ومنــذ تاريــخ طالقــي والبنتــن‬\n\n                                                                                     ‫‪330‬‬\n\f      ‫(‪ ).....‬تقيمــان عنــدي ولــم ينفــق عليهمــا والدهمــا املدعــى عليــه البتــة‪،‬‬\n      ‫وقــد كنــت أنفــق عليهــم بنيــة الرجــوع‪ ،‬أطلــب إلــزام املدعــى عليــه‬\n      ‫بتســليم النفقــة املاضيــة اعتبــارا مــن تاريــخ‪1429/8/22 :‬ه ـ حتــى تاريخ‪:‬‬\n      ‫‪1434/2/22‬ه ـ وحتديــد نفقــة مســتقبلية للطفلتــن‪ ،‬هكــذا ادعــت‪.‬‬\n      ‫وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائـاً‪ :‬مــا ذكرتــه املدعيــة مــن‬\n      ‫الــزواج والطــاق وتاريخــه والبنتــن واســمهما وتواريــخ والدتهمــا وأنهمــا‬\n      ‫يقيمــان عندهــا منــذ تاريــخ طالقهــا فــكل ذلــك صحيــح ولكنــي‬\n      ‫آخذهمــا بعــض األحيــان مــن املدعيــة يــوم األربعــاء واخلميــس واجلمعــة‪،‬‬\n      ‫وأمــا مــا ذكرتــه أننــي لــم أنفــق عليهمــا البتــة فغيــر صحيــح والصحيــح‬\n      ‫أننــي أنفــق عليهمــا منــذ طالقــي لوالدتهمــا حتــى اآلن‪ ،‬وال مانــع لــدي‬\n      ‫مــن حتديــد نفقــة مســتقبلية لبنتــي (‪ ،).....‬وأطلــب رد دعــوى املدعيــة‬\n      ‫جتــاه مطالبتهــا بالنفقــة الســابقة وإخــاء ســبيلي منهــا‪ ،‬هكــذا أجــاب‪.‬‬\n      ‫وبســؤاله عــن بينتــه يف ذلــك أجــاب قائــا‪ :‬أطلــب مهلــة إلحضارهــا‪،‬‬\n      ‫هكــذا أجــاب‪ .‬ويف يــوم األربعــاء املوافــق‪1434/04/24 :‬ه ـ حضــرت‬\n      ‫املدعيــة ووالدهــا املعــرف بهــا واملدعــى عليــه‪ :‬املثبت حضورهم يف جلســة‬\n      ‫ســابقة‪ ،‬وبســؤال املدعــى عليــه عمــا اســتمهل مــن أجلــه أحضــر للشــهادة‬\n      ‫وأدائهــا‪ .....، :‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم‪ .....‬وهــو‬\n      ‫مــن مواليــد عــام‪1382 :‬ه ـ ويعمــل يف ‪ ...‬ويســكن يف حــي ‪ .......‬وطــريف‬\n      ‫النــزاع مــن أبنــاء عمومتــه ويزيــد املدعــى أنــه أخ لزوجتــه ـ حســب إفادتــه ـ‬\n      ‫وشــهد قائــا‪( :‬أشــهد هلل أننــي أرى املدعــى عليــه يشــتري لبناتــه كســوة‬\n      ‫األعيــاد منــذ إقامتهــن عنــد والدتهــن‪ ،‬ورأيتــه مــا ال أحصــي يعطــي ابنتــه‬\n      ‫الكبيــرة (‪ ).....‬بعــد انتهــاء وقــت زيارتهــا لــه وقبــل الذهــاب بهــا لوالدتهــا‬\n      ‫مبالــغ ماليــة علــى فتــرات متفرقــة مــن (‪ 300‬ـ ‪ ،)500‬عمــا بــأن زوجتــي‬\n\n\n‫‪331‬‬\n\f‫تذهــب معــه لألســواق لشــراء كســوة لبناتــه‪ ،‬وقــد ســمعت املدعــى عليــه‬\n‫يكلــم املدعيــة عــن طريــق اجلــوال ويقــول للمدعيــة أنــه ســوف يتكفــل‬\n‫بتوصيــل بناتــه للمدرســة فامتنعــت املدعيــة)‪ ،‬هــذا مــا لــدي وبــه أشــهد‪.‬‬\n‫ثــم أضــاف الشــاهد مخاطبــا املدعــى عليــه‪( :‬اطلــب حضانــة أبنائــك‬\n‫مــن القاضــي كــي تربيهــم أنــت)‪ ،‬هكــذا أضــاف‪ .‬وبعــرض الشــاهد‬\n‫وشــهادته علــى املدعيــة أجابــت قائلــة‪ :‬هــو شــخص متحامــل علــي‪،‬‬\n                                   ‫وشــهادته غيــر صحيحــة‪ ،‬هكــذا أجابــت‪.‬‬\n‫وبســؤال املدعــى عليــه عــن زيــادة بينــة أحضــر للشــهادة وأدائهــا ‪..... ،‬‬\n‫ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم‪ .....‬وهــو مــن مواليــد عــام‪:‬‬\n‫‪1390‬ه ـ ويعمــل ‪ ....‬وليــس لــه قرابــة بالطرفــن ويســكن يف حــي ‪.......‬ـ‬\n‫حسب إفادته ـ وشهد قائال‪( :‬أشهد هلل أنني أكون كثيرا من األحيان‬\n‫مــع املدعــى عليــه وإذا انتهــت فتــرة الزيــارة وأراد أن يرجعهــم لوالدتهــم‬\n‫يشــتري لهــن كل مــا يحتاجونــه مــن اللبــاس وكســوة العيــد وأغــراض‬\n‫املدرســة وقبــل أن ينزلهــم يعطــي كل واحــدة مــن البنتــن مبلــغ يتــراوح‬\n‫مــا بــن ‪ 20‬ـ ‪ )50‬هــذا مــا لــدي وبــه أشــهد‪ .‬وبعــرض الشــاهد وشــهادته‬\n‫علــى املدعيــة أجابــت قائلــة‪ :‬بالنســبة للشــاهد فهــو مســتور احلــال‪ ،‬وأمــا‬\n‫شــهادته فهــي عليــه هــل يكفــي كل أســبوع أن يعطــي كل واحــدة‬\n‫مبلغــا قــدره‪ :‬خمســون ريــاال؟ هكــذا أجابــت‪ .‬وبســؤال املدعــى عليــه عــن‬\n‫زيــادة بينــة أجــاب قائــا‪ :‬أكتفــي مبــا قدمــت‪ ،‬هكــذا أجــاب‪ .‬ونظــرا‬\n‫لوصــول القضيــة لهــذا احلــد فقــد أمــرت بالكتابــة لقســم اخلبــراء لتقديــر‬\n‫نفقــة البنتــن (‪ )....... ، .......‬مــن تاريــخ‪1429/8/22 :‬ه ـ وحتديــد نفقــة‬\n‫مســتقبلية‪ .‬ويف يــوم األحــد املوافــق‪1434/05/26 :‬ه ـ حضــرت املدعيــة‬\n‫‪ .......‬ووالدهــا املعــرف بهــا ‪ ،‬ولــم يحضــر املدعــى عليــه‪ :‬رغــم تبلغــه‬\n\n\n                                                                                     ‫‪332‬‬\n\f      ‫مبوعــد هــذه اجللســة حســب توقيعــه علــى ضبــط اجللســة الســابقة‪ ،‬وقــد‬\n      ‫وردنــا كتــاب رئيــس قســم الصلــح رقــم‪ 3456691 :‬يف‪1434/4/22 :‬ه ـ‬\n      ‫ومرفــق بــه محضــر هــذا نصــه‪( :‬وحيــث ذكــرت املدعيــة بــأن املدعــى‬\n      ‫عليــه يعمــل ســائق أجــرة خاصــة وال يقــل دخلــه الشــهري منهــا مبلغ ـ ًا‬\n      ‫ثالثــة آالف ريــال وقــد ورث عــن والــده منــذ مــدة قريبــة جــد ًا ولديــه شــقة‬\n      ‫متليــك وهــو يعيــش مبفــرده وال يكفــل أحــد غيــر نفســه وليــس عليــه أي‬\n      ‫التزامــات وبنــاء عليــه فإننــا نــرى أن تقــدر نفقــة البنتــن (‪ ).....‬الشــهرية‬\n      ‫مببلــغ قــدره‪ :‬ســتمائة ريــال لــكل واحــدة منهــن غيــر شــاملة للعــاج وأمــا‬\n      ‫الكســوة فتكــون مضاعفــة يف العيديــن)‪ .‬ا‪ .‬ه ـ وبعــرض ذلــك علــى‬\n      ‫املدعيــة أجابــت قائلــة‪ :‬أنــا موافقــة علــى هــذا التقديــر‪ ،‬وأطلــب حصــر‬\n      ‫دعــواي يف املطالبــة بالنفقــة املســتقبلية‪ ،‬وأمــا الســابقة فســوف أقيــم‬\n      ‫فيهــا دعــوى مســتقلة الحقــا‪ ،‬وأطلــب تضمــن احلكــم بالنفــاذ املعجــل‪،‬‬\n      ‫هكــذا أجابــت‪ .‬فبنــاء علــى مــا ســلف‪ ،‬ولقــول اهلل ـ تعالــى ـ‪( :‬لينفــق‬\n      ‫ذو ســعة مــن ســعته)‪ ،‬ونظــر ًا حلاجــة البنتــن للنفقــة‪ ،‬وألن الوالــد جتــب‬\n      ‫عليــه نفقــة ولــده كاملــة ينفــرد بهــا‪ ،‬وألنــه جــرى تقديــر النفقــة لــكل‬\n      ‫واحــدة مــن البنتــن ســتمائة ريــال حســب القــرار املرصــود أعــاه‪ ،‬وبنــاء‬\n      ‫علــى املــادة الثامنــة والتســعون بعــد املئــة مــن نظــام املرافعــات الشــرعية‪،‬‬\n      ‫لذلــك كلــه فقــد ألزمــت املدعــى عليــه أن يســلم للمدعيــة نفقــة بنتيهــا‬\n      ‫(‪...‬و‪ )...‬بتاريــخ واحــد مــن كل شــهر هجــري مبلغــا قــدره‪ :‬ألــف ومئتــا‬\n      ‫ريــال اعتبــار ًا مــن شــهر جمــادى اآلخــر لعــام‪1434 :‬ه ـ وبذلــك حكمــت‬\n      ‫حكمــا مشــموال بالنفــاذ املعجــل‪ .‬وهــذا احلكــم يعــد حضوريــا يف حــق‬\n      ‫املدعــى عليــه‪ .‬وبإعــان احلكــم قــررت املدعيــة قناعتهــا باحلكــم‪ ،‬أمــا‬\n      ‫املدعــى عليــه فســوف يبلــغ باحلكــم ولــه االعتــراض بطلــب التمييــز‬\n\n\n‫‪333‬‬\n\f‫خــال ثالثــن يوم ـ ًا اعتبــار ًا مــن تاريــخ تبليغــه بنســخة احلكــم‪ ،‬وإذا‬\n‫تأخــر عــن هــذه املـ ّـدة ـ مــع تبلغــه لشــخصه بنســخة احلكــم ـ ســقط‬\n‫القطعيــة‪،‬‬\n      ‫ّ‬      ‫حقــه يف االعتــراض بطلــب االســتئناف واكتســب احلكــم‬\n‫وإذا تب َّلــغ لغيــر شــخصه ولــم يقـ ِّـدم اعتراضــه رفــع احلكــم لالســتئناف‬\n‫مــن دون اعتــراض‪ .‬وســوف يتــم الكتابــة للجهــة التنفيذيــة إلنفــاذ هــذا‬\n‫احلكــم عاجــا بكفالــة‪ .‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمد‬\n                      ‫وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/05/26‬ه ـ‬\n‫احلمــد هلل وحــده‪ ،‬وبعــد‪ :‬ويف يــوم اإلثنــن املوافــق‪1434/09/14 :‬ه ـ‬\n‫عــادت املعاملــة مــن محكمــة االســتئناف وبرفقهــا قــرار دائــرة األحــوال‬\n‫الشــخصية الثانيــة رقــم ‪ 34303321‬يف ‪1434/08/23‬ه ـ ونــص احلاجــة‬\n‫منــه‪( :‬وبدراســة احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر‬\n‫باألكثريــة املوافقــة علــى احلكــم) ا‪ .‬ه ـ وللبيــان جــرى إثباتــه‪ ،‬وأمــرت‬\n‫بإحلــاق ذلــك علــى الصــك والســجل‪ .‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى‬\n    ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‪1434/09/14 :‬ه ـ‬\n‫احلمــد هلل والصــاة والســام علــى مــن ال نبي بعــده ‪ ،‬وبعد فقد جرى منا‬\n‫نحــن قضــاة الدائــرة الثانيــة لألحــوال الشــخصية واألوقــاف والوصايــا‬\n‫والقصــار وبيــوت املــال مبحكمــة االســتئناف يف منطقــة مكــة‬\n‫املكرمــة االطــاع علــى الصــك الصــادر مــن فضيلــة الشــيخ‪ .....‬القاضــي‬\n‫باحملكمــة العامــة بجــدة برقــم ‪ 34222949‬وتاريــخ ‪ 1434/5/26‬ه ـ‬\n‫املتضمــن دعــوى‪ .....‬ضــد ‪ .....‬يف دعــوى نفقــة آدمــي وبدراســة الصــك‬\n‫وصــورة ضبطــه والالئحــة االعتراضيــة تقــرر باألكثريــة املوافقــة علــى‬\n‫احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه‬\n                                                                        ‫وســلم ‪.‬‬\n\n\n                                                                                   ‫‪334‬‬\n\f335\n\f336\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":329,"source_page_end":336,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6674a2f8557fdd2a6b7dfc89a1076d9543f25b9b99ce8a4e60a98fb085ae0964","normalized_text_hash":"a7b5a476e0a5cf91ac6136768423e9d2039acab463a4eb868a836a02a647384a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p329-34222949"},{"id":"0ca464b4-d922-5af7-9cb9-6deb3d01cd21","document_type":"judgment","category":"judicial","subcategory":"general","title":"زوجية -منع تدخل -مطالبة زوج والد زوجته بكف تدخله بينه وبن زوجته -مصادقة املدعى عليه على الدعوى وبرر تدخله بأن املدعي طلق ابنته وال بينة له بذلك -إنكار املدعي وقوع الطاق - األصل بقاء عقد النكاح -إلزام المحكمة املدعى عليه بكف يده عن زوجة املدعي -اعترض املدعى عليه -صدق احلكم.","document_number":"34352237","case_number":"34306303","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/6","year":"1434","subject":"زوجية -منع تدخل -مطالبة زوج والد زوجته بكف تدخله بينه وبن زوجته -مصادقة املدعى عليه على الدعوى وبرر تدخله بأن املدعي طلق ابنته وال بينة له بذلك -إنكار املدعي وقوع الطاق - األصل بقاء عقد النكاح -إلزام المحكمة املدعى عليه بكف يده عن زوجة املدعي -اعترض املدعى عليه -صدق احلكم.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"   ‫تاريخه‪1434/11/6 :‬هـ َر ْق ُم‬\n                          ‫ُ‬                   ‫َر ْق ُم َّ‬\n                                ‫الص ِّك‪34352237 :‬‬\n                                  ‫الدعوى‪34306303 :‬‬\n‫رقم قرار التصديق من محكمة االستئناف ‪35114060 :‬‬\n                                ‫تاريخه‪1434/1/14 :‬هـ‬\n\n\n            ‫زوجيــة ‪ -‬منــع تدخــل ‪ -‬مطالبــة زوج والــد زوجتــه بكــف تدخلــه بينــه‬\n            ‫وبــن زوجتــه ‪ -‬مصادقــة املدعــى عليــه علــى الدعــوى وبــرر تدخلــه بــأن‬\n            ‫املدعــي طلــق ابنتــه وال بينــة لــه بذلــك ‪ -‬إنــكار املدعــي وقــوع الطــاق ‪-‬‬\n            ‫األصــل بقــاء عقــد النــكاح ‪ -‬إلــزام احملكمــة املدعــى عليــه بكــف يــده عــن‬\n                              ‫زوجــة املدعــي ‪ -‬اعتــرض املدعــى عليــه ‪ -‬صــدق احلكــم‪.‬‬\n\n\n\n\n            ‫مــا اســتند إليــه القاضــي مــن املبــادئ العامــة وقواعــد اإلثبــات والعدالــة‬\n                                                                       ‫يف تســبيب حكمــه‪.‬‬\n\n\n\n\n            ‫أقــام زوج دعــوى يطالــب والــد زوجتــه بكــف اعتراضــه و انقيــاد‬\n            ‫زوجتــه لــه ‪ ،‬رفــض املدعــى عليــه انقيــاد ابنتــه للمدعــى بســبب طالقــه‬\n            ‫لهــا وال بينــة لــه بذلــك ‪ ،‬أنكــر املدعــي طــاق زوجتــة ‪ ،‬وألن األصــل‬\n            ‫بقــاء النــكاح وال بينــة علــى الطــاق حكمــت احملكمــة بإلــزام املدعــى‬\n            ‫عليــه بكــف اعتراضــه وانقيــاد ابنتــه لزوجهــا املدعــي ‪ ،‬اعتــرض املدعــى‬\n                                                                  ‫عليــه‪ -‬وصــدق احلكــم‬\n\n\n\n\n    ‫‪337‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة ‪ ..........‬وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة برقــم وتاريــخ املقيــدة باحملكمــة برقــم‬\n‫(‪ ).....‬وتاريــخ ‪ .....‬افتتحــت اجللســة الســاعة ‪ 09 : 00‬وفيهــا حضــر ‪..........‬‬\n‫بالســجل املدنــي رقــم ‪ ..........‬وادعــى علــى احلاضــر معــه (‪ ).....‬بالســجل‬\n‫املدنــي رقــم (‪ ).....‬قائــا يف دعــواه أنــه بتاريــخ عقــدت الــزواج علــى بنــت‬\n‫املدعــى عليــه ودخلــت بهــا بتاريــخ ‪1432/10/5‬ه ـ وســكنت معــي يف‬\n‫بيتــي يف محافظــة (‪ ).....‬ويف أواخــر شــهر جمــادى األولــى مــن عــام‬\n‫‪1433‬ه ـ كانــت زوجتــي املذكــورة يف بدايــة حملهــا وطلبــت منــي أن‬\n‫أذهــب بهــا إلــى بيــت والدهــا مبحافظــة (‪ ).....‬فرفضــت وجــاء والدهــا‬\n‫املدعــى عليــه وأخذهــا مــن بيتــي دون إذن منــي وال تــزال عنــد املدعــى‬\n‫عليــه واملدعــى عليــه يعتــرض انقيــاد زوجتــي املذكــورة لــي لــذا أطلــب‬\n‫إلــزام املدعــى عليــه بكــف اعتراضــه انقيــاد زوجتــي املذكــورة لــي‬\n‫هكــذا ادعــى وبســؤال املدعــى عليــه أجــاب بقولــه مــا ذكــره املدعــي‬\n‫مــن عقــد الــزواج علــى بنتــي املذكــورة بالتاريــخ املذكــور وأنــه دخــل‬\n‫بهــا بالتاريــخ املذكــور وســكنت معــه يف محافظــة (‪ ).....‬فصحيــح ومــا‬\n‫ذكــره املدعــي أنــي أخــذت بنتــي املذكــورة مــن بيتــه بــدون إذنــه فغيــر‬\n‫صحيــح بــل الصحيــح أنــي أخذت بنتي املذكــورة بتاريخ ‪1433/5/19‬هـ‬\n‫مــن بيــت املدعــي بــإذن مــن املدعــي ومــا ذكــره أن بنتــي املذكــورة ال‬\n‫تــزال عنــدي وأنــي اعتــرض انقيــاد بنتــي املذكــورة للمدعــي فصحيــح‬\n‫والســبب أنــه بتاريــخ ‪1433/5/21‬ه ـ ذهبــت ببنتــي املذكــورة إلــى بيــت‬\n\n                                                                                      ‫‪338‬‬\n\f      ‫املدعــي يف محافظــة (‪ ).....‬ووجــدت بيــت املدعــي مغلــق وانتظــرت عنــد‬\n      ‫بيــت املدعــي مــن الســاعة الرابعــة عصــر ًا إلــى آذان العشــاء وجــاء املدعــي‬\n      ‫وقــال املدعــي لــي ( بنتــك طالــق وورقتهــا جتيهــا وتأخــذ عفشــها كلــه‬\n      ‫اللــي يف البيــت) وأنــا معتــرض انقيــاد بنتــي املذكــورة للمدعــي لكــون‬\n      ‫املدعــي طلقهــا هكــذا أجــاب وبعــد ســماع الدعــوى واإلجابــة طلبــت مــن‬\n      ‫املدعــى وثيقــة عقــد الــزواج فأبــرز عقد الزواج رقــم ‪ 24/46/233‬وتاريخ‬\n      ‫‪1431/8/29‬ه ـ الصــادر مــن مــأذون عقــود األنكحــة (‪ ).....‬املصــرح‬\n      ‫لــه بإجــراء عقــود األنكحــة لســكان محافظــة جــدة املتضمــن عقــد‬\n      ‫نــكاح بالســجل املدنــي رقــم (‪ ).....‬علــى املــرأة ســجلها املدنــي رقــم(‪).....‬‬\n      ‫مرفقــه صورتــه باملعاملــة ثــم ســألت املدعــي عمــا ذكــره املدعــى عليــه‬\n      ‫مــن الطــاق فأجــاب املدعــي بقولــه مــا ذكــره املدعــى عليــه أنــي طلقــت‬\n      ‫زوجتــي املذكــورة فغيــر صحيــح هكــذا أجــاب ثــم طلبــت مــن املدعــى‬\n      ‫عليــه البينــة علــى طــاق املدعــي لزوجتــه املذكــورة فأجــاب بقولــه ال‬\n      ‫يوجــد لــدي بينــة هكــذا أجــاب وبنــاء علــى جميــع مــا تقــدم ومبــا أن‬\n      ‫املدعــى عليــه أقــر بالــزواج ومبــا أن املدعــى عليــه أقــر باعتراضــه انقيــاد‬\n      ‫بنتــه املذكــورة للمدعــي ومبــا أن املدعي أنكــر طالق زوجته املذكورة‬\n      ‫ولــم يثبــت املدعــى عليــه الطــاق لــذا فقــد حكمــت بإلــزام املدعــى عليــه‬\n      ‫بكــف اعتراضــه انقيــاد زوجــة املدعــي املذكــورة وبعــد النطــق باحلكم‬\n      ‫وتالوتــه عليهمــا أفهمتهمــا بطــرق االعتــراض املقــررة ومواعيدهــا فقــرر‬\n      ‫املدعــي قناعتــه وقــرر املدعــى عليــه عــدم قناعتــه وأفهمتــه مبراجعتنــا‬\n      ‫يــوم اخلميــس املوافــق ‪1434/11/6‬ه ـ الســتالم نســخة مــن صــك احلكــم‬\n      ‫وتقــدمي مذكــرة اعتراضيــة إلــى إدارة احملكمــة خــال مــدة أقصاهــا‬\n      ‫ثالثــون يومــا مــن التاريــخ احملــدد لالســتالم وإذا انتهــت املــدة ولــم يتقــدم‬\n\n\n‫‪339‬‬\n\f‫باعتراضــه فــإن احلــق يف طلــب االســتئناف يســقط ويكتســب احلكــم‬\n‫القطعيــة واختتمــت اجللســة الســاعة ‪ 09 : 25‬وبــاهلل التوفيــق وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/11/05‬ه‪.‬‬\n‫احلمــد هلل وحــده وبعــد يف هــذا اليــوم األربعــاء املوافــق ‪1435/02/01‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪11 : 00‬واملعاملــة قــد عــادت مــن محكمــة‬\n‫االســتئناف بالقصيــم وقــد مت التظهيــر علــى صــك احلكــم بقــرار دائــرة‬\n‫األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف مبنطقة القصيم‬\n‫رقم ‪ 35114060‬وتاريخ ‪1435/1/14‬هـ نصه (تظهيرات دائرة األحوال‬\n‫الشــخصية واإلنهــاءات مبحكمــة االســتئناف مبنطقــة القصيــم احلمــد‬\n‫هلل وحــده وبعــد فقــد اطلعنــا علــى هــذا الصــك رقــم ‪ 34352237‬وتاريــخ‬\n‫‪1434/11/6‬ه ـ الصــادر مــن فضيلــة الشــيخ القاضــي باحملكمــة العامة‬\n‫وأصدرنــا القــرار رقــم ‪ 35114060‬وتاريــخ ‪1435/1/14‬ه ـ املتضمــن‬\n‫املصادقــة علــى مــا حكــم بــه فضيلتــه قاضــي اســتئناف (‪ ).....‬قاضــي‬\n‫اســتئناف (‪ ).....‬رئيــس الدائــرة (‪ ).....‬أ‪ .‬ه ـ واختتمــت اجللســة الســاعة‬\n‫‪11 :10‬وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                              ‫وســلم‪ .‬حــرر يف ‪1435/2/1‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة املختصــة‬\n‫بتدقيــق قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n‫مبنطقــة القصيــم علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة مبحافظــة ‪ ..........‬برقــم (‪ )..........‬وتاريــخ ‪1435/1/9‬هــ؛ املقيــدة‬\n‫لــدى احملكمــة برقــم (‪ )..........‬وتاريــخ ‪1435/1/10‬هــ؛ اخلاصــة‬\n‫ب ــدعوى‪ ).....(/‬ضــد‪ ).....(/‬؛ بشــأن مطالبتــه بإلــزام املدعــى عليــه‬\n‫بكــف اعتراضــه انقيــاد زوجتــه‪).....(/‬؛ املنتهيــة بالصــك الصــادر مــن‬\n\n\n                                                                                    ‫‪340‬‬\n\f      ‫فضيلــة الشــيخ‪ ).....(/‬القاضــي باحملكمــة؛ املســجل برقــم () وتاريــخ‬\n      ‫‪1434/11/6‬هــ؛ املتضمــن حكــم فضيلتــه بإلــزام املدعــى عليــه بكــف‬\n      ‫اعتراضــه انقيــاد زوجــة املدعــي املذكــورة؛ علــى النحــو املفصــل فيــه‪.‬‬\n      ‫وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة‬\n      ‫قررنــا املصادقــة علــى مــا حكــم بــه فضيلتــه‪ .‬واهلل املوفــق‪ ،‬وصلــى اهلل‬\n                                         ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪341‬‬\n\f342\n\f343\n\f344\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":337,"source_page_end":344,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f5d895f131ef5f9e1c6a0a976bee123c878118d45050e14768773c15106e2587","normalized_text_hash":"85455408baefb95bf1e0193acb7a21add4634f326fa41bf366cca5bfc3c559f8","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p337-34352237"},{"id":"5cb99f47-c0a7-559b-8682-d1ae393e6bb9","document_type":"judgment","category":"judicial","subcategory":"general","title":"طلب إعادة خادمة -تخلف املدعى عليه عن احلضور مع تبلغه باملوعد لشخصه -تخلف املدعى عليه يعد نكو ال -رد اليمن إلى املدعي بصحة دعواه ألن احلق يعرف من جهته -إلزام املدعى عليه","document_number":"3462374","case_number":"33343992","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعنيزة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/15","year":"1434","subject":"طلب إعادة خادمة -تخلف املدعى عليه عن احلضور مع تبلغه باملوعد لشخصه -تخلف املدعى عليه يعد نكو ال -رد اليمن إلى املدعي بصحة دعواه ألن احلق يعرف من جهته -إلزام املدعى عليه","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/3/15 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪3462374 :‬‬\n                         ‫َر ْق ُم الدعوى‪33343992 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34228433‬تاريخه‪1434/6/3 :‬هـ‬\n\n\n      ‫طلــب إعــادة خادمــة ‪ -‬تخلــف املدعــى عليــه عــن احلضــور مــع تبلغــه‬\n      ‫باملوعــد لشــخصه ‪ -‬تخلــف املدعــى عليــه يعــد نكــو ًال ‪ -‬رد اليمــن إلــى‬\n      ‫املدعــي بصحــة دعــواه ألن احلــق يعــرف مــن جهتــه ‪ -‬إلــزام املدعــى عليــه‬\n                                                                      ‫بــرد اخلادمــة ‪.‬‬\n\n\n\n\n                                         ‫‪ -1‬املادة (‪ )55‬من نظام املرافعات الشرعية ‪.‬‬\n                                       ‫‪ -2‬املادة (‪ )101‬من نظام املرافعات الشرعية ‪.‬‬\n                                    ‫‪ -3‬املادة (‪ )2/103‬من نظام املرافعات الشرعية ‪.‬‬\n                                   ‫‪ -4‬املادة (‪ ) 5/179‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي أنــه كفــل خادمتــه للعمــل عنــده‪ ،‬وقــد عملــت عنــده فتــرة‬\n      ‫معينــة ثــم اســتغنى عنهــا‪ ،‬طلــب منــه املدعــى عليــه أخذهــا لتجربتهــا‬\n      ‫يف العمــل ثــم نقــل كفالتهــا إليــه فوافــق علــى ذلــك‪ ،‬مت تســليمها إليــه‬\n      ‫وبعــد ذلــك لــم يتوصــل إليــه بــأي طريقــة أو وســيلة‪ ،‬طلــب إلزامــه بإعــادة‬\n      ‫اخلادمــة‪ ،‬مت إبــاغ املدعــى عليــه بجميــع اجللســات إال أنــه لــم يحضــر‬\n      ‫ال عــن اليمــن حــال عــدم احلضــور‬    ‫كمــا مت إبالغــه باعتبــاره نــاك ً‬\n      ‫ولكــن دون جــدوى ‪ ،‬حيــث إن املدعــى عليــه غيــر متجــاوب فقــد أفهــم‬\n\n‫‪345‬‬\n\f‫القاضــي املدعــي بــأن عليــه أن يحلــف اليمــن علــى مــا جــاء بدعــواه ألن‬\n‫ال عــن اليمــن وهــذا مــن املواضــع التــي تــرد‬ ‫املدعــى عليــه يعــد نــاك ً‬\n‫فيهــا اليمــن علــى املدعــي ألن احلــق يعــرف مــن جهتــه كمــا نــص عليــه‬\n‫احملققــون كشــيخ اإلســام وابــن القيــم ‪ ،‬حلــف املدعــي اليمــن كمــا‬\n‫طلبــت منــه ‪ ،‬بنــاء علــى عــدم حضــور املدعــى عليــه مــع تبليغه لشــخصه ‪،‬‬\n‫ال واحلالــة هــذه ‪ ،‬وبنــاء علــى املادتــن‬\n                                          ‫وحيــث إن املدعــى عليــه يعــد نــاك ً‬\n‫(‪ )55‬و ( ‪ ) 2/103‬مــن نظــام املرافعــات الشــرعية ‪ ،‬صــدر احلكــم‬\n‫بإلــزام املدعــى عليــه بإعــادة اخلادمــة املذكــورة للمدعــي ‪ ،‬احلكــم يف‬\n‫حــق املدعــى عليــه يعــد حضوريـ ًا ‪ ،‬تســليم املدعــى عليــه نســخة احلكــم‬\n‫عــن طريــق محضــري اخلصــوم وإفهامــه بتعليمــات االســتئناف ‪ ،‬صــدق‬\n‫احلكــم مــن محكمــة االســتئناف ‪ ،‬ورد خطــاب الشــرطة بأنــه لــم يتــم‬\n‫تســليم صــورة احلكــم للمدعــى عليــه رغــم التــردد علــى منزلــه أكثــر‬\n‫مــن مــرة ويف أوقــات مختلفــة وهواتفــه مغلقــة بصفــة مســتمرة ‪ ،‬مت بعــث‬\n‫املعاملــة حملكمــة االســتئناف بنــاء علــى املــادة ( ‪ ) 5/179‬مــن نظــام‬\n‫املرافعــات الشــرعية ولوائحــه التنفيذيــة ‪ ،‬صــدق احلكــم مــن محكمــة‬\n                                                                    ‫االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد يف يــوم الثالثــاء املوافــق ‪1433/07/01‬ه ـ لــدي‬\n‫أنــا ‪ ......‬القاضــي يف احملكمــة العامــة بعنيــزة افتتحــت اجللســة يف‬\n‫وقتهــا احملــدد لســماعها يف الســاعة الثامنــة والنصــف صباحـ ًا للنظــر يف‬\n‫الدعــوى املقدمــة مــن ‪ ......‬ضــد ‪ ......‬واملقيــدة يف هــذه احملكمــة برقــم‬\n‫‪ 33921012‬يف ‪1433/05/16‬ه ـ واحملالــة لنــا بشــرح فضيلــة الرئيــس‬\n\n                                                                                    ‫‪346‬‬\n\f      ‫وقــد افتتحــت هــذه اجللســة بنــاء علــى املــادة اخلامســة واخلمســن مــن‬\n      ‫نظــام املرافعــات الشــرعية ولوائحــه التنفيذيــة وفيهــا حضــر ‪ ......‬ســعودي‬\n      ‫مبوجــب الســجل رقــم ‪ ......‬وادعــى علــى الغائــب عــن مجلــس القضــاء‬\n      ‫الــذي تبلــغ بهــذا املوعــد لشــخصه حســبما يظهر من ورقــة التبليغ املرفقة‬\n      ‫باملعاملــة قائــا يف حتريــر دعــواه لقــد اســتقدمت خادمــة مــن اثيوبيــا يف‬\n      ‫‪1432/09/15‬ه ـ وعملــت لــدي ســتة أشــهر ثــم اســتغنيت عنهــا فطلــب‬\n      ‫املدعــى عليــه منــي نقــل كفالتهــا إليــه فوافقــت علــى ذلــك ثــم أخذهــا‬\n      ‫منــي يف شــهر ربيــع األول مــن هــذا العــام ‪1433‬ه ـ لتجربتهــا متهيــد ًا لنقــل‬\n      ‫كفالتهــا إليــه واســتلم اجلــواز اخلــاص بهــا كذلــك لكنــه أغلــق هواتفــه‬\n      ‫ولــم يعــد يــرد علــى اتصاالتــي أطلــب إلزامــه بإعــادة هــذه اخلادمــة لــي‬\n      ‫هــذه دعــواي ثــم أفهمتــه بأنــه البــد مــن بيــان اســم هــذه اخلادمــة وإبــراز‬\n      ‫مســتند قدومهــا إلــى اململكــة ومســتند كفالتــه لهــا ففهــم ذلــك وطلــب‬\n      ‫إمهالــه إلحضــار ذلــك فأجيــب لذلــك ثــم رفعــت اجللســة ‪ .‬ثــم يف جلســة‬\n      ‫أخــرى حضــر املدعــي ولــم يحضــر املدعــى عليــه ولــم يقــدم عــذر ًا لتخلفــه‬\n      ‫ا إن اخلادمــة اســمها وهــي اثيوبيــة‬    ‫عــن احلضــور ثــم قــرر املدعــي قائ ـ ً‬\n      ‫اجلنســية وقــد دخلــت إلــى هــذه البــاد مبوجــب التأشــيرة رقــم (‪)......‬‬\n      ‫يف (‪1432/8/27‬هــ) لغــرض العمــل لــدي هكــذا قــرر ثــم أبــرز صــورة‬\n      ‫التأشــيرة املشــار إليهــا آنف ـ ًا والتقريــر الطبــي الصــادر لهــا للحصــول‬\n      ‫علــى إقامــة فوجدتهــا مطابقــة ملــا قــرره املدعــي آنف ـ ًا ‪ .‬ثــم يف جلســة‬\n      ‫أخــرى حضــر املدعــي ولــم يحضــر املدعــى عليــه ولــم يردنــا أي رد مــن‬\n      ‫شــرطة عنيــزة علــى خطابنــا املرفــوع إليهــم يف ‪1433/8/6‬ه ـ املطلــوب‬\n      ‫فيــه إحضــار املدعــى عليــه بنــاء علــى املــادة (‪ )101‬مــن نظــام املرافعــات‬\n      ‫الشــرعية ثــم جــرى ســؤال املدعــي ألديــك بينــة علــى مــا جــاء يف دعــواك‬\n\n\n‫‪347‬‬\n\f‫فقــال ليــس لــدي بينــة وأطلــب إحضــار املدعــى عليــه فــان أنكــر ذلــك‬\n‫فإننــي أطلــب توجيــه اليمــن إليــه ثــم رفعــت اجللســة إلحضــار املدعــى‬\n‫عليــه بنــاء علــى املــادة (‪ )101‬مــن نظــام املرافعــات الشــرعية وإبالغــه بــأن‬\n‫ال عــن أداء‬‫املدعــي قــد طلــب ميينــه وأنــه إذا لــم يحضــر فســوف يعــد نــاك ً‬\n‫اليمــن ‪ .‬ثــم يف جلســة أخــرى حضــر املدعــي ولــم يحضــر املدعــى عليــه‬\n‫وقــد وردنــا أصــل ورقــة التبليــغ مــن قســم محضــري اخلصــوم املتضمنــة‬\n‫اإلفــادة بأنــه مت االتصــال علــى األرقــام اخلاصــة باملدعــى عليــه فكانــت‬\n‫مقفلــة وأنــه مت الذهــاب إلــى منزلــة عــدة مــرات فلــم يوجــد بــه أحــد ‪ .‬أ ‪ .‬هـ‬\n‫‪ .‬ونظــرا ألن املدعــى عليــه غيــر متجــاوب فقــد أفهمــت املدعــي بــأن عليــه‬\n‫أن يحلــف ميينــا علــى مــا جــاء يف دعــواه ألن املدعــى عليــه يعــد نــاكال‬\n‫عــن أداء اليمــن وهــذان مــن مواضــع رد اليمــن ألن احلــق يعــرف مــن جهــة‬\n‫املدعــي ثــم قــرر املدعــي قائــا إننــي مســتعد ألداء اليمــن ثــم حلــف بــاهلل‬\n‫قائــا واهلل العظيــم إننــي اتفقــت مــع املدعــى عليــه علــى أن يأخــذ منــي‬\n‫اخلادمــة املذكــورة يف هــذه الدعــوى وهــي إثيوبيــة اجلنســية لتجربتهــا‬\n‫ثــم نقــل كفالتهــا إليــه واســتالمه جلوازهــا يف شــهر ربيــع األول مــن عــام‬\n‫‪1433‬ه ـ وأنهــا مازالــت عنــده ولــم ينقــل كفالتهــا أن هــذا كلــه صحيــح‬\n‫هكــذا حلــف فبنــاء علــى مــا ســبق مــن الدعــوى واإلجابــة ونظــرا ألن‬\n‫املدعــى عليــه قــد تبلــغ لشــخصه بــأول موعــد ولــم يحضــر أي جلســة وملــا‬\n‫جــاء يف املــادة (‪ )55‬مــن نظــام املرافعــات الشــرعية ولوائحــه التنفيذيــة‬\n‫وألن املدعــى عليــه يعتبــر نــاكال عــن أداء اليمــن وألن املدعــي قــد‬\n‫حلــف اليمــن الالزمــة شــرعا حســبما طلبــت منــه وألن هــذه الدعــوى‬\n‫ممــا يدخــل فيهــا رد اليمــن إلــى املدعــي ألن احلــق يعــرف مــن جهتــه‬\n‫كمــا نــص علــى ذلــك جمــع مــن احملققــن كشــيخ اإلســام ابــن تيميــة‬\n\n\n                                                                                         ‫‪348‬‬\n\f      ‫وابــن القيــم وملــا جــاء يف املــادة (‪ )2/103‬مــن نظــام املرافعــات الشــرعية‬\n      ‫لذلــك كلــه فقــد ألزمــت املدعــى عليــه بــان يعيــد اخلادمــة املذكــورة يف‬\n      ‫الدعــوى إلــى املدعــي وبذلــك حكمــت ويعــد احلكــم يف حقــه حضوريــا‬\n      ‫ثــم أمــرت بتســليم املدعــى عليــه نســخة مــن احلكــم عــن طريــق محضــري‬\n      ‫اخلصــوم لتقــدمي اعتراضــه خــال مــدة أقصاهــا ثالثــون يومــا مــن تاريــخ‬\n      ‫اســتالمه لــه وأنــه إذا لــم يقــدم اعتراضــه خــال هــذه املــدة فــإن حقــة‬\n      ‫يســقط يف التمييــز ويصبــح احلكــم مكتســبا القطعيــة وعليــه جــرى‬\n      ‫التوقيــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                      ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/03/15‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ويف يــوم الســبت املوافــق ‪1434/5/18‬ه ـ افتتحــت‬\n      ‫اجللســة يف الســاعة الثامنــة وخمســة وأربعــون دقيقــة بنــاء علــى ورود‬\n      ‫خطــاب مديــر شــرطة عنيــزة رقــم ‪ 3/16/2304/31‬يف ‪1434/5/12‬ه ـ‬\n      ‫واملتضمــن أنــه لــم يتــم تســليم صورة احلكم للمدعى عليــه ‪ ...‬رغم التردد‬\n      ‫علــى منزلــه أكثــر مــن مــرة ويف أوقــات مختلفــة وهواتفــه مغلقــة بصفــة‬\n      ‫مســتمرة أ‪.‬ه ـ ولذلــك فقــد أمــرت ببعــث املعاملــة حملكمــة االســتئناف‬\n      ‫بالقصيــم لتدقيــق احلكــم بنــاء علــى املــادة ‪ 5/179‬مــن نظــام املرافعــات‬\n      ‫الشــرعية ولوائحــه التنفيذيــة وصلــى اهلل وســلم علــى نبينــا محمــد حــرر‬\n                                                                 ‫يف ‪1434/5/18‬هـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ،‬يف يــوم األربعــاء املوافــق ‪1434/6/14‬ه ـ‬\n      ‫افتتحــت اجللســة يف الســاعة العاشــرة والنصــف صباحــا بنــاء علــى ورود‬\n      ‫املعاملــة مــن محكمــة االســتئناف بالقصيــم برقــم ‪ 341262902‬يف‬\n      ‫‪1434/6/11‬ه ـ مــزودة بقــرار أصحــاب الفضيلــة قضــاة االســتئناف‬\n      ‫بالدائــرة احلقوقيــة األولــى بالقصيــم رقــم ‪ 34228433‬يف ‪1434/6/3‬ه ـ‬\n\n\n‫‪349‬‬\n\f‫املقــرر فيــه املصادقــة علــى احلكــم أ ‪ .‬ه ـ ‪ .‬وقــد جــرى التهميــش بذلــك‬\n‫علــى الضبــط وســجله حســب التعليمــات وعليــه جــرى التوقيــع وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                       ‫حــرر يف ‪ 1434/06/14‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى نبينــا محمــد وعلى آلــه وصحبه‬\n‫وبعــد ‪،‬فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة األولــى مبحكمــة‬\n‫االســتئناف مب ـ ــنطقة القصـ ــيم علــى الـمـعــامـلـ ــة ال ــواردة م ــن فـض ــيلة‬\n‫رئيــس احملكمــة العامــة مبحافظــة عنيــزة برقــم (‪ )33921012‬وتــاري ـ ــخ‬\n‫‪1434/5/21‬ه ـ ؛ الـمح ــالة إلـيـنـ ــا بـرق ــم (‪ )34240941‬الـمـرف ــق به ــا‬\n‫الـص ــك الـمسج ــل بـرق ــم (‪ )3462374‬وتاريخ ‪1434/3/15‬هـ ؛ الصادر‬\n‫مــن فضيلــة الشــيخ ‪ ......‬القاضــي باحملكمــة؛ اخلــاص بدعــوى ‪ ......‬ضــد‬\n‫‪ ، ......‬بشــأن املطالبــة بإعــادة خادمــة أثيوبيــة‪ ،‬وقــد تضمــن الصــك‬\n‫حكــم فضيلتــه بإلــزام املدعــى عليــه بــأن يعيــد اخلادمــة إلــى املدعــي؛‬\n‫علــى النحــو املفصــل فيــه‪ .‬وبدراســة الصــك وصــورة ضبطــه وأوراق‬\n‫املعاملــة تقــرر املصادقــة علــى احلكــم‪ .‬واهلل املوفــق‪ ،‬وصلــى اهلل علــى‬\n                                         ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                        ‫‪350‬‬\n\f351\n\f352\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":345,"source_page_end":352,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5b2679c38dc568466615e684aee2e21fda87bb9be8bc955ef205e246c2a05be2","normalized_text_hash":"d5b0666cc920d065b82037dbc65cee90b3495644e9f08ff5fec85d36c4634f75","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p345-3462374"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
